function conductor(){ return libIcon("musDirettore"); }   /* direttore: sempre illustrato (sostituisce lo schema); podio/leggio/sgab disegnati a parte nel draw */
   /* podio con leggìo incorporato (icona catalogo) */
function podioBase(){ return bar(0,0,120,120,'ic fFloor',3)+bar(0,0,104,104,'ic thin',2); }   /* piattaforma 120×120 = footprint del direttore */
function dirSize(it){ return (it&&it.podio) ? [120,120] : [90,114]; }   /* direttore: footprint = illustrazione musDirettore (90×114); col podio = piattaforma 120×120 */
/* divide la postazione chitarra nei suoi elementi (chitarra, sedia, leggio, ampli) come item indipendenti */
function explodeGuitar(){
  var it=getSel(), t=it&&TYPES[it.type]; if(!t||!t.gtr) return;
  var kind=t.gtr, base=it.label?it.label+" ":"", pcs=[], seated=it.sedia;
  pcs.push({type:it.type, dx:seated?GTR_GX:0, dy:seated?GTR_GY:0, label:it.label||"", extra:{sedia:false,leggio:false,ampli:false}});   /* chitarra (di fianco e a livello sedia) */
  if(seated) pcs.push({type:"sedia", dx:0, dy:-25, label:""});
  if(it.leggio) pcs.push({type:"leggio", dx:0, dy:gtrLeggioY(it,kind), label:""});
  if(it.ampli) pcs.push({type:"comboamp",dx:-43, dy:-88, rot:-30, label:base+"Ampli"});
  if(it.pedaliera) pcs.push({type:"pedaliera", dx:0, dy:(seated?72:64), label:base+"Pedalboard"});
  var rot=(it.rot||0)*Math.PI/180, c=Math.cos(rot), s=Math.sin(rot), made=[];
  pcs.forEach(function(pc){ var T=TYPES[pc.type]; if(!T) return;
    var ni={id:uid(), type:pc.type, x:Math.round(it.x+(pc.dx*c-pc.dy*s)), y:Math.round(it.y+(pc.dx*s+pc.dy*c)),
            rot:((it.rot||0)+(pc.rot||0)), w:T.w, d:T.d, label:pc.label||""};
    if(T.riser) ni.h=T.h||40;
    if(pc.extra) Object.keys(pc.extra).forEach(function(k){ ni[k]=pc.extra[k]; });
    made.push(ni);
  });
  if(made.length<2) return;
  state.items=state.items.filter(function(x){ return x.id!==it.id; });
  made.forEach(function(n){ state.items.push(n); });
  selSet={}; made.forEach(function(n){ selSet[n.id]=true; }); sel=made[made.length-1].id;
  render(); save();
}
/* postazione singola cello/basso CENTRATA (sgabello al centro dietro lo strumento) → la doppia resta simmetrica */
function celloPost(){
  return shadow(42,58,0,8)+bar(0,-36,44,44,'ic fBlack',9)+bar(0,-60,44,8,'ic fill',4)+
    '<g transform="translate(0,22) rotate(-24)">'+violino(1.0,'fWood')+'</g>';
}
function bassPost(){
  return shadow(54,60,0,6)+circ(0,-44,16,'ic fBlack')+circ(0,-44,5,'dotS')+
    '<g transform="translate(0,14) rotate(-12)">'+violino(1.45,'fWoodD')+'</g>';
}
function doubleStringPost(kind, dx){
  dx=dx||33;   /* sep/2 di default = 65/2 ≈ 33 */
  var lr, legY=38;
  /* tutti gli strumenti PARALLELI (nessuna specchiatura) */
  function parallel(inner, rotL, rotR, ty){ var t=ty||0;
    /* destra prima (sotto), sinistra dopo (in primo piano) */
    return '<g transform="translate('+dx+','+t+') rotate('+(rotR||0)+')">'+inner+'</g>'+
           '<g transform="translate('+(-dx)+','+t+') rotate('+(rotL||0)+')">'+inner+'</g>'; }
  if(kind==="vln1"||kind==="vln2"){ lr=parallel(postaz(gVln(0.45)), -8, 8); }
  else if(kind==="vla"){ lr=parallel(postaz(gVln(0.53)), -8, 8); }
  else if(kind==="vc"){ legY=54; lr=parallel(celloPost(), -7, 7, 4); }
  else { legY=58; lr=parallel(bassPost(), -7, 7, 7); }   /* cb */
  return lr+'<g transform="translate(0,'+legY+')">'+leggioGlyph(0)+'</g>';
}
/* sedia singola (vista dall'alto) */
function chairSvg(cx){ return bar(cx,-22,46,46,'ic fBlack',9)+bar(cx,-48,46,9,'ic fill',4); }
/* seduta a CONTORNO CHIARO: per le postazioni con icone realistiche, così lo strumento sopra resta leggibile */
function seatLight(cx){ return bar(cx,-22,46,46,'ic soft',9)+bar(cx,-48,46,9,'ic soft',4); }
/* postazione configurabile: sedia/leggio/doppia secondo i flag dell'item.
   dblKind: vln1|vln2|vla|vc|cb usano il disegno doppio dedicato; altrimenti doppio generico.
   realistic=true → seduta chiara (icone realistiche). */
function station(it, glyph, dblKind, realistic){
  it=it||{};
  /* Unifica icone (15/07): aspetto ILLUSTRATO (default) → disegna l'illustrazione del musicista
     invece dello schema. Doppia = 2 illustrazioni a ±sep/2, la 2ª specchiata. Micro/canali/numerazione
     restano quelli della postazione (l'illustrazione è solo il look). */
  var art = postArt(it);
  if(art){
    /* leggio davanti alla figura (verso il pubblico, +y) se attivo — l'illustrazione non lo include */
    var ad = (TYPES[art] && TYPES[art].d) ? TYPES[art].d : 80;
    var leg = (it.leggio!==false) ? '<g transform="translate(0,'+Math.round(ad*0.52)+')">'+leggioGlyph(0)+'</g>' : '';
    if(it.doppia){
      var hx = it.sep ? it.sep/2 : 45;   /* 2 musicisti affiancati, ENTRAMBI verso il pubblico (non specchiati), */
      var conv = 12;                      /* leggermente convergenti verso il centro, come lo schematico */
      /* destra prima (sotto), sinistra dopo (in primo piano) */
      return '<g transform="translate('+hx+',0) rotate('+conv+')">'+libIcon(art)+'</g>'+
             '<g transform="translate('+(-hx)+',0) rotate('+(-conv)+')">'+libIcon(art)+'</g>'+leg;
    }
    return libIcon(art)+leg;
  }
  var seat = realistic ? seatLight : chairSvg;
  if(it.doppia){
    var half = it.sep ? it.sep/2 : null;
    if(/^(vln1|vln2|vla|vc|cb)$/.test(dblKind||"")) return realistic ? doubleStringPostLib(dblKind, half) : doubleStringPost(dblKind, half);
    var dx = half || 45, conv=12;   /* sedie convergenti verso il centro */
    /* destra prima (sotto), sinistra dopo (in primo piano) */
    return '<g transform="translate('+dx+',0) rotate('+conv+')">'+seat(0)+glyph+'</g>'+
      '<g transform="translate('+(-dx)+',0) rotate('+(-conv)+')">'+seat(0)+glyph+'</g>'+
      '<g transform="translate(0,38)">'+leggioGlyph(0)+'</g>';
  }
  /* archi singoli realistici: layout dedicato a scala reale (sedia/sgabello + strumento + leggio davanti) */
  var sk=realistic && strKeyOf(dblKind);
  if(sk) return archiStation(it, sk);
  /* postazione singola generica: glifo a scala reale + sedia + leggio */
  return (it.sedia!==false?seat(0):'')+glyph+(it.leggio!==false?leggioGlyph(38):'');
}
/* postazione a 2 con icone realistiche (archi): 2 sedute chiare + 2 strumenti + 1 leggio */
/* archi a SCALA REALE: sedia/sgabello + strumento + leggio davanti. Il contrabbasso (grande) sta su sgabello
   ed è spostato a lato per non coprire stool e leggio. legY segue l'altezza reale dello strumento. */
var STRING_CFG = {
  violino:    {legY:46, stool:false, side:0},
  viola:      {legY:50, stool:false, side:0},
  violoncello:{legY:74, stool:false, side:0},
  contrabbasso:{legY:110, stool:true, side:0, stoolX:-45, stoolY:-55}   /* sgabello sx/manico; leggio vicino alla base (+90) */
};
function strKeyOf(kind){ return {vln1:'violino',vln2:'violino',vla:'viola',vc:'violoncello',cb:'contrabbasso'}[kind||""]; }
function stringSeat(cfg){ var sx=cfg.stoolX||0,sy=cfg.stoolY||-26; return cfg.stool ? (circ(sx,sy,17,'ic soft')+circ(sx,sy,5,'dotS')) : seatLight(0); }   /* sgabello (cerchio) o sedia chiara */
function stringInstr(key){ return libIcon(key); }   /* scala reale (nessun ridimensionamento) */
/* postazione singola arco (scala reale) */
function archiStation(it, key){
  var cfg=STRING_CFG[key]||{legY:40,side:0};
  var s = (it.sedia!==false ? stringSeat(cfg) : '');
  s += '<g transform="translate('+(cfg.side||0)+',0)">'+stringInstr(key)+'</g>';
  if(it.leggio!==false) s += '<g transform="translate(0,'+cfg.legY+')">'+leggioGlyph(0)+'</g>';
  return s;
}
function doubleStringPostLib(kind, dx){
  dx=dx||33;
  var key=strKeyOf(kind)||'violino', cfg=STRING_CFG[key]||{legY:38,side:0}, conv=12;   /* sedie convergenti verso il centro */
  var inst=stringInstr(key);
  /* nel doppio lo sgabello/sedia è sempre al centro locale (non usa stoolX del singolo) */
  var dblSeat=cfg.stool?(circ(0,-26,17,'ic soft')+circ(0,-26,5,'dotS')):seatLight(0);
  function side(sx,ang){ return '<g transform="translate('+sx+',0) rotate('+ang+')">'+dblSeat+inst+'</g>'; }
  /* destra prima (sotto), sinistra dopo (in primo piano) */
  return side(dx,conv)+side(-dx,-conv)+'<g transform="translate(0,'+cfg.legY+')">'+leggioGlyph(0)+'</g>';
}
/* ── Timpani realistici (libreria icon-prototype): ingombri reali caldaia+telaio ── */
var TIMP_MODELS={ t51:{icon:"timp51",d:57,lbl:'20\u2033'}, t58:{icon:"timp58",d:65,lbl:'23\u2033'},
  t66:{icon:"timp66",d:73,lbl:'26\u2033'}, t74:{icon:"timp74",d:81,lbl:'29\u2033'}, t81:{icon:"timp81",d:88,lbl:'32\u2033'} };
/* set standard per numero (dall'acuto al grave) e slot ad arco (posizioni dei set approvati in libreria) */
var TIMP_SETS={ 1:["t74"], 2:["t74","t81"], 3:["t66","t74","t81"], 4:["t58","t66","t74","t81"], 5:["t51","t58","t66","t74","t81"] };
var TIMP_R_ARC={1:85, 2:85, 3:90, 4:100, 5:110};   /* raggio dell'arco dei centri, per numero */
/* orient: "americano" = grave alla sinistra del musicista (in pianta a destra, musicista a nord);
   "tedesco" = specchiato. layout: "arco" (semicerchio ATTORNO allo sgabello, pedali verso il musicista) | "linea".
   Sgabello del timpanista dentro l'arco (p.stool!==false). */
function timpSlots(pp){
  var n=Math.max(1,Math.min(5,pp.count||2)), gap=3, out=[], i;
  var ms=TIMP_SETS[n].map(function(k){ return TIMP_MODELS[k]; });
  if(pp.layout==="linea"){
    var x=0, sx=0, topy=1e9;
    ms.forEach(function(m){ var r=m.d/2; out.push({icon:m.icon,lbl:m.lbl,r:r,x:x+r,y:0,rot:0}); x+=m.d+4; });
    out.forEach(function(t){ sx+=t.x; topy=Math.min(topy,t.y-t.r); });
    if(pp.stool!==false || pp.mus!==false) out.push({r:20,x:Math.round(sx/n*10)/10,y:topy-24,rot:0,seat:true});   /* posto del musicista: persona e/o sgabello (deciso in drawTimpani) */
  } else {
    /* arco: centri su una circonferenza, concavità verso il musicista (a nord), timpani tangenti+gap */
    var R=TIMP_R_ARC[n], dth=[], span=0;
    for(i=0;i<n-1;i++){ var corda=ms[i].d/2+ms[i+1].d/2+gap; dth.push(2*Math.asin(corda/2/R)); span+=dth[i]; }
    var th=-span/2, ths=[th];
    for(i=0;i<n-1;i++){ th+=dth[i]; ths.push(th); }
    for(i=0;i<n;i++){ var r=ms[i].d/2;
      out.push({icon:ms[i].icon,lbl:ms[i].lbl,r:r,
        x:Math.round(R*Math.sin(ths[i])*10)/10, y:Math.round(R*Math.cos(ths[i])*10)/10,
        rot:Math.round(-ths[i]*180/Math.PI)});   /* pedale verso il musicista */
    }
    if(pp.stool!==false || pp.mus!==false){
      var inner=1e9;   /* bordo interno dei timpani frontali: il posto ci si accosta */
      for(i=0;i<n;i++){ if(Math.abs(ths[i])<1.05) inner=Math.min(inner,(R-ms[i].d/2)*Math.cos(ths[i])); }
      if(inner===1e9) inner=R-ms[0].d/2;
      out.push({r:20,x:0,y:Math.round((inner-24)*10)/10,rot:0,seat:true});   /* posto del musicista: persona e/o sgabello */
    }
  }
  if(pp.orient==="tedesco"){ var mn=1e9,mx=-1e9; out.forEach(function(t){ mn=Math.min(mn,t.x); mx=Math.max(mx,t.x); });
    out.forEach(function(t){ t.x=Math.round((mn+mx-t.x)*10)/10; t.rot=-t.rot; }); }
  return out;
}
function timpBBox(L){ var minx=1e9,maxx=-1e9,miny=1e9,maxy=-1e9;
  L.forEach(function(t){ minx=Math.min(minx,t.x-t.r); maxx=Math.max(maxx,t.x+t.r); miny=Math.min(miny,t.y-t.r); maxy=Math.max(maxy,t.y+t.r); });
  return {w:maxx-minx, d:maxy-miny, cx:(minx+maxx)/2, cy:(miny+maxy)/2};
}
/* Glifi strumento in scala (cm reali) */
function gVln(s){ return '<g transform="translate(28,-14) rotate(38)">'+violino(s,'fWood')+'</g>'; }
function gCorno(){ return libIcon('corno'); }   /* corno francese: icona dalla libreria */         /* luce */

/* Corpo violino/cello/contrabbasso (vista dall'alto, scala s: 1 = cello). Tutto vettoriale, in scala.
   Dettaglio: cassa con punte/centro, tastiera in ebano, 4 corde, ponticello, cordiera, riccio, f-fori. */
function violino(s,woodCls){
  function n(v){ return Math.round(v*s*10)/10; }
  var sw=Math.max(0.45, Math.round(0.7*s*10)/10);   /* spessore corda in scala */
  var body='<path class="ic '+(woodCls||'fWood')+'" d="M 0,'+n(-40)+' C '+n(14)+','+n(-40)+' '+n(20)+','+n(-31)+' '+n(18)+','+n(-22)+
    ' C '+n(17)+','+n(-15)+' '+n(11)+','+n(-13)+' '+n(12)+','+n(-7)+
    ' C '+n(14)+','+n(-1)+' '+n(21)+','+n(2)+' '+n(22)+','+n(11)+
    ' C '+n(23)+','+n(24)+' '+n(12)+','+n(30)+' 0,'+n(30)+
    ' C '+n(-12)+','+n(30)+' '+n(-23)+','+n(24)+' '+n(-22)+','+n(11)+
    ' C '+n(-21)+','+n(2)+' '+n(-14)+','+n(-1)+' '+n(-12)+','+n(-7)+
    ' C '+n(-11)+','+n(-13)+' '+n(-17)+','+n(-15)+' '+n(-18)+','+n(-22)+
    ' C '+n(-20)+','+n(-31)+' '+n(-14)+','+n(-40)+' 0,'+n(-40)+' Z"/>';
  /* bordo interno (filetto) per profondità */
  var purf='<path class="ic thin" fill="none" opacity="0.45" d="M 0,'+n(-37)+' C '+n(12)+','+n(-37)+' '+n(16)+','+n(-30)+' '+n(15)+','+n(-22)+
    ' C '+n(14)+','+n(-14)+' '+n(9)+','+n(-12)+' '+n(10)+','+n(-7)+
    ' C '+n(11)+','+n(0)+' '+n(18)+','+n(3)+' '+n(19)+','+n(11)+
    ' C '+n(20)+','+n(22)+' '+n(10)+','+n(27)+' 0,'+n(27)+
    ' C '+n(-10)+','+n(27)+' '+n(-20)+','+n(22)+' '+n(-19)+','+n(11)+
    ' C '+n(-18)+','+n(3)+' '+n(-11)+','+n(0)+' '+n(-10)+','+n(-7)+
    ' C '+n(-9)+','+n(-12)+' '+n(-14)+','+n(-14)+' '+n(-15)+','+n(-22)+
    ' C '+n(-16)+','+n(-30)+' '+n(-12)+','+n(-37)+' 0,'+n(-37)+' Z"/>';
  /* tastiera in ebano: dal ponticello al capotasto (oltre la cassa) */
  var fingerboard='<path class="ic fill" d="M '+n(-3)+','+n(-2)+' C '+n(-3.4)+','+n(-22)+' '+n(-2.5)+','+n(-46)+' '+n(-2.3)+','+n(-54)+
    ' L '+n(2.3)+','+n(-54)+' C '+n(2.5)+','+n(-46)+' '+n(3.4)+','+n(-22)+' '+n(3)+','+n(-2)+' Z"/>';
  /* riccio + cavigliere */
  var scroll='<circle class="ic fWoodL" cx="0" cy="'+n(-57)+'" r="'+n(4)+'"/><circle class="ic thin" fill="none" cx="0" cy="'+n(-57)+'" r="'+n(1.8)+'"/>';
  /* 4 corde dal cordiera al capotasto (si restringono verso l'alto) */
  var strings='';
  [-1.9,-0.65,0.65,1.9].forEach(function(xx){ strings+='<line x1="'+n(xx)+'" y1="'+n(27)+'" x2="'+n(xx*0.45)+'" y2="'+n(-53)+'" stroke="#efe7d2" stroke-width="'+sw+'" stroke-linecap="round"/>'; });
  var bridge=bar(0,n(7),n(15),n(2.6),'ic fill',1);
  var tail='<path class="ic fill" d="M '+n(-3.4)+','+n(26)+' L '+n(3.4)+','+n(26)+' L '+n(2)+','+n(38)+' L '+n(-2)+','+n(38)+' Z"/>';
  var fholes='<path class="fhole" d="M '+n(-7)+','+n(-3)+' q '+n(-2.5)+','+n(7)+' 0,'+n(13)+'"/>'+
    '<path class="fhole" d="M '+n(7)+','+n(-3)+' q '+n(2.5)+','+n(7)+' 0,'+n(13)+'"/>';
  return body+purf+fholes+fingerboard+scroll+strings+bridge+tail;
}
/* Piano a coda parametrico — pianta reale: fascia (spine) DRITTA a sx, coda arrotondata
   al fondo, bentside a destra con ansa a S verso il blocchetto tastiera. Ancore normalizzate
   prese dalla pianta Steinway. Tastiera a tutta larghezza sul fronte (+y). */
function pianoCoda(it){
  var w2=it.w/2, d2=it.d/2;
  function P(x,y){ return (x*w2).toFixed(1)+','+(y*d2).toFixed(1); }
  var p='M '+P(-1,1)+
    ' L '+P(-1,-0.66)+                                          /* fascia dritta (lato bassi) */
    ' C '+P(-1,-0.90)+' '+P(-0.82,-1)+' '+P(-0.50,-1)+          /* spalla coda sx */
    ' C '+P(-0.20,-1)+' '+P(0.10,-0.93)+' '+P(0.34,-0.79)+      /* coda → inizio bentside */
    ' C '+P(0.60,-0.63)+' '+P(0.79,-0.40)+' '+P(0.875,-0.18)+   /* curva grande */
    ' C '+P(0.94,-0.01)+' '+P(0.965,0.10)+' '+P(0.945,0.215)+   /* rientro ansa */
    ' C '+P(0.935,0.30)+' '+P(0.962,0.365)+' '+P(1,0.44)+       /* ansa a S → blocchetto */
    ' L '+P(1,1)+' Z';
  var s='<path class="ic fBlack" d="'+p+'"/>';                                               // cassa nera lucida
  s+='<g transform="scale(0.93)"><path d="'+p+'" fill="url(#gBoard)" stroke="#2a2c30" stroke-width="1.2"/></g>'; // tavola armonica
  for(var i=0;i<7;i++){                                                                       // corde a ventaglio (bassi più lunghi)
    var x=(-0.60+i*0.125)*w2, top=-(0.84-i*0.052)*d2;
    s+='<line class="pstr" x1="'+(x-0.04*w2)+'" y1="'+top+'" x2="'+x+'" y2="'+(d2*0.52)+'"/>';
  }
  s+=lin(-0.72*w2,0.30*d2,0.80*w2,0.30*d2,'pstr');                                            // barra smorzatori
  s+=lin(-0.55*w2,-0.30*d2,-0.10*w2,0.30*d2,'pstr')+lin(0.15*w2,-0.52*d2,0.45*w2,0.05*d2,'pstr'); // crociere piastra
  s+='<path class="hilite" d="M '+(-w2+5)+','+(d2-30)+' L '+(-w2+5)+','+(-d2*0.62)+'"/>';      // riflesso fascia
  s+=lin(-w2*0.35,d2-27,w2*0.35,d2-27,'ic thin');                                              // leggio
  s+=bar(0,d2-17.5,it.w-14,5,'ic fill',1)+bar(0,d2-9,it.w-14,14,'ic thin',2);                  // ciglio + tastiera
  for(var k=-2;k<=2;k++){ s+=bar(k*0.31*it.w*0.5,d2-9,9,7,'ic fill',1); }                      // gruppi tasti neri
  return s;
}
/* Tastiera a barre graduate (xilofono/marimba): cornice trapezia + barre */

/* ============ CATALOGO (dimensioni REALI in cm, verificate — vedi RICERCA.md) ============ */
/* Passacavi (cable ramp) giallo/nero, gamma tipo Defender/Adam Hall — varianti reali (dim. cm, n° canali). */
var RAMP_TYPES = {
  micro:{nome:"Micro (pedonale)",  w:100, d:28, ch:2},
  midi: {nome:"Midi (carrabile)",  w:88,  d:54, ch:5},
  xxl:  {nome:"XXL (cavi grossi)", w:88,  d:72, ch:5, big:true},
  end:  {nome:"Rampa terminale",   w:54,  d:26, ch:0, end:true}
};
/* disegno parametrico (top-down, centrato): base nera + coperchio giallo alta-visibilità + N canali
   + incastri modulari; asse lungo = w (cavi lungo x), spalle carrabili in alto/basso, ends a sx/dx. */
function drawCableRamp(it){
  var cfg=RAMP_TYPES[it.rampType]||RAMP_TYPES.midi, w=it.w||cfg.w, d=it.d||cfg.d;
  var YEL="#efc31f", BLK="#1c1c1c", GRV="#3a3a3a";
  var xL=-w/2, xR=w/2, yT=-d/2, yB=d/2;
  if(cfg.end){   /* rampa terminale = trapezio: alto al lato modulare (sx), sottile a terra (dx) */
    var thin=Math.max(4, d*0.22);
    var s='<path fill="'+BLK+'" d="M '+xL+','+yT+' L '+xR+','+(-thin/2)+' L '+xR+','+(thin/2)+' L '+xL+','+yB+' Z"/>';
    s+='<path fill="'+YEL+'" d="M '+(xL+5)+','+(yT+5)+' L '+(xR-4)+','+(-thin/2+2)+' L '+(xR-4)+','+(thin/2-2)+' L '+(xL+5)+','+(yB-5)+' Z"/>';
    s+='<line x1="'+xL+'" y1="'+(yT+d*0.4)+'" x2="'+xL+'" y2="'+(yB-d*0.4)+'" stroke="'+YEL+'" stroke-width="4"/>';
    return s;
  }
  var ML=cfg.w, n=Math.max(1, Math.round(w/ML));   /* n° moduli standard nella tratta */
  var rx=Math.min(9, d*0.13);
  var s='<rect x="'+xL+'" y="'+yT+'" width="'+w+'" height="'+d+'" rx="'+rx+'" fill="'+BLK+'"/>';
  var bev=Math.max(5, d*0.17);   /* spalle nere = rampa carrabile (alto/basso) */
  s+='<rect x="'+(xL+7)+'" y="'+(yT+bev)+'" width="'+(w-14)+'" height="'+(d-2*bev)+'" rx="4" fill="'+YEL+'"/>';
  var nc=cfg.ch, top=yT+bev+(d-2*bev)*0.18, bot=yB-bev-(d-2*bev)*0.18, gap=(nc>1)?(bot-top)/(nc-1):0;
  for(var i=0;i<nc;i++){ var y=(nc===1)?0:(top+i*gap);
    s+='<line x1="'+(xL+13)+'" y1="'+y+'" x2="'+(xR-13)+'" y2="'+y+'" stroke="'+GRV+'" stroke-width="'+(cfg.big?5:2.6)+'" stroke-linecap="round"/>'; }
  for(var m=1;m<n;m++){ var xs=xL+m*ML;   /* giunzione a coda di rondine tra i moduli */
    s+='<path fill="none" stroke="'+BLK+'" stroke-width="2.5" d="M '+xs+','+yT+' l 6,'+(d*0.28).toFixed(1)+' l -12,'+(d*0.44).toFixed(1)+' l 6,'+(d*0.28).toFixed(1)+'"/>'; }
  s+='<line x1="'+xL+'" y1="'+(yT+d*0.38)+'" x2="'+xL+'" y2="'+(yB-d*0.38)+'" stroke="'+YEL+'" stroke-width="3"/>';
  s+='<line x1="'+xR+'" y1="'+(yT+d*0.38)+'" x2="'+xR+'" y2="'+(yB-d*0.38)+'" stroke="'+YEL+'" stroke-width="3"/>';
  if(n>1) s+='<text x="0" y="'+(yT-6)+'" text-anchor="middle" font-size="18" font-weight="700" fill="#1c1c1c" font-family="-apple-system,Segoe UI,sans-serif">'+((w/100).toFixed(1)).replace(".",",")+' m</text>';   /* lunghezza reale della tratta sul palco (non il n° moduli) */
  return s;
}
/* n° moduli di una tratta di passacavi (per etichetta/STATO/rider) */
function rampModules(it){ if(it.type!=="cableramp") return 0; var cfg=RAMP_TYPES[it.rampType]||RAMP_TYPES.midi; if(cfg.end) return 1; return Math.max(1, Math.round((it.w||cfg.w)/cfg.w)); }
/* Gazebo/tenda: reso come TELAIO (perimetro + montanti agli angoli + falde del tetto a linee) —
   NON occlude gli elementi sotto (come la copertura palco). Configurabile per taglia + resize libero. */
var GAZEBO_SIZES = [[300,300],[300,450],[300,600],[400,400],[400,800]];   /* taglie evento più comuni (cm) */
function gazLabel(w,d){ function f(n){ return (Math.round(n/10)/10).toString().replace(".",","); } return f(w)+"×"+f(d); }
function drawGazebo(it, opts){
  opts=opts||{};
  var w=it.w||300, d=it.d||300, xL=-w/2, xR=w/2, yT=-d/2, yB=d/2;
  var FR="#8f979e", DIAG="#c3c8cd", POST="#6f767d";
  var s='<rect x="'+xL+'" y="'+yT+'" width="'+w+'" height="'+d+'" rx="6" fill="none" stroke="'+FR+'" stroke-width="4"/>';
  s+='<path fill="none" stroke="'+DIAG+'" stroke-width="2" d="M '+xL+','+yT+' L 0,0 L '+xR+','+yT+' M '+xL+','+yB+' L 0,0 L '+xR+','+yB+'"/>';   /* falde del tetto verso il colmo */
  var ps=Math.max(12, Math.min(w,d)*0.05);   /* montanti angolari */
  [[xL,yT],[xR,yT],[xL,yB],[xR,yB]].forEach(function(p){ s+='<rect x="'+(p[0]-ps/2)+'" y="'+(p[1]-ps/2)+'" width="'+ps+'" height="'+ps+'" rx="2" fill="'+POST+'"/>'; });
  if(opts.cross){ var cs=Math.min(w,d)*0.14; s+='<rect x="'+(-cs/2).toFixed(1)+'" y="'+(-cs*0.17).toFixed(1)+'" width="'+cs.toFixed(1)+'" height="'+(cs*0.34).toFixed(1)+'" rx="2" fill="#dc2626"/><rect x="'+(-cs*0.17).toFixed(1)+'" y="'+(-cs/2).toFixed(1)+'" width="'+(cs*0.34).toFixed(1)+'" height="'+cs.toFixed(1)+'" rx="2" fill="#dc2626"/>'; }   /* croce = tenda medica (PMA) */
  return s;   /* etichetta (nome + misura) disegnata a livello app in itemMarkup, non qui: unica e posizionabile sul lato */
}
var GAZ_TYPES = { gazebo33:1, tenda63:1, pma:1 };   /* coperture "a telaio": etichetta unica nome+dimensione, taglia+lato configurabili */
function gazStructLabel(it){   /* nome base (editabile) + dimensione live, es. "Gazebo 3×6 m" */
  var t=TYPES[it.type]||{}, base=(it.label!=null&&it.label!=='')?it.label:(t.defLabel||"Gazebo");
  return base+" "+gazLabel(it.w||t.w||300, it.d||t.d||300)+" m";
}
function isCover(it){ return !!GAZ_TYPES[it.type] || (typeof it.type==="string" && it.type.indexOf("roof")===0); }   /* coperture = gazebo/tende/PMA + copertura palco (roof*) */
var coverLayerUI={vis:true, op:100, lock:false};   /* layer Coperture (runtime, non persistito): visibilità + opacità + lucchetto come gli altri layer */
function coverH(it){ return (it&&it.h!=null) ? it.h : (String(it&&it.type).indexOf("roof")===0 ? 500 : 250); }   /* luce sotto la copertura (cm): default 5 m per la copertura palco, 2,5 m per gazebo/tende */
function ptInCover(px,py,cov){ var dx=px-cov.x, dy=py-cov.y, a=-((cov.rot||0)*Math.PI/180), c=Math.cos(a), s=Math.sin(a); return Math.abs(dx*c-dy*s)<=(cov.w||0)/2 && Math.abs(dx*s+dy*c)<=(cov.d||0)/2; }   /* punto nel rettangolo (ruotato) della copertura */
function coverAtRisk(it){ return !isCover(it) && (isAudioSource(it) || wattOf(it)>0 || OUT_SET[it.type]!=null || it.type==="mixer" || it.type==="foh" || it.type==="rack" || cabIsBox(it)); }   /* attrezzatura audio/elettrica = "teme la pioggia" */
function coveredBy(cov){ return (state.items||[]).filter(function(x){ return coverAtRisk(x) && ptInCover(x.x,x.y,cov); }); }
/* ===== ASTA GIGANTE (29/07) — pianta in scala reale, vista dall'alto, fronte palco = +y =====
   È la giraffa da coro/orchestra: treppiede grande a doppia crociera + braccio telescopico con
   contrappeso. Misure prese dai datasheet dei modelli di riferimento, NON a occhio:
     · K&M 20811  (k-m.de)  base Ø 1485 mm · altezza 1850-4400 mm · 11 kg · braccio opzionale 21231
     · Proel PRO300BK       base Ø 1500 mm · altezza 1600-2350 mm · braccio 1350-2050 mm · 5,2 kg
     · Proel PRO400BK       base Ø 1060 mm · altezza 1510-2400 mm · braccio 1400-2350 mm · 12 kg
     · K&M 21231 (braccio)  1070-1870 mm · 5,32 kg · contrappeso regolabile · per 20811 e 21411
   SCELTE: base Ø150 = i due modelli col treppiede più largo (20811 1485, PRO300 1500), arrotondati.
   Sbraccio disegnato 140 cm = la sola quota dentro TUTTE e tre le corse documentate del braccio
   (107-187 · 135-205 · 140-235); è la proiezione orizzontale, il braccio vero è più lungo perché
   scende sul coro. Tubo del braccio Ø5 cm = dato di targa del PRO400BK.
   Il resto (spessore delle gambe, lunghezza del codolo del contrappeso) è tratto grafico: non è
   dichiarato da nessun costruttore e qui non lo si inventa come misura.
   Confronto col resto del catalogo: una giraffa normale ha base Ø 680 mm (Proel RSM180) e braccio
   435-745 mm (K&M 210/9) — la gigante è più del doppio in entrambe le quote, e si deve vedere. */
/* base = Ø del treppiede aperto · sbraccio = proiezione orizzontale del braccio dal palo.
   Da qui discendono l'ingombro (w = base, d = mezza base dietro il palo + sbraccio) e il disegno:
   una sola fonte, così pianta e misure non possono divergere. */
var ASTAG = { base:150, sbraccio:140 };
ASTAG.w = ASTAG.base;
ASTAG.d = ASTAG.base/2 + ASTAG.sbraccio;            /* 215 cm */
ASTAG.hubY = -ASTAG.d/2 + ASTAG.base/2;             /* -32,5: il palo NON è al centro del riquadro */
function drawAstaGigante(){
  function n(v){ return (Math.round(v*10)/10); }
  var R=ASTAG.base/2, hubY=ASTAG.hubY;
  var LEG="#1a1c1e", HL="#41464b", RUB="#0e0f10", HUB="#26292c", HUB2="#34383c",
      BOOM="#202326", BOOM2="#2a2d31", CW="#101214", CW2="#2c3033", GR="#565b60", GR2="#8b9196";
  /* piedi del treppiede: uno indietro (fronte palco = +y, quindi -y è dietro), due avanti a ±120° */
  var feet=[[0,hubY-R],[R*0.866,hubY+R*0.5],[-R*0.866,hubY+R*0.5]], s="";
  feet.forEach(function(f){   /* gamba come tubo pieno, non come linea: alla scala del palco si vede lo spessore */
    var ux=f[0]/R, uy=(f[1]-hubY)/R, px=-uy*1.6, py=ux*1.6;   /* semilarghezza tubo 1,6 cm */
    s+='<path fill="'+LEG+'" d="M '+n(px)+','+n(hubY+py)+' L '+n(f[0]+px)+','+n(f[1]+py)+
       ' L '+n(f[0]-px)+','+n(f[1]-py)+' L '+n(-px)+','+n(hubY-py)+' Z"/>';
  });
  /* doppia crociera: è la firma dei treppiedi giganti (K&M la dichiara "tube legs with double cross
     braces" su 20811 e 21411) ed è ciò che distingue questa pianta da quella della giraffa normale */
  [0.55,0.80].forEach(function(k){   /* abbastanza larghe da non impastarsi col perno e col contrappeso */
    var p=feet.map(function(f){ return [n(f[0]*k), n(hubY+(f[1]-hubY)*k)]; });
    var dd='M '+p[0][0]+','+p[0][1]+' L '+p[1][0]+','+p[1][1]+' L '+p[2][0]+','+p[2][1]+' Z';
    s+='<path fill="none" stroke="'+LEG+'" stroke-width="2.2" stroke-linejoin="round" d="'+dd+'"/>';
    s+='<path fill="none" stroke="'+HL+'" stroke-width=".8" stroke-linejoin="round" d="'+dd+'"/>';
  });
  feet.forEach(function(f){ s+='<ellipse fill="'+RUB+'" cx="'+n(f[0])+'" cy="'+n(f[1])+'" rx="3.2" ry="3.2"/>'; });
  /* contrappeso: codolo dietro il perno, dentro l'impronta del treppiede (non allarga l'ingombro) */
  s+='<rect fill="'+BOOM2+'" x="-1.6" y="'+n(hubY-34)+'" width="3.2" height="34" rx="1.2"/>';
  s+='<rect fill="'+CW+'" x="-5.2" y="'+n(hubY-34)+'" width="10.4" height="15" rx="2.6"/>';
  s+='<rect fill="'+CW2+'" x="-5.2" y="'+n(hubY-29.5)+'" width="10.4" height="2.2" rx=".8"/>';
  s+='<rect fill="'+CW2+'" x="-5.2" y="'+n(hubY-24)+'" width="10.4" height="2.2" rx=".8"/>';
  /* braccio telescopico in due tratti (tubo Ø5 cm, dato di targa PRO400BK), il secondo più sottile */
  var tip=hubY+ASTAG.sbraccio, mid=hubY+ASTAG.sbraccio*0.55;
  s+='<rect fill="'+BOOM+'" x="-2.5" y="'+n(hubY)+'" width="5" height="'+n(mid-hubY)+'" rx="1.6"/>';
  s+='<rect fill="'+BOOM2+'" x="-1.9" y="'+n(mid)+'" width="3.8" height="'+n(tip-mid-7)+'" rx="1.3"/>';
  s+='<rect fill="'+HUB2+'" x="-3.4" y="'+n(mid-2.6)+'" width="6.8" height="5.2" rx="1.4"/>';   /* morsetto della sfilata */
  /* perno in testa al palo: il cerchio grande è il palo visto da sopra */
  s+='<circle fill="'+HUB+'" cx="0" cy="'+n(hubY)+'" r="7.5"/><circle fill="'+HUB2+'" cx="0" cy="'+n(hubY)+'" r="4.6"/>';
  s+='<circle fill="'+BOOM+'" cx="0" cy="'+n(hubY)+'" r="2.2"/>';
  /* microfono in punta */
  s+='<rect fill="'+BOOM+'" x="-1.7" y="'+n(tip-8)+'" width="3.4" height="4" rx="1"/>';
  s+='<circle fill="'+GR+'" cx="0" cy="'+n(tip-3)+'" r="3.4"/>';
  s+='<circle fill="'+GR2+'" cx="-.4" cy="'+n(tip-3.4)+'" r="2.5"/>';
  return s;
}
