               if(it.d>=50){ var ay1=it.d/2-12,ay2=-it.d/2+12; s+=lin(0,ay1,0,ay2,'ic thin')+'<path class="ic thin" fill="none" d="M -6,'+(ay2+8)+' L 0,'+ay2+' L 6,'+(ay2+8)+'"/>'; }
