  followspot:"seguipersona segui persona occhio di bue cannone",
  schermo:"televisore video wall maxischermo",   /* NON "monitor": inquinerebbe la query dei wedge */
  camera:"telecamera telecamere videocamera riprese",
  notebook:"computer portatile pc", laptop:"computer portatile pc",
  /* sigle delle input list anglosassoni: un fonico le digita per abitudine (BD, SN, OH, Gtr, Kys…).
     Verificate una per una contro i falsi positivi: la ricerca è una substring, e sigle come "kbd" o
     "bsn" pescavano la batteria sulla query "bd" e il fagotto su "sn". Quelle sono state scartate. */
  keysamp:"kb kys", controllermidi:"kb keys",
  corista:"vox bgv bv backing vox lead vox",
  rullante:"sn snr sd snare", grancassa:"bd",
  piatto:"cym crash ride", piatticoppia:"cym",
