/* Su quali elementi si puo' scegliere un modello di backline: quelli che AMP_DB dichiara di coprire.
   Niente elenco di tipi scritto a parte, che invecchierebbe da solo appena si aggiunge una riga. */
function ampModelApplies(it){
  if(!it||!it.type) return false;
  for(var k in AMP_DB){ var d=AMP_DB[k]; if(d.per && d.per.indexOf(it.type)>=0) return true; }
  return false;
}
function ampModelOf(it){ var d=(it && it.bm && AMP_DB[it.bm]) || null;
  /* un modello scelto e poi rimasto appiccicato a un tipo che non copre non deve piu' contare */
  return (d && d.per && it && d.per.indexOf(it.type)>=0) ? d : null; }
/* Assorbimento del modello. Mai `out`: quella e' potenza audio. null = non dichiarato dal costruttore. */
function ampModelWatt(it){ var d=ampModelOf(it); if(!d||d.watt==null) return null;
  var n=+d.watt; return (isFinite(n)&&n>=0) ? n : null; }
function ampModelKg(it){ var d=ampModelOf(it); if(!d||d.kg==null) return null;
  var n=+d.kg; return (isFinite(n)&&n>0) ? n : null; }
