  function px(a,c){ return horiz?a:c; } function py(a,c){ return horiz?c:a; }
  var s="";
  if(horiz){ s+=bar(0,-W/2+railH/2,L,railH,"ic",railH/2); s+=bar(0,W/2-railH/2,L,railH,"ic",railH/2); }
  else { s+=bar(-W/2+railH/2,0,railH,L,"ic",railH/2); s+=bar(W/2-railH/2,0,railH,L,"ic",railH/2); }
  var aT=-W/2+railH, aB=W/2-railH, step=Math.max(W*0.95,16), a, a2;
  if(kind==="ladder"){ for(a=-L/2+step/2;a<L/2;a+=step){ s+=lin(px(a,aT),py(a,aT),px(a,aB),py(a,aB),"ic thin"); } }
  else if(kind==="zig"){ var up=true; for(a=-L/2;a<L/2-0.1;a+=step){ a2=Math.min(a+step,L/2); var c1=up?aB:aT,c2=up?aT:aB; s+=lin(px(a,c1),py(a,c1),px(a2,c2),py(a2,c2),"ic thin"); up=!up; } }
  else { for(a=-L/2;a<L/2-0.1;a+=step){ a2=Math.min(a+step,L/2); s+=lin(px(a,aT),py(a,aT),px(a2,aB),py(a2,aB),"ic thin"); s+=lin(px(a,aB),py(a,aB),px(a2,aT),py(a2,aT),"ic thin"); } }
  [[-L/2,-W/2],[-L/2,W/2],[L/2,-W/2],[L/2,W/2]].forEach(function(e){ s+=circ(px(e[0],e[1]),py(e[0],e[1]),railH*0.75,"ic"); });
  return s;
