     +'<rect x="'+r2(-W/2+0.8)+'" y="'+r2(-D/2+0.8)+'" width="'+r2(W-1.6)+'" height="'+r2(D-1.6)+'" rx="1.3" fill="#1d2024"/>';
    var nIn=0,nOut=0,k; for(k in use.i) if(use.i[k]) nIn++; for(k in use.o) if(use.o[k]) nOut++;
