    if(nIn) s+='<rect x="'+r2(-bw/2)+'" y="'+r2(by)+'" width="'+r2(bw*Math.min(1,nIn/(L.cap||1)))+'" height="'+r2(bh)+'" rx="'+r2(bh/2)+'" fill="'+IN_COL+'"/>';
