/* ===== MONTAGGIO (Simone 29/07) ============================================================
   Un faro a terra, uno su stativo e uno appeso a un'americana sono tre montaggi diversi, e chi
   allestisce ha bisogno di saperlo: cambia il materiale (base, stativo, gancio + cavo di sicurezza)
   e cambia l'altezza del punto luce.

   Il montaggio è un ATTRIBUTO del faro, non un oggetto in più: lo stativo si disegna nell'icona,
   così non c'è nessun id da tenere vivo e nessun orfano da recuperare quando si cancella.
   Per l'appeso la struttura si trova per GEOMETRIA, come la pedana trova chi ci sta sopra
   (itemsOnRiser): il faro dentro il rettangolo di un'americana è appeso a quella, e la segue.
   panDeg non esiste: la rotazione è già it.rot. ========================================== */
var MOUNT_MODES=[["floor","A terra"],["stand","Su stativo"],["hung","Appeso"]];
var MOUNT_H_DEF={ floor:25, stand:250, hung:400 };     /* cm dal palco al punto luce */
var MOUNT_H_MIN=20, MOUNT_H_MAX=1200;                  /* limiti larghi: 20 cm (a terra) → 12 m (americana alta) */
var MOUNT_SAFETY=[["present","Presente"],["unspecified","Da verificare"],["missing","Mancante"]];
var HANG_STRUCT={ americana:1, truss:1 };              /* strutture a cui si appende: barra luci e truss */
function isMountable(it){ return !!(it && lightsIsGear(it.type)); }   /* gli apparecchi del reparto luci */
function isHangStruct(it){ return !!(it && HANG_STRUCT[it.type]===1); }
function mountModeOf(it){
  var m=it && it.mount && it.mount.mode;
  return (m==="stand"||m==="hung") ? m : "floor";      /* default e migrazione: a terra, senza spostare niente */
}
function mountHOf(it){
  var mo=mountModeOf(it), h=it && it.mount && it.mount.h;
  if(h==null || !isFinite(+h)) return MOUNT_H_DEF[mo];
  return Math.max(MOUNT_H_MIN, Math.min(MOUNT_H_MAX, Math.round(+h)));
}
function mountSafetyOf(it){
  var v=it && it.mount && it.mount.safety;
  return (v==="present"||v==="missing") ? v : "unspecified";
}
function mountLabel(k){ for(var i=0;i<MOUNT_MODES.length;i++) if(MOUNT_MODES[i][0]===k) return MOUNT_MODES[i][1]; return ""; }
function mountSet(it, patch){
  if(!it || !isMountable(it)) return;
  var m=it.mount||{};
  Object.keys(patch||{}).forEach(function(k){ if(patch[k]==null) delete m[k]; else m[k]=patch[k]; });
  if(m.mode==="floor" && m.h==null && m.safety==null && !m.note) delete it.mount; else it.mount=m;
}
/* La struttura a cui il faro è appeso: quella che se lo ritrova sotto. Nessun id memorizzato —
   sposti l'americana e i suoi fari la seguono, sposti il faro fuori e si sgancia da solo. */
function hangSupportOf(it){
  if(!it || mountModeOf(it)!=="hung") return null;
  var found=null;
  (state.items||[]).forEach(function(s){
    if(found || !isHangStruct(s)) return;
    var rot=(s.rot||0)*Math.PI/180, cos=Math.cos(-rot), sin=Math.sin(-rot);
    var dx=it.x-s.x, dy=it.y-s.y, lx=dx*cos-dy*sin, ly=dx*sin+dy*cos;
    if(Math.abs(lx)<=s.w/2 && Math.abs(ly)<=s.d/2+10) found=s;   /* +10 cm: un faro un filo sotto la barra è appeso lo stesso */
  });
  return found;
}
function hangItemsOf(st){
  if(!isHangStruct(st)) return [];
  return (state.items||[]).filter(function(it){ return isMountable(it) && mountModeOf(it)==="hung" && hangSupportOf(it)===st; });
}
/* Testo che il montaggio aggiunge sotto il nome, in pianta: è il dato che serve a chi monta. */
function mountNote(it){
  if(!isMountable(it)) return "";
  var mo=mountModeOf(it);
  if(mo==="floor") return "";
  var h=(mountHOf(it)/100).toFixed(mountHOf(it)%100?1:0).replace(".",",");
  return (mo==="stand" ? "stativo " : "appeso ")+h+" m";
}
