  if(flat==="bottom") return "M "+x+","+(y+d)+" A "+(w/2)+","+d+" 0 0 1 "+(x+w)+","+(y+d)+" Z";    /* bulge verso il fondo */
  if(flat==="left")   return "M "+x+","+y+" A "+w+","+(d/2)+" 0 0 1 "+x+","+(y+d)+" Z";            /* bulge a destra */
