      var gzT=gazStructLabel(it), gzs=(it.dimSide&&it.dimSide!=='auto')?it.dimSide:'top', goff=13, gdx=0, gdy=0, gtr='';
      if(gzs==='top'){ gdy=-(it.d/2)-goff; }
