  var used={}; (state.items||[]).forEach(function(x){ if(x.type==="miczone"&&x.zcol) used[x.zcol]=1; });
  for(var i=0;i<MICZONE_COLORS.length;i++){ if(!used[MICZONE_COLORS[i]]) return MICZONE_COLORS[i]; }
