  if(!_segHits(a,c1,rects)&&!_segHits(c1,b,rects)) return [a,c1,b];
  if(!_segHits(a,c2,rects)&&!_segHits(c2,b,rects)) return [a,c2,b];
  return _astarOrth(a,b,rects) || [a,orthCorner(a,b),b];
