/* Dopo un collegamento computer→console: se quel modello offre PIÙ DI UNA connessione, la scelta è
   dell'utente e si chiede (mai indovinata). Se ne offre una sola, la si scrive lo stesso — così è
   comunque esplicita nel pannello e sull'etichetta del cavo. */
function mixAskVia(it, mixIt){
  if(!it || !mixIt || !COMP_SRC[it.type]) return false;
  var opts=mixerConnOpts(mixIt);
  if(opts.length<=1){ cabSetVia(it, opts.length?opts[0].id:"an"); return false; }
  var cur=cabViaOfItem(it);
  if(opts.some(function(o){ return o.id===cur; }) && cur!=="an") return false;   /* già scelta e ancora valida */
  openMixViaPicker(it, mixIt);
  return true;
}
function openMixViaPicker(it, mixIt){
  var m=document.getElementById("mixViaModal"); if(!m) return;
  var mm=mixerModelOf(mixIt), opts=mixerConnOpts(mixIt);
  var nm=(it.label||(TYPES[it.type]&&TYPES[it.type].nome)||"Computer");
  document.getElementById("mvHint").innerHTML=
    esc(nm)+" → <b>"+esc(mm.brand+" "+mm.model)+"</b>. Sono tre cavi diversi: qui sotto ci sono <b>solo</b> le connessioni che questa console ha davvero.";
  var host=document.getElementById("mvOpts"); host.innerHTML="";
  var cur=cabViaOfItem(it);
  opts.forEach(function(o){
    var b=document.createElement("button"); b.type="button";
    b.className="pa-card mv-opt"+(o.id===cur?" sel":""); b.setAttribute("data-via", o.id);
    b.innerHTML='<b>'+esc(o.name)+'</b><br><small>'+esc(o.hint)+'</small>';
    b.addEventListener("click", function(){ m.hidden=true; cabSetVia(it, o.id); });
    host.appendChild(b);
  });
  m.hidden=false;
}
(function(){
  var m=document.getElementById("mixViaModal"); if(!m) return;
  var c=document.getElementById("mvClose"); if(c) c.addEventListener("click", function(){ m.hidden=true; });
  m.addEventListener("mousedown", function(e){ if(e.target===m) m.hidden=true; });
})();
function cabSetItemBox(it, boxId){
  var n=cabItemInputs(it).length; if(!n) return;
  /* cambiando box la porta scelta a mano decade: il numero era di QUELLA box (29/07) */
  if(isPerMusicianMulti(it)){ for(var i=0;i<n;i++){ var cmi=cabManual(it.id+"#"+i); if(cmi.box!==boxId) delete cmi.port; cmi.box=boxId; delete cmi.auto; } return; }   /* postazione: ogni musicista alla stessa box, ma cavi separati */
  var cm=cabManual(cabItemRouteKey(it)); if(cm.box!==boxId) delete cm.port; cm.box=boxId; delete cm.auto;   /* scelto a mano: non si ridistribuisce più */
  compViaDecay(it, boxId);   /* la via digitale era di quel mixer: sulla stage box non esiste */
}
/* ── Shift+trascina un elemento SOPRA un cavo (stile Max: inserire un oggetto nel patch cord) ──
   Rilasci con Shift una stage box/sub-snake su un cavo audio → quello strumento si ricollega alla
   box rilasciata; un distro/ciabatta su una linea elettrica → il carico si ricollega al distro. */
function distToPoly(sp, P){ var best=1e9;
  for(var i=0;i<P.length-1;i++){ var a=P[i], b=P[i+1];
    var vx=b[0]-a[0], vy=b[1]-a[1], L2=vx*vx+vy*vy||1;
    var t=Math.max(0, Math.min(1, ((sp.x-a[0])*vx+(sp.y-a[1])*vy)/L2));
    var dx=sp.x-(a[0]+t*vx), dy=sp.y-(a[1]+t*vy);
    var d=dx*dx+dy*dy; if(d<best) best=d;
  }
  return Math.sqrt(best);
}
function cabTryInsertAt(sp, it){
  if(!it || !sp) return false;
  var TH=26, OBS=obstacleRects();   /* tolleranza dal cavo in cm */
  if(cabIsDest(it) && state.cab && state.cab.on){
    var R=cabResult(), best=null, bd=TH;
    (R.links||[]).forEach(function(l){ if(l.deleted || (l.box && l.box.id===it.id)) return;
      var ex={}; ex[l.s.it.id]=1; if(l.box&&l.box.id) ex[l.box.id]=1;
      var d=distToPoly(sp, orthExpand(cabRoutePts(l.pts, OBS, ex)));
      if(d<bd){ bd=d; best=l; } });
    if(best){ cabSetItemBox(best.s.it, it.id);   /* tutto lo strumento passa alla box inserita (cavo unico se multi-canale) */
      __cabRes=null; save(); return true; }
  }
  if(elecIsDistro(it) && state.elec && state.elec.on){
    var Re=elecResult(), bestE=null, bdE=TH;
    (Re.loadLinks||[]).forEach(function(l){ if(l.distro && l.distro.it && l.distro.it.id===it.id) return;
      var ex={}; if(l.load&&l.load.it) ex[l.load.it.id]=1; if(l.distro&&l.distro.it) ex[l.distro.it.id]=1;
      var d=distToPoly(sp, orthExpand(cabRoutePts(l.pts, OBS, ex)));
      if(d<bdE){ bdE=d; bestE=l; } });
    if(bestE){ state.elec.manual=state.elec.manual||{}; state.elec.manual[bestE.load.it.id]={distro:it.id};
      __elecRes=null; save(); return true; }
  }
  return false;
}
/* Manual-first: "Collega automaticamente" (D-L2A, 21/07) materializza la proposta del motore come
   override ESPLICITI: simula in modalità auto e scrive man[key].box SOLO verso box REALI (salta le
   proposte b.auto) e SOLO dove l'utente non ha già un collegamento. Così la proposta diventa
   collegamenti dell'utente: visibili, modificabili, cancellabili uno a uno. Ritorna quante chiavi
   (cavi input/gruppo + mix monitor) ha collegato. */
function cabConnectAll(){
  if(!state.cab.on) state.cab.on=true;
  var man=state.cab.manual=state.cab.manual||{};
  var prev=state.cab.mode; state.cab.mode="auto";
  var R; try{ R=audioCablingEngine(); } finally{ state.cab.mode=prev; }
  var done=0, seen={};
  (R.links||[]).forEach(function(l){
    if(l.deleted || !l.box || l.box.auto) return;
    var cm=man[l.key]||(man[l.key]={});
    if(!cm.box && !cm.deleted){ cm.box=l.box.id; cm.auto=1; if(!seen[l.key]){ seen[l.key]=1; done++; } }
  });
  (R.mixes||[]).forEach(function(m){
    if(!m.box || m.box.auto) return;
    var k="mix:"+m.key, cm=man[k]||(man[k]={});
    if(!cm.box && !cm.deleted){ cm.box=m.box.id; cm.auto=1; done++; }
  });
  __cabRes=null; save(); render();
  return done;
}
/* Collega UN SOLO canale (fulmine sulla riga della lista, Simone 28/07): stessa logica di
   cabConnectAll — simula la modalità auto e prende la destinazione che il motore sceglierebbe — ma
   materializza solo la chiave chiesta. Gli altri canali restano come sono.
   Ritorna l'id della box scelta, o null se non c'è destinazione. */
function cabConnectOne(key){
  if(!key) return null;
  if(!state.cab.on) state.cab.on=true;
  var man=state.cab.manual=state.cab.manual||{};
  var prev=state.cab.mode; state.cab.mode="auto";
  var R; try{ R=audioCablingEngine(); } finally{ state.cab.mode=prev; }
  /* La chiave della RIGA non è la chiave del PERCORSO (bug 28/07, batteria): uno strumento
     multicanale viaggia su UN multipolare con chiave di gruppo «grp:<id>», mentre la riga della
     lista ha la chiave del canale «<id>#<n>». Cercando la chiave della riga fra i link non si
     trovava nulla e il fulmine rispondeva «nessuna destinazione adatta» pur avendo la stage box lì.
     Il link porta entrambe: l.s.key è il canale, l.key è il percorso. Collegando il percorso, gli
     otto canali della batteria vanno insieme — che è anche quello che ci si aspetta. */
  var hit=null, rk=null;
  (R.links||[]).forEach(function(l){ if(!hit && l.s && l.s.key===key && l.box && !l.box.auto){ hit=l.box.id; rk=l.key; } });
  if(!hit) (R.mixes||[]).forEach(function(m){ if(!hit && ("mix:"+m.key)===key && m.box && !m.box.auto){ hit=m.box.id; rk="mix:"+m.key; } });
  if(!hit) return null;
  var cm=man[rk]||(man[rk]={});
  if(cm.box && !cm.deleted) return cm.box;        /* già cablato: non si tocca — ma un cavo TOLTO va ricollegato (29/07: in auto il cestino lascia box+deleted, e il fulmine rispondeva «collegato» senza collegare niente) */
  delete cm.deleted;                              /* il fulmine è una richiesta esplicita: annulla un «cavo tolto» */
  cm.box=hit; cm.auto=1;
  __cabRes=null; save(); render();
  /* finito su una console: con che cosa ci entra il computer? (stessa domanda del trascinamento) */
  var _dst=(state.items||[]).filter(function(x){ return x.id===hit; })[0];
  var _src=(R.links||[]).filter(function(l){ return l.key===rk; })[0];
  if(_dst && _src && _src.s && cabMixerIn(_dst)) setTimeout(function(){ mixAskVia(_src.s.it, _dst); }, 0);
  return hit;
}
/* etichetta di una destinazione per i messaggi: «Stage box A» o il modello della console (29/07) */
function cabDestLabel(b){
  if(!b) return "una stage box";
  return b.isMixer ? b.name : ("Stage box "+b.letter);
}
/* Scelta della porta fisica su una stage box. L'ultimo che sceglie vince: se quella porta era
   già stata scelta da un altro canale, l'altro torna automatico e si rimette in fila. Così
   «voglio QUESTO ingresso» è sempre una richiesta esaudibile, non un conflitto da risolvere a mano.
   port 0/null = torna automatica. Ritorna false se la porta non esiste o è riservata.
   Come il fulmine, scrive sulla chiave di PERCORSO (cabRouteKeyOf): uno strumento multicanale
   viaggia su un multipolare e la porta scelta è quella con cui il multipolare entra nella box. */
function cabSetPort(key, port){
  if(!key) return false;
  var rk=(typeof cabRouteKeyOf==="function") ? cabRouteKeyOf(key) : key;
  var man=state.cab.manual=state.cab.manual||{};
  port=+port||0;
  if(!port){
    var m0=man[rk];
    if(m0){ delete m0.port; if(!Object.keys(m0).length) delete man[rk]; }
    __cabRes=null; save(); render();
    return true;
  }
  /* su quale box sta questo canale: la scelta manuale, altrimenti quella che gli ha dato il motore */
  var R=cabResult(true), boxId=(man[rk]&&man[rk].box)||null;
  if(!boxId) (R.links||[]).forEach(function(l){ if(!boxId && l.key===rk && l.box) boxId=l.box.id; });
  var b=(R.boxes||[]).filter(function(x){ return x.id===boxId; })[0];
  if(!b || b.auto || port<1 || port>b.cap) return false;
  if(b.resMap && b.resMap[port]) return false;   /* riservata: tiene il suo numero, nel popup resta disabilitata */
  /* l'ultimo vince: chi teneva quella porta torna automatico e si rimette in fila. Un multipolare
     occupa un BLOCCO di porte consecutive: se le due scelte si sovrappongono anche solo in parte,
     a tornare automatico è tutto lo strumento — un multipolare non si spezza. */
  var _span={};
  (R.links||[]).forEach(function(l){ if(!l.deleted) _span[l.key]=(_span[l.key]||0)+1; });
  var _mio=port+(_span[rk]||1)-1;
  Object.keys(man).forEach(function(k){
    if(k===rk) return;
    var o=man[k]; if(!o || !(o.port>0)) return;
    var _suo=+o.port+(_span[k]||1)-1;
    if(_suo<port || +o.port>_mio) return;   /* blocchi che non si toccano: nessuno si sposta */
    var kb=o.box||null;
    if(!kb) (R.links||[]).forEach(function(l){ if(!kb && l.key===k && l.box) kb=l.box.id; });
    if(kb===boxId){ delete o.port; if(!Object.keys(o).length) delete man[k]; }
  });
  var m=cabManual(rk);
  m.port=port; if(!m.box) m.box=boxId;
  __cabRes=null; save(); render();
  return true;
}
/* Allinea elettrico (parità con cabAlign): snap dei corner manuali alla griglia + pulizia collineari */
/* Align stile Max (08/07): riordina TUTTI i cavi manuali — snap dei corner alla griglia + pulizia
   (fonde i collineari, toglie i micro-jog). Diverso da "Reset manuale" (che butta il routing): qui il
   percorso che hai disegnato resta, solo più pulito e allineato. Passo = griglia attiva o 25 cm. */
function cabAlign(){
  var R=cabResult(); if(!R) return;
  var step=snapVal()||25, man=state.cab.manual||{}, changed=false;
  R.links.forEach(function(l){ var m=man[l.key]; if(!m||!m.pts||!m.pts.length||!l.box) return;
    var full=[l.pts[0]].concat(m.pts).concat([boxAnchor(l.box)]);
    var snapped=full.map(function(p,i){ return (i===0||i===full.length-1) ? p.slice() : [Math.round(p[0]/step)*step, Math.round(p[1]/step)*step]; });
    var poly=cabCleanPoly(snapped), interior=poly.slice(1,-1);
    if(interior.length) m.pts=interior; else delete m.pts;
    changed=true;
  });
  if(changed){ __cabRes=null; save(); render(); renderCabPanel(); }
}

/* ===== CABLAGGIO ELETTRICO — motore (carichi → distro → alimentazione, bilanciamento fasi) =====
   Stesso principio del cablaggio audio: dati (WATT reali) → calcolo → layer → report. */
var ELEC_VOLT=230;
/* Soglie sotto le quali l'Audit tace (27/07, dall'audit d'uso). Un duo acustico — due canali e un ampli
   da 200 W in una presa — prendeva «Da rivedere» con un errore critico, perché le regole erano tarate
   su una produzione media applicata a qualunque progetto. Sotto queste soglie stage box, quadro
   elettrico e monitor di palco non mancano: semplicemente non servono. */
var AUDIT_MIN_CH=4;      /* canali audio: fino a 4 si va diretti al banco, senza stage box */
var AUDIT_MIN_W=1000;    /* watt: sotto 1 kW non si tira un quadro, si usa la Schuko che c'è */
/**
 * L'elettrico è stato aperto, oppure il progetto è ancora quello che il modello ha posato?
 *
 * Sei modelli su otto nascevano con un ERRORE CRITICO — «carichi presenti ma nessun quadro» — perché
 * una band fa 2,6 kW di soli ampli e la soglia è 1 kW. Formalmente giusto, praticamente rumore: chi
 * lo vede a ogni progetto impara a premere «Esporta comunque» e smette di leggerlo, e allora il
 * giorno che l'errore è vero non lo ferma nessuno.
 *
 * Finché il layer elettrico non è mai stato attivato e non c'è un quadro né un cavo, la mancanza è
 * un «non hai ancora fatto»: resta un avviso. Appena l'utente apre l'elettrico torna un errore.
 * (decisione di Simone, 16/08)
 */
function elettricoIniziato(){
  try{
    var e=state.elec||{};
    /* NON `e.on`: il layer elettrico nasce acceso, quindi sarebbe vero sempre e non distinguerebbe
       niente (provato: su un modello appena creato dava «iniziato»). Le tracce vere di lavoro
       sull'elettrico sono l'alimentazione dichiarata, un cavo tirato a mano, un quadro sul palco. */
    if(e.supply) return true;
    if(e.manual && Object.keys(e.manual).length) return true;
    if(e.uplinks && Object.keys(e.uplinks).length) return true;
    return (state.items||[]).some(function(it){
      return (typeof elecIsDistro==="function" && elecIsDistro(it)) || (typeof elecIsGen==="function" && elecIsGen(it));
    });
  }catch(_e){ return true; }   /* nel dubbio la severità resta quella piena */
}
/* Il DIMMER RACK e' una destinazione, non un carico (Simone 29/07): i fari dimmerabili si
   attaccano a lui e lui al quadro — prima era un carico da 3600 W fissi e i PAR gli passavano
   accanto per andare dritti al quadro, che e' il contrario di come si cabla davvero.
   32 A trifase e 12 canali sono la taglia tipica di un rack da 12 kW: si cambiano dal pannello. */
var ELEC_DISTRO ={ distro125:{a:125,ph:3,name:"Quadro 125A"}, distro63:{a:63,ph:3,name:"Distro 63A"}, distro32:{a:32,ph:3,name:"Distro 32A"}, quadro:{a:63,ph:3,name:"Quadro"}, ciabatta:{a:16,ph:1,name:"Ciabatta"}, dimmerluci:{a:32,ph:3,name:"Dimmer"} };
var ELEC_SECTIONS = [[16,"2,5 mm²"],[32,"6 mm²"],[63,"16 mm²"],[125,"35 mm²"],[250,"70 mm²"]];
function elecIsDistro(it){ return !!ELEC_DISTRO[it.type]; }
function elecIsGen(it){ return GEN_KVA[it.type]!=null; }
function elecSection(a){ for(var i=0;i<ELEC_SECTIONS.length;i++){ if(a<=ELEC_SECTIONS[i][0]) return ELEC_SECTIONS[i][1]; } return "95 mm²"; }
/* F4: connettore della linea — dedotto (audio rack → PowerCON, >16A → CEE, altrimenti Schuko) o override */
var ELEC_POWERCON={ rack:1, amprack:1 };
/* Il powerCON è un connettore da 20 A (TRUE1: 16 A) — sopra quella soglia non esiste, e un rack ampli
   da 7 kW ne chiede 30. Prima il tipo vinceva sulla corrente: il PDF «Alimentazioni» stampava
   «PowerCON» per una linea da 30 A mentre due righe sotto l'avviso diceva «serve una linea dedicata
   (CEE)» — due indicazioni opposte nello stesso foglio, e chi prepara i cavi segue quella sbagliata.
   La corrente comanda: oltre i 16 A si passa a CEE anche per rack e amp rack (25/08). */
var ELEC_POWERCON_MAX_A=16;
function elecConnOf(it, a, ov){
  var pcOk = ELEC_POWERCON[it.type] && !(a>ELEC_POWERCON_MAX_A);
  var k = (ov==="schuko"||ov==="cee"||ov==="powercon") ? ov : (pcOk ? "powercon" : (a>16 ? "cee" : "schuko"));
  /* Anche scelto a mano: un powerCON su 30 A resta un errore, non una preferenza. */
  if(k==="powercon" && a>ELEC_POWERCON_MAX_A) k="cee";
  if(k==="powercon") return {k:"pc", label:"PowerCON"};
  if(k==="cee") return {k:"cee", label:"CEE"+(a>32?"63":(a>16?"32":"16"))};
  return {k:"sk", label:"Schuko"};
}
function elecMargin(){ return 0.2; }
function elecKW(w){ return (w/1000).toFixed(1).replace(".",",")+" kW"; }
function elecSupplyPoint(){
  var sp=state.elec&&state.elec.supply, W=state.stage.w, D=state.stage.d;
  var gen=(state.items||[]).filter(elecIsGen)[0];
  if(gen) return {kind:"gen", name:"Generatore "+GEN_KVA[gen.type]+" kVA", x:gen.x, y:gen.y, kva:GEN_KVA[gen.type]};   /* generatore sul palco = sorgente (vince) */
  if(!sp) return null;
  var nm={rete:"Allaccio rete / quadro gen.", right:"Alimentazione DX", left:"Alimentazione SX", custom:"Alimentazione", gen:"Generatore"};
  var p={kind:sp.kind, name:nm[sp.kind]||"Alimentazione"};
  if(sp.kind==="custom"){ p.x=sp.x; p.y=sp.y; }
  else if(sp.kind==="right"){ p.x=W-30; p.y=D-40; }
  else if(sp.kind==="left"){ p.x=30; p.y=D-40; }
  else { p.x=W/2; p.y=D+108; }   /* rete: sotto, non sovrapposta all'home audio */
  p.x=Math.round(p.x); p.y=Math.round(p.y); return p;
}
var selElec=null;   /* linea elettrica selezionata (key = id del carico) — parità con selCab */
function elecManual(key){ state.elec.manual=state.elec.manual||{}; if(!state.elec.on) state.elec.on=true;
  if(!state.elec.manual[key] || typeof state.elec.manual[key]!=="object") state.elec.manual[key]={}; return state.elec.manual[key]; }
/* La FASE PIÙ CARICA dell'impianto (29/07) — l'equivalente elettrico della capienza «10/16 su A»
   dell'Input. Non la somma dei kW dei quadri, che non fa saltare niente: quello che conta è la
   singola fase più carica, la stessa grandezza con cui electricEngine alza «quasi al limite»
   (>85% di d.a) e «sovraccarico» (>d.a). Nessun numero nuovo: solo d.phLoad[] contro d.a. */
function elecWorstPhase(R){
  var w=null;
  ((R&&R.distros)||[]).forEach(function(d){
    if(!d.a) return;
    for(var p=0;p<d.ph;p++){
      var a=d.phLoad[p]||0;
      if(!w || (a/d.a) > (w.a/w.cap)) w={a:a, cap:d.a, letter:d.letter, ph:"L"+(p+1)};
    }
  });
  return w;
}
/* Scollega una linea elettrica (carico o uplink). È la stessa scrittura del tasto Elimina sulla
   linea selezionata: in manual-first l'override sparisce, in auto resta la pietra tombale
   {deleted:true} che tiene il carico fuori dalla proposta del motore finché non lo richiami col
   fulmine. Una sola funzione per i due punti d'ingresso: due formulazioni divergerebbero. */
function elecDeleteKey(key){
  if(!key || !state.elec) return false;
  if(String(key).indexOf("up:")===0){ if(state.elec.uplinks) delete state.elec.uplinks[String(key).slice(3)]; }
  else if(state.elec.mode!=="auto"){ if(state.elec.manual) delete state.elec.manual[key]; }
  else { state.elec.manual=state.elec.manual||{}; state.elec.manual[key]={deleted:true}; }
  if(selElec===key) selElec=null;
  __elecRes=null;
  return true;
}
/* Cestino sulla riga della lista Power: scollega UN carico e libera la sua linea sul quadro. */
