          +'<circle class="elec-endpt elec-endpt-hit" data-el="'+esc(selElec)+'" data-eend="'+ec[0]+'" cx="'+ec[1][0].toFixed(1)+'" cy="'+ec[1][1].toFixed(1)+'" r="17"/>';
