function buildCompCtl(comp, it, only){
  var box=document.getElementById("pCompCtl"); box.innerHTML="";
  var p=parts(it);
  var dimEl=document.createElement("div"); dimEl.className="comp-dim";        /* ingombro reale, come nel prototipo */
  var nPz = comp.explode ? comp.explode(it).length : 0;
  dimEl.textContent="Ingombro: "+it.w+"\u00d7"+it.d+" cm"+(nPz?" \u00b7 "+nPz+" elementi":"");
  box.appendChild(dimEl);
  if(comp.presets){                                  /* DS v2.1: chips preset (scelte esclusive) */
    var pr=document.createElement("div"); pr.className="chips"; pr.style.margin="2px 0 10px";
    comp.presets.forEach(function(ps){
      var b=document.createElement("button"); b.type="button"; b.textContent=ps[0];
      var match=Object.keys(ps[1]).every(function(k){ return String(p[k]===undefined?COMP[it.type].defParts[k]:p[k])===String(ps[1][k]); });
      if(match) b.classList.add("on");
      b.addEventListener("click", function(){
        var np=parts(it); Object.keys(ps[1]).forEach(function(k){ np[k]=ps[1][k]; });
        var c2=COMP[it.type]; if(c2.size){ var sz=c2.size(it); it.w=sz[0]; it.d=sz[1]; }
        render(); save();
      });
      pr.appendChild(b);
    });
    box.appendChild(pr);
  }
  comp.controls.forEach(function(c){
    if(only && only.indexOf(c.key)<0) return;   /* config ridotta (batteria): solo i controlli elencati (Musicista/Sgabello) */
    if(c.type==="toggle"){
      var lab=document.createElement("label"); lab.className="chk";
      var cb=document.createElement("input"); cb.type="checkbox"; cb.checked=!!p[c.key];
      cb.addEventListener("change", function(){ setPart(it, c.key, cb.checked); });
      lab.appendChild(cb); lab.appendChild(document.createTextNode(" "+c.label));
      box.appendChild(lab);
    } else if(c.type==="choice"){
      /* DS v2.2: le scelte esclusive sono chips orizzontali, mai tendine */
      var clab=document.createElement("label"); clab.textContent=c.label; box.appendChild(clab);
      var ch=document.createElement("div"); ch.className="chips"; ch.style.margin="0 0 8px";
      var cur=p[c.key]===undefined?comp.defParts[c.key]:p[c.key];
      c.options.forEach(function(o){
        var b2=document.createElement("button"); b2.type="button"; b2.textContent=o[1];
        if(cur===o[0]) b2.classList.add("on");
        b2.addEventListener("click", function(){ setPart(it, c.key, o[0]); });
        ch.appendChild(b2);
      });
      box.appendChild(ch);
    } else {
      var row=document.createElement("div"); row.className="cnt-row";
      var s=document.createElement("span"); s.className="cnt-lab"; s.textContent=c.label;
      var minus=document.createElement("button"); minus.className="btn cnt-b"; minus.type="button"; minus.textContent="−";
      var val=document.createElement("span"); val.className="cnt-v"; val.textContent=(p[c.key]||0);
      var plus=document.createElement("button"); plus.className="btn cnt-b"; plus.type="button"; plus.textContent="+";
      minus.addEventListener("click", function(){ setPart(it, c.key, Math.max(c.min, (parts(it)[c.key]||0)-1)); });
      plus.addEventListener("click", function(){ setPart(it, c.key, Math.min(c.max, (parts(it)[c.key]||0)+1)); });
      row.appendChild(s); row.appendChild(minus); row.appendChild(val); row.appendChild(plus);
      box.appendChild(row);
    }
  });
}
function setPart(it, key, val){
  parts(it)[key]=val;
  var comp=COMP[it.type];
  if(comp && comp.size){ var sz=comp.size(it); it.w=sz[0]; it.d=sz[1]; }
  render(); save();
}
/* "Dividi in elementi singoli": esplode un componibile nei suoi pezzi come item indipendenti */
function explodeComposite(){
  var it=getSel(); if(!it) return; var comp=COMP[it.type]; if(!comp||!comp.explode) return;
  var pieces=comp.explode(it), rot=(it.rot||0)*Math.PI/180, c=Math.cos(rot), s=Math.sin(rot), made=[], gid="g"+uid();
  pieces.forEach(function(pc){
    var T=TYPES[pc.type]; if(!T) return;
    var wx=it.x+(pc.dx*c - pc.dy*s), wy=it.y+(pc.dx*s + pc.dy*c);
    var ni={id:uid(), type:pc.type, x:Math.round(wx), y:Math.round(wy), rot:it.rot||0, w:T.w, d:T.d, label:pc.label||"", grp:gid};
    if(T.riser) ni.h=T.h||40;
    if(pc.extra) Object.keys(pc.extra).forEach(function(k){ ni[k]=pc.extra[k]; });
    made.push(ni);
  });
  if(!made.length) return;
  state.items=state.items.filter(function(x){ return x.id!==it.id; });
  made.forEach(function(n){ state.items.push(n); });
  selSet={}; made.forEach(function(n){ selSet[n.id]=true; }); sel=made[made.length-1].id;
  render(); save();
}
