/* Dividi una postazione doppia (×2 del generatore o doppia-da-flag) in 2 postazioni singole */
var SINGLE_OF_KIND={vln1:"vlnpost", vln2:"vlnpost", vla:"violapost", vc:"violoncello", cb:"contrabbasso"};
function splitDouble(){
  var it=getSel(); if(!it) return;
  var single;
  if(DOUBLE_TYPES[it.type]) single=SINGLE_OF_KIND[DOUBLE_TYPES[it.type].kind];
  else if(POSTAZ[it.type] && it.doppia) single=it.type;
  if(!single || !TYPES[single] || !POSTAZ[single]) return;
  var cfg=sepCfg(it), half=(it.sep||cfg.sep)/2, rot=(it.rot||0)*Math.PI/180;
  var ox=Math.cos(rot)*half, oy=Math.sin(rot)*half, P=POSTAZ[single], base=it.label||"";
  function mk(cx,cy,lab){ var o={id:uid(), type:single, x:Math.round(cx), y:Math.round(cy), rot:it.rot||0,
    w:P.s[0], d:P.s[1], label:lab||"", sedia:true, leggio:true, doppia:false};
    if(it.grp) o.grp=it.grp; if(it.vsec!=null) o.vsec=it.vsec; return o; }
  /* mantieni i due nomi distinti della doppia (label / label2) */
  var a=mk(it.x-ox, it.y-oy, it.label||""), b=mk(it.x+ox, it.y+oy, it.label2 || (base?base+" b":""));
  state.items=state.items.filter(function(x){ return x.id!==it.id; });
  state.items.push(a,b);
  selSet={}; selSet[a.id]=true; selSet[b.id]=true; sel=b.id;
  render(); save();
}
/* split di una postazione singola → strumento (senza sedia/leggio) + sedia + leggio come elementi indipendenti */
function splitPostaz(){
  var it=getSel(); if(!it || !POSTAZ[it.type]) return;
  var rot=(it.rot||0)*Math.PI/180, c=Math.cos(rot), s=Math.sin(rot), gid="g"+uid(), made=[];
  function place(type,dx,dy){ var T=TYPES[type]; if(!T) return; made.push({id:uid(),type:type,
    x:Math.round(it.x+dx*c-dy*s), y:Math.round(it.y+dx*s+dy*c), rot:it.rot||0, w:T.w, d:T.d, label:"", grp:gid}); }
  var hadSedia=it.sedia!==false, hadLeggio=it.leggio!==false;
  it.sedia=false; it.leggio=false; it.doppia=false; it.grp=gid;   /* lo strumento resta in posizione, nudo */
  var isStool=STOOL_POSTAZ[it.type]!=null;
  if(hadSedia) place(isStool ? "sgabello" : "sedia", 0, isStool ? -26 : -22);
  if(hadLeggio) place("leggio", 0, 38);
  made.forEach(function(m){ state.items.push(m); });
  selSet={}; selSet[it.id]=true; made.forEach(function(m){ selSet[m.id]=true; }); sel=it.id;
  render(); save();
}
/* split di una voce → persona (senza leggio) + leggio */
function splitVoce(){
  var it=getSel(); if(!it || !VOCE[it.type]) return;
  if(it.leggio===false){ return; }
  var rot=(it.rot||0)*Math.PI/180, c=Math.cos(rot), s=Math.sin(rot), gid="g"+uid();
  var T=TYPES.leggio, dx=0, dy=42;
  var lg={id:uid(), type:"leggio", x:Math.round(it.x+dx*c-dy*s), y:Math.round(it.y+dx*s+dy*c), rot:it.rot||0, w:T.w, d:T.d, label:"", grp:gid};
  it.leggio=false; it.grp=gid; state.items.push(lg);
  selSet={}; selSet[it.id]=true; selSet[lg.id]=true; sel=it.id; render(); save();
}
/* è scomponibile in elementi? */
function isDecomposable(it){ if(!it) return false; var t=TYPES[it.type]; if(!t) return false;
  if(it.type==="corista") return false;   /* corista: niente "Dividi in elementi" (è solo una voce, Simone) */
  return !!COMP[it.type] || !!t.gtr || !!DOUBLE_TYPES[it.type] || it.doppia===true || !!POSTAZ[it.type] || !!VOCE[it.type] || it.type==="sedialeggio"; }
/* dispatcher unico "Dividi in elementi" */
function splitElement(){
  var it=getSel(); if(!it) return; var t=TYPES[it.type]; if(!t) return;
  if(COMP[it.type]) return explodeComposite();
  if(t.gtr) return explodeGuitar();
  if(DOUBLE_TYPES[it.type] || it.doppia===true) return splitDouble();
  if(POSTAZ[it.type]) return splitPostaz();
  if(VOCE[it.type]) return splitVoce();
  if(it.type==="sedialeggio") return splitSediaLeggio();
}
/* "Sedia + leggio" → sedia (nera) + leggio come item indipendenti, nelle stesse posizioni del disegno combinato */
function splitSediaLeggio(){
  var it=getSel(); if(!it || it.type!=="sedialeggio") return;
  var rot=(it.rot||0)*Math.PI/180, c=Math.cos(rot), s=Math.sin(rot), gid="g"+uid(), made=[];
  function place(type,dx,dy){ var T=TYPES[type]; if(!T) return; made.push({id:uid(),type:type,
    x:Math.round(it.x+dx*c-dy*s), y:Math.round(it.y+dx*s+dy*c), rot:it.rot||0, w:T.w, d:T.d, label:"", grp:gid}); }
  place("sedia", 0, -25);   /* sedia nella stessa posizione del disegno combinato */
  place("leggio", 0, 36);   /* leggio davanti */
  if(!made.length) return;
  state.items=state.items.filter(function(x){ return x.id!==it.id; });
  made.forEach(function(m){ state.items.push(m); });
  selSet={}; made.forEach(function(m){ selSet[m.id]=true; }); sel=made[made.length-1].id;
  render(); save();
}
