      var corU={donna:false, micMode:"tonda"}, corD={donna:true, micMode:"tonda"};
      body.appendChild(makeBtn("corista","Uomo", corU, "voce")); n++;
      entries.push({k:"corista", nome:"Uomo", over:corU, dim:"voce"});
