    if(_qaAll[i].indexOf(q)===-1) continue;
    var n=_qaName[i], s=_qaStrong[i], r;
    if(n.indexOf(q)===0) r=0;
    else if(qaWordStart(n,q)) r=1;
    else if(qaWordStart(s,q)) r=2;
    else if(n.indexOf(q)>-1) r=3;
    else if(s.indexOf(q)>-1) r=4;
    else r=5;
