  var box=document.createElement("div"); box.id="quickAdd"; box.className="quick-add";
  box.style.left=Math.max(8, Math.min(cx, window.innerWidth-288))+"px";
  box.style.top=Math.max(8, Math.min(cy, window.innerHeight-336))+"px";
