  var pad=" "+id+" ", any=false;
  gs.forEach(function(g){ if((" "+(g.getAttribute("data-own")||"")+" ").indexOf(pad)>=0) any=true; });
  if(!any){ gs.forEach(function(g){ g.classList.remove("dim"); }); return; }
