/* Le quattro azioni distruttive sulle liste usano la finestra dell'app, non i dialoghi nativi del
   browser (audit 27/07): quelli si possono sopprimere — e allora l'azione o non parte più o parte
   senza chiedere — e bloccavano la scheda al secondo click. */
function askThenRun(hasContent, title, message, confirmText, run){
  if(!hasContent){ run(); return; }
  confirmDialog({icon:"warn", title:title, message:message, confirmText:confirmText})
    .then(function(ok){ if(ok) run(); });
}
