/* ============ TASTIERA ============ */
/* A11y canvas (audit H-10): annunci per screen reader nella regione #a11yLive. */
function a11yAnnounce(msg){ var el=document.getElementById("a11yLive"); if(!el) return; el.textContent=""; setTimeout(function(){ el.textContent=msg; }, 30); }
function a11yDesc(it){ if(!it) return ""; var nm=(it.label!=null&&it.label!=="")?String(it.label):(typeof defaultLabel==="function"?defaultLabel(it.type):String(it.type||"elemento")); return nm+", posizione "+Math.round(it.x)+", "+Math.round(it.y)+(it.rot?(", ruotato "+Math.round(it.rot)+" gradi"):""); }
function a11yItemIndex(id){ var a=state.items||[]; for(var i=0;i<a.length;i++){ if(a[i].id===id) return i; } return -1; }
/* Finestre costruite fuori dal motore di dialogo: nessuna aveva un gestore di Esc, e «Produzione —
   reparti» restava perfino a intercettare i click. In più un solo Esc chiudeva TRE livelli insieme
   (finestra + selezione sul palco + ricerca nel catalogo): ora chiude un livello per volta. (06/08) */
var ESC_MODALS=["prodModal","rubModal","learn","clDlg","csvPicker","cloudModal"];
function escCloseTopModal(target){
  var inField=target && /INPUT|SELECT|TEXTAREA/.test(target.tagName||"");
  for(var i=ESC_MODALS.length-1;i>=0;i--){
    var m=document.getElementById(ESC_MODALS[i]);
    /* «aperta» = si vede davvero: alcune di queste finestre non usano l'attributo hidden ma il CSS,
       e fidarsi del solo hidden faceva mangiare l'Esc a una finestra invisibile */
    if(!m || m.hidden || !m.getClientRects().length) continue;
    /* Esc dentro un campo della finestra chiude la finestra: molte si aprono col fuoco già in un
       input (Produzione), e lasciarle aperte significava lasciarle a intercettare i click. */
    if(inField && !m.contains(target)) continue;
    m.hidden=true; return true;
  }
  return false;
}
document.addEventListener("keydown", function(e){
  if(clOpen && e.key==="Escape"){ clShow(false); return; }   /* channel list a schermo intero */
  if(e.key==="Escape" && escCloseTopModal(e.target)) return;
  /* durante la scelta dell'area di stampa Esc vale «annulla questo passo»: riporta alla finestra
     Esporta da cui si è partiti, invece di lasciare sul canvas senza né finestra né pannello */
  if(e.key==="Escape" && typeof frameEdit!=="undefined" && frameEdit && typeof finishFrameEdit==="function"){
    /* stopImmediatePropagation: più avanti c'è il listener che chiude la finestra Esporta con Esc, e
       nello stesso evento richiuderebbe quella che stiamo riaprendo qui */
    e.stopImmediatePropagation(); finishFrameEdit(); return; }
  var modal=document.getElementById("orchModal");
  if(!modal.hidden && e.key==="Escape"){ modal.hidden=true; return; }
  var strModal=document.getElementById("stringModal");
  if(!strModal.hidden && e.key==="Escape"){ strModal.hidden=true; return; }
  var legM=document.getElementById("legniModal"); if(!legM.hidden && e.key==="Escape"){ legM.hidden=true; return; }
  var ottM=document.getElementById("ottoniModal"); if(!ottM.hidden && e.key==="Escape"){ ottM.hidden=true; return; }
  /* Selezione da tastiera sul canvas (H-10): quando l'SVG ha il focus, Tab/Shift+Tab scorrono gli
     elementi in ordine di documento e li annunciano. Oltre l'ultimo (o prima del primo) si esce dal
     canvas lasciando passare il Tab del browser → nessuna trappola di focus. Sola navigazione: ok
     anche a progetto bloccato. */
  var _svg=document.getElementById("svg");
  if(e.key==="Tab" && document.activeElement===_svg){
    var order=(state.items||[]).filter(function(x){ return x && x.id!=null; });
    if(order.length){
      var ci=-1; for(var _i=0;_i<order.length;_i++){ if(order[_i].id===sel){ ci=_i; break; } }
      if(!e.shiftKey){
        if(ci<0){ e.preventDefault(); selectOne(order[0].id); render(); a11yAnnounce("Selezionato "+a11yDesc(getSel())+". 1 di "+order.length); return; }
        if(ci<order.length-1){ e.preventDefault(); selectOne(order[ci+1].id); render(); a11yAnnounce(a11yDesc(getSel())+". "+(ci+2)+" di "+order.length); return; }
        clearSelection(); render();   /* oltre l'ultimo: esci dal canvas */
      } else {
        if(ci<0){ e.preventDefault(); selectOne(order[order.length-1].id); render(); a11yAnnounce("Selezionato "+a11yDesc(getSel())+". "+order.length+" di "+order.length); return; }
        if(ci>0){ e.preventDefault(); selectOne(order[ci-1].id); render(); a11yAnnounce(a11yDesc(getSel())+". "+ci+" di "+order.length); return; }
        clearSelection(); render();   /* prima del primo: esci */
      }
    }
  }
  /* SOLA LETTURA — progetto bloccato (__projLocked) OPPURE documento di qualcun altro aperto da link
     condiviso / consulenza lato cliente (body.viewmode). Il viewer si difendeva col solo
     `pointer-events:none` sul palco: il mouse non lo toccava, la TASTIERA sì — Tab dava il fuoco
     all'SVG, le frecce spostavano gli elementi, Canc li cancellava, ⌘D duplicava. Qui si legge.
     Restano fuori dal blocco: Tab/Esc (navigazione e accessibilità), ⌘C (copia, non modifica) e ⌘S
     in consulenza, che è il salvataggio autorizzato del consulente, non una scrittura sul documento. */
  var _soloLettura = window.__projLocked || document.body.classList.contains("viewmode");
  if(_soloLettura && !/INPUT|SELECT|TEXTAREA/.test(e.target.tagName) && !(e.target&&e.target.isContentEditable)){
    var _modifica = e.key==="Delete" || e.key==="Backspace" || /^Arrow/.test(e.key)
      || (!e.metaKey && !e.ctrlKey && !e.altKey && /^[rd]$/i.test(e.key))            /* r/R ruota, d/D duplica */
      || ((e.metaKey||e.ctrlKey) && /^(v|z|y|d|x)$/i.test(e.key))
      || ((e.metaKey||e.ctrlKey) && /^s$/i.test(e.key) && window.__projLocked);
    if(e.key!=="Escape" && _modifica){
      e.preventDefault();
      /* col tasto tenuto premuto il keydown si ripete: un toast al secondo basta a spiegarlo */
      if(window.__toast && (!window.__roToastAt || (e.timeStamp - window.__roToastAt) > 1000)){
        window.__roToastAt = e.timeStamp;
        window.__toast(window.__projLocked
          ? "Il progetto è bloccato. Sbloccalo per modificarlo."
          : "Questo è un link in sola lettura: il progetto si legge, non si modifica.");
      }
      return;
    }
  }
  if((e.metaKey||e.ctrlKey) && (e.key==="s"||e.key==="S")){ e.preventDefault();
    if(window.__consultMode){ var liveSave=document.getElementById("viewSave"); if(liveSave&&!liveSave.disabled) liveSave.click(); }
    else if(!document.body.classList.contains("viewmode") && window.fileSaveVersion) fileSaveVersion();
    return;
  }
  /* ⌘N = nuovo progetto (richiesta Simone). NB: Chrome spesso NON consegna ⌘N alla pagina (finestra
     nuova riservata) — per questo vale anche ⌥⌘N, sempre consegnato. e.code copre l'Alt su Mac. */
  if((e.metaKey||e.ctrlKey) && !e.shiftKey && (e.key==="n"||e.key==="N"||e.code==="KeyN")){ e.preventDefault();
    if(window.__consultMode){ if(window.__toast) window.__toast("Nuovo progetto non disponibile durante la consulenza.",true); }
    else if(!document.body.classList.contains("viewmode") && window.proxyClick) proxyClick("bNew");
    return;
  }
  if((e.metaKey||e.ctrlKey) && (e.key==="p"||e.key==="P")){ e.preventDefault(); if(!document.body.classList.contains("viewmode") && window.proxyClick) window.proxyClick("bHdrPdf"); return; }   /* U1: Cmd/Ctrl+P = come "Esporta PDF…" (apre l'hub Esporta centrato, non la stampa del browser) */
  if((e.metaKey||e.ctrlKey) && (e.key==="z"||e.key==="Z")){ e.preventDefault(); if(e.shiftKey) redo(); else undo(); return; }
  if((e.metaKey||e.ctrlKey) && (e.key==="y"||e.key==="Y")){ e.preventDefault(); redo(); return; }
  /* spacebar → modalità pan temporanea (come Figma/Photoshop) */
  if(e.key===" " && !/INPUT|SELECT|TEXTAREA/.test(e.target.tagName) && !e.metaKey && !e.ctrlKey){
    e.preventDefault();
    if(!spacebarPan){ spacebarPan=true; document.body.classList.add("space-pan"); }
    return;
  }
  /* modalità Palco: Invio = conferma (Fatto), Backspace/Canc = elimina il blocco selezionato */
  if(stageEdit){
    if(e.key==="Enter"){ e.preventDefault(); if(document.activeElement && document.activeElement.blur) document.activeElement.blur(); toggleStageEdit(); return; }
    if((e.key==="Backspace"||e.key==="Delete") && !/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)){ e.preventDefault(); delSelBlock(); return; }
  }
  /* Esc dentro un campo: chiude la ricerca del catalogo e lascia il campo. Ma se il campo sta DENTRO
     una finestra (il link di Condividi, un nome nel pannello…), il palco sotto non si tocca: lì Esc
     vale per la finestra, e portarsi via anche la selezione era il terzo livello chiuso a tradimento
     dallo stesso tasto (06/08). */
  if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)){
    if(e.key==="Escape"){
      var _inFinestra=e.target.closest && e.target.closest(".modal,#learn,#clDlg,.hdrmenu,#prodModal,#rubModal,#versPanel,#props");
      if(_inFinestra){ e.target.blur(); return; }
      endCatSearch(); e.target.blur(); clearSelection(); render();
    }
    return; }
  /* cavo selezionato: Backspace/Canc lo toglie (richiesta Simone). In manual-first = SCOLLEGA
     (la sorgente torna "da collegare"); in auto = eliminato col fantasma ripristinabile. */
  if((selCab || Object.keys(selCabSet).length) && (e.key==="Backspace"||e.key==="Delete")){
    e.preventDefault();
    var kk=Object.keys(selCabSet).length ? Object.keys(selCabSet) : (selCab?[selCab]:[]);
    kk.forEach(cabDeleteKey);
    selCab=null; selCabSet={}; __cabRes=null; save(); render(); renderCabPanel();
    return;
  }
  if(selElec && (e.key==="Backspace"||e.key==="Delete")){   /* linea elettrica: scollega (parità con l'audio) */
    e.preventDefault();
    if(selElec.indexOf("up:")===0){ if(state.elec.uplinks) delete state.elec.uplinks[selElec.slice(3)]; }
    else if(state.elec.mode!=="auto"){ if(state.elec.manual) delete state.elec.manual[selElec]; }
    else { state.elec.manual=state.elec.manual||{}; state.elec.manual[selElec]={deleted:true}; }
    selElec=null; __elecRes=null; save(); render(); renderElecPanel();
    return;
  }
  if(selMond && (e.key==="Backspace"||e.key==="Delete")){   /* monitor digitale: scollega */
    e.preventDefault();
    var cmm=mondManual(selMond); delete cmm.to; delete cmm.pts; if(!Object.keys(cmm).length) delete state.mond.manual[selMond];
    selMond=null; __mondRes=null; save(); render();
    return;
  }
  if((e.metaKey||e.ctrlKey) && (e.key==="c"||e.key==="C")){ e.preventDefault(); copySel(); return; }   /* Cmd/Ctrl+C copia */
  if((e.metaKey||e.ctrlKey) && (e.key==="v"||e.key==="V")){ e.preventDefault(); pasteClip(); return; }  /* Cmd/Ctrl+V incolla */
  if((e.metaKey||e.ctrlKey) && (e.key==="x"||e.key==="X")){ e.preventDefault(); if(getSel()){ copySel(); deleteSel(); } return; }   /* Cmd/Ctrl+X taglia */
  if((e.key==="a"||e.key==="A") && !e.metaKey && !e.ctrlKey){ e.preventDefault(); fit(); return; }   /* "a" → adatta la vista al contenuto (palco + elementi, anche fuori palco), come il bottone Adatta */
  var it=getSel(), step = e.shiftKey?25:5;
  /* Esc chiude UN livello per volta: se sopra il palco c'è ancora qualcosa di aperto (una finestra
     che ha già i suoi gestori, o un menu), il palco sotto non si tocca — prima lo stesso Esc chiudeva
     la finestra E deselezionava E azzerava la ricerca nel catalogo, tre stati in un colpo (06/08). */
  if(e.key==="Escape"){
    /* «aperta» si misura sulla visibilità reale: alcune finestre non usano l'attributo hidden */
    var _apri=Array.prototype.slice.call(document.querySelectorAll(".modal,#learn,#clDlg,.hdrmenu,#prodModal,#rubModal,#versPanel"))
      .filter(function(x){ return !x.hidden && x.getClientRects().length; });
    if(_apri.length) return;
  }
  if(e.key==="Escape"){ exitHubModes(); clearSelection(); if(!endCatSearch()) collapseCats();   /* con una ricerca aperta, Esc riporta la colonna in stato di partenza (campo vuoto, in cima) */
    exitListMode();   /* ESC: i layer si deselezionano e tornano alla modalità base */
    render(); }
  if(!it) return;
  if(e.key==="Backspace"||e.key==="Delete"){ e.preventDefault(); var _dn=a11yDesc(it); deleteSel(); a11yAnnounce(_dn+" eliminato"); }
  else if(e.key==="r"){ rotateSel(15); a11yAnnounce("Ruotato a "+Math.round((getSel()||it).rot||0)+" gradi"); }
  else if(e.key==="R"){ rotateSel(-15); a11yAnnounce("Ruotato a "+Math.round((getSel()||it).rot||0)+" gradi"); }
  else if(e.key==="d"||e.key==="D"){ duplicateSel(); a11yAnnounce("Duplicato: "+a11yDesc(getSel())); }
  else if(e.key.indexOf("Arrow")===0){
    e.preventDefault();
    var dx=0,dy=0;
    if(e.key==="ArrowLeft") dx=-step; if(e.key==="ArrowRight") dx=step;
    if(e.key==="ArrowUp") dy=-step; if(e.key==="ArrowDown") dy=step;
    selItems().filter(itemEditable).forEach(function(s){ s.x+=dx; s.y+=dy; });   /* col lucchetto chiuso le frecce non lo muovono */
    render(); save(); ensureVisible(); a11yAnnounce(a11yDesc(getSel()));
  }
});
document.addEventListener("keyup", function(e){
  if(e.key===" "){ spacebarPan=false; document.body.classList.remove("space-pan"); }
});
window.addEventListener("blur", function(){ spacebarPan=false; document.body.classList.remove("space-pan"); });

/* ============ GENERATORE ORGANICO ORCHESTRA ============ */
/* Disposizione standard (direttore fronte-centro, archi ad arco, legni/ottoni in file, percussioni in fondo).
   Spaziature reali: ~100 cm tra leggii in fila, ~125 cm tra le file. */
var ORCH_DEF = [
  {id:"v1", nome:"Violini I",   def:12, type:"vlnpost",     arc:[-82,-55], sp:175},
  {id:"v2", nome:"Violini II",  def:10, type:"vlnpost",     arc:[-20,-8],  sp:175},
  {id:"vle",nome:"Viole",       def:8,  type:"violapost",   arc:[12,24],   sp:175},
  {id:"vc", nome:"Violoncelli", def:6,  type:"violoncello", arc:[62,76],   sp:195},
  {id:"cb", nome:"Contrabbassi",def:4,  type:"contrabbasso",arc:[72,84],   sp:220, rowStart:2},
  {id:"fl", nome:"Flauti",      def:2,  type:"flauto",      row:0, slot:0},
  {id:"ob", nome:"Oboi",        def:2,  type:"oboe",        row:0, slot:1},
  {id:"cl", nome:"Clarinetti",  def:2,  type:"clarinetto",  row:1, slot:0},
  {id:"fg", nome:"Fagotti",     def:2,  type:"fagotto",     row:1, slot:1},
  {id:"cor",nome:"Corni",       def:4,  type:"corno",       row:2, slot:0},
  {id:"tr", nome:"Trombe",      def:3,  type:"tromba",      row:2, slot:1},
  {id:"tbn",nome:"Tromboni",    def:3,  type:"trombone",    row:2, slot:2},
  {id:"tba",nome:"Tuba",        def:1,  type:"tuba",        row:2, slot:3},
  {id:"arp",nome:"Arpa",        def:1,  type:"arpa",        spot:{a:-58, f:0.82}},
  {id:"pf", nome:"Pianoforte",  def:0,  type:"grancoda",    spot:{a:-73, f:1.0}},
  {id:"cel",nome:"Celesta",     def:0,  type:"celesta",     spot:{a:-66, f:1.18}},
  {id:"tim",nome:"Timpani (set 4)",def:1,type:"timpani",    back:0, parts:{count:4,layout:"arco",orient:"americano"}},
  {id:"gc", nome:"Gran cassa",  def:1,  type:"grancassa",   back:1},
  {id:"pia",nome:"Piatti",      def:1,  type:"piatticoppia",back:2},
  {id:"rul",nome:"Rullante",    def:1,  type:"rullante",    back:3},
  {id:"cmp",nome:"Campane tubolari",def:0,type:"campane",   back:4},
  {id:"tam",nome:"Tam-tam",     def:0,  type:"tamtam",      back:5}
];

var pendingOut = null;
var pendingReviewModal = "orchModal";
var ORCH_PRESETS = [
  {id:"quartetto", nome:"Quartetto archi — 2.0.1.1", hint:"Quartetto classico: 2 violini, viola e violoncello. Ideale per piccoli palchi o cerimonie.", counts:{v1:2,v2:0,vle:1,vc:1}},
  {id:"archi_compatto", nome:"Ensemble archi compatto — 2.2.1.1", hint:"Piccolo ensemble archi per palchi ridotti; buona base per eventi cameristici.", counts:{v1:2,v2:2,vle:1,vc:1}},
  {id:"camera", nome:"Orchestra da camera — archi 4.4.3.2.1", hint:"Camera orchestra: archi piccoli, legni a uno, due corni; patch list a spot/area.", counts:{v1:4,v2:4,vle:3,vc:2,cb:1,fl:1,ob:1,cl:1,fg:1,cor:2}},
  {id:"ridotta", nome:"Sinfonica ridotta — archi 6.5.4.3.2", hint:"Sinfonica ridotta per teatro/piazza: legni a due, ottoni essenziali, arpa e timpani.", counts:{v1:6,v2:5,vle:4,vc:3,cb:2,fl:2,ob:2,cl:2,fg:2,cor:3,tr:2,tbn:1,arp:1,tim:1}},
  {id:"standard", nome:"Sinfonica completa — archi 12.10.8.6.4", hint:"Organico standard completo. Richiede un palco ampio o l'adattamento automatico del palco.", counts:null}
];
function defaultOrchCounts(){
  var c={}; ORCH_DEF.forEach(function(s){ c[s.id]=s.def; }); return c;
}
function orchTotal(counts){
  return ORCH_DEF.reduce(function(sum,s){ return sum+(counts[s.id]||0); },0);
}
function cloneCounts(counts){
  var c={}; ORCH_DEF.forEach(function(s){ c[s.id]=counts[s.id]||0; }); return c;
}
function presetById(id){
  return ORCH_PRESETS.find(function(p){ return p.id===id; }) || ORCH_PRESETS[0];
}
function presetCounts(id){
  var p=presetById(id);
  return p.counts ? cloneCounts(p.counts) : defaultOrchCounts();
}
/* ARCHI: file concentriche CONTINUE attorno al podio, partizionate per sezione.
   Ogni fila è un arco unico (V1 a sx del direttore → V2 → Viole → Vc a dx); passo angolare
   costante = posti affiancati lungo la curva, tutti rivolti al podio. Cb dietro i Vc, a destra.
   Restituisce il raggio esterno (per posizionare legni/ottoni dietro). */
var STR_R0=290, STR_DR=150;
function layoutStrings(counts, out){
  var secs=[["v1","Violini I","vlnpost","Violino I"],["v2","Violini II","vlnpost","Violino II"],
            ["vle","Viole","violapost","Viola"],["vc","Violoncelli","violoncello","Violoncello"]];
  var sizes=secs.map(function(s){ return counts[s[0]]||0; });
  var total=sizes.reduce(function(a,b){ return a+b; },0);
  if(!total) return STR_R0;
  var rows = total<=8 ? 1 : (total<=20 ? 2 : 3);
  /* ripartizione di ogni sezione sulle file (file davanti ≥ dietro) */
  var split=sizes.map(function(n){
    var base=Math.floor(n/rows), extra=n-base*rows, a=[];
    for(var r=0;r<rows;r++) a.push(base+(r<extra?1:0));
    return a;
  });
  var P=2*Math.asin(Math.min(0.5, 56/STR_R0));   /* passo angolare ~ corda 112 cm */
  var m0=split.reduce(function(a,s){ return a+s[0]; },0);   /* posti in prima fila */
  var secCount=[0,0,0,0];   /* numerazione progressiva per sezione: ogni leggio ha un nome */
  for(var r=0;r<rows;r++){
    var rowSeats=[];
    secs.forEach(function(s,i){
      var k=split[i][r];
      for(var j=0;j<k;j++){ secCount[i]++; rowSeats.push({type:s[2], lbl:s[3]+" "+secCount[i], vsec:(i===0?1:i===1?2:0)}); }
    });
    var m=rowSeats.length; if(!m) continue;
    var R=STR_R0+STR_DR*r;
    for(var idx=0; idx<m; idx++){
      var a=(idx-(m-1)/2)*P, x=R*Math.sin(a), y=-R*Math.cos(a);
      var o={type:rowSeats[idx].type, x:Math.round(x), y:Math.round(y),
        rot:Math.round(a*180/Math.PI), label:rowSeats[idx].lbl};
      if(rowSeats[idx].vsec) o.vsec=rowSeats[idx].vsec;
      out.push(o);
    }
  }
  /* Contrabbassi: arco corto dietro/destra dei violoncelli */
  var nb=counts.cb||0, outerRows=rows;
  if(nb){
    var R=STR_R0+STR_DR*rows, a0=(m0-1)/2*P*0.55;
    for(var j=0;j<nb;j++){
      var a=a0+j*P, x=R*Math.sin(a), y=-R*Math.cos(a);
      out.push({type:"contrabbasso", x:Math.round(x), y:Math.round(y),
        rot:Math.round(a*180/Math.PI), label:"Contrabbasso "+(j+1)});
    }
    outerRows=rows+1;
  }
  return STR_R0+STR_DR*outerRows;
}

function buildOrchestraOut(counts){
  var out=[];
  function rad(g){ return g*Math.PI/180; }
  function rotTo(x,y){ return Math.atan2(x,-y)*180/Math.PI; }  /* postazione rivolta al podio */

  /* 1. archi: file concentriche continue attorno al podio */
  var stringOuter=layoutStrings(counts, out);

  /* 2. legni e ottoni: file diritte dietro gli archi, gruppi affiancati */
  var DR=175, windBase=stringOuter+40, rows={}, maxWindRow=-1;
  ORCH_DEF.forEach(function(sec){
    var n=counts[sec.id]||0;
    if(n && sec.row!=null){ (rows[sec.row]=rows[sec.row]||[]).push(sec); maxWindRow=Math.max(maxWindRow,sec.row); }
  });
  Object.keys(rows).forEach(function(ri){
    ri=+ri;
    var groups=rows[ri].sort(function(a,b){ return a.slot-b.slot; });
    var sp=130, gap=95, seats=[], cur=0;
    groups.forEach(function(g){
      var n=counts[g.id];
      for(var i=0;i<n;i++){ seats.push({g:g,i:i,n:n,x:cur}); cur+=sp; }
      cur+=gap;
    });
    var tot=cur-sp-gap, y=-(windBase+DR*ri);
    seats.forEach(function(s){
      var x=s.x-tot/2;
      out.push({type:s.g.type, x:x, y:y, rot:rotTo(x,y),
        label: (autoNumbered(s.g.type)?instrBase(s.g.type):(DEFAULT_LABELS[s.g.type]||s.g.nome))+(s.n>1?" "+(s.i+1):"")});   /* stesso nome pieno del catalogo (Corno 1, non Cor 1) */
    });
  });

  /* 3. percussioni: linea in fondo, centrata */
  var backs=ORCH_DEF.filter(function(s){ return s.back!=null && (counts[s.id]||0)>0; })
                    .sort(function(a,b){ return a.back-b.back; });
  if(backs.length){
    var maxD=0, totW=0;
    backs.forEach(function(b){ maxD=Math.max(maxD,TYPES[b.type].d); totW+=TYPES[b.type].w; });
    totW+=70*(backs.length-1);
    var backY=-(windBase+DR*(maxWindRow+1)+25+maxD/2), cx=-totW/2;
    out.push({type:"pedana", x:0, y:backY, w:Math.max(500,totW+150), d:maxD+90, h:20, label:""});  /* riser percussioni */
    backs.forEach(function(b){
      var w=TYPES[b.type].w;
      out.push({type:b.type, x:cx+w/2, y:backY, rot:0, label:(autoNumbered(b.type)?instrBase(b.type):b.nome), parts:b.parts});   /* "Timpani", non "Timpani (set 4)" */
      cx+=w+70;
    });
  }

  /* 4. arpa / pianoforte / celesta a sinistra */
  ORCH_DEF.forEach(function(sec){
    var n=counts[sec.id]||0; if(!n || !sec.spot) return;
    for(var i=0;i<n;i++){
      var r=windBase*sec.spot.f+i*130, a=rad(sec.spot.a);
      var x=r*Math.sin(a), y=-r*Math.cos(a);
      out.push({type:sec.type, x:x, y:y, rot:rotTo(x,y), label:(autoNumbered(sec.type)?instrBase(sec.type):sec.nome)+(n>1?" "+(i+1):"")});
    }
  });

  /* 5. podio + dimensionamento palco */
  out.push({type:"podio", x:0, y:0, rot:0, label:""});
  return out;
}

function buildStringOrganicoOut(counts, opts){
  opts=opts||{};
  var out=[];
  var sections=[
    {id:"v1", double:"vln1x2", single:"vlnpost", singleLabel:"Violini I"},
    {id:"v2", double:"vln2x2", single:"vlnpost", singleLabel:"Violini II"},
    {id:"vle",double:"violax2", single:"violapost", singleLabel:"Viole"},
    {id:"vc", double:"cellix2", single:"violoncello", singleLabel:"Violoncelli"}
  ];
  function desksFor(sec){
    var n=counts[sec.id]||0, desks=[], pairs=Math.floor(n/2), idx=0;
    for(var i=0;i<pairs;i++){ idx++; desks.push({type:sec.double, label:sec.singleLabel+" "+idx}); }
    if(n%2){ idx++; desks.push({type:sec.single, label:sec.singleLabel+" "+idx}); }
    return desks;
  }
  var secDesks=sections.map(function(sec){ return {sec:sec, desks:desksFor(sec)}; });
  var totalDesks=secDesks.reduce(function(sum,s){ return sum+s.desks.length; },0);
  var rows = totalDesks<=8 ? 1 : (totalDesks<=18 ? 2 : 3);
  var split=secDesks.map(function(s){
    var n=s.desks.length, base=Math.floor(n/rows), extra=n-base*rows, a=[], pos=0;
    for(var r=0;r<rows;r++){
      var take=base+(r<extra?1:0);
      a.push(s.desks.slice(pos,pos+take)); pos+=take;
    }
    return a;
  });
  var R0=300, DR=165, P=2*Math.asin(Math.min(0.6, 92/R0));
  var outerRows=rows;
  for(var r=0;r<rows;r++){
    var row=[];
    split.forEach(function(secRows){ secRows[r].forEach(function(d){ row.push(d); }); });
    var m=row.length; if(!m) continue;
    var R=R0+DR*r;
    for(var idx=0; idx<m; idx++){
      var a=(idx-(m-1)/2)*P, x=R*Math.sin(a), y=-R*Math.cos(a);
      out.push({type:row[idx].type, x:Math.round(x), y:Math.round(y), rot:Math.round(a*180/Math.PI), label:row[idx].label});
    }
  }
  var cbN=counts.cb||0;
  if(cbN){
    var cbDesks=[], cbPairs=Math.floor(cbN/2), ci=0;
    for(var c=0;c<cbPairs;c++){ ci++; cbDesks.push({type:"cbx2", label:"Contrabbassi "+ci}); }
    if(cbN%2){ ci++; cbDesks.push({type:"contrabbasso", label:"Contrabbassi "+ci}); }
    var cbR=R0+DR*rows+90, cbP=2*Math.asin(Math.min(0.5, 110/cbR));
    var baseA=(totalDesks?((Math.max(3,totalDesks)-1)/2)*P*0.34:0.28);
    cbDesks.forEach(function(d,i){
      var a=baseA+i*cbP, x=cbR*Math.sin(a), y=-cbR*Math.cos(a);
      out.push({type:d.type, x:Math.round(x), y:Math.round(y), rot:Math.round(a*180/Math.PI), label:d.label});
    });
    outerRows=rows+1;
  }
  if(opts.stereo) out.push({type:"coppiast", x:0, y:-125, rot:0, label:"ST archi"});
  if(opts.podio!==false) out.push({type:"podio", x:0, y:0, rot:0, label:"Podio"});
  return out;
}
function genStringOrganico(counts, opts, fitStage, clearFirst, force){
  pendingReviewModal="stringModal";
  return placeOut(buildStringOrganicoOut(counts, opts), fitStage, clearFirst, force);
}

function odim(o){ var t=TYPES[o.type]; return {w:(o.w!=null?o.w:t.w), d:(o.d!=null?o.d:t.d)}; }
function measureOrchestraOut(out){
  var minY=0, maxY=0, maxX=0;
  out.forEach(function(o){ var z=odim(o);
    minY=Math.min(minY, o.y-z.d/2-20); maxY=Math.max(maxY, o.y+z.d/2+20); maxX=Math.max(maxX, Math.abs(o.x)+z.w/2+20); });
  return {minY:minY, maxY:maxY, maxX:maxX};
}
/* margine fronte palco (verso il pubblico) = spazio davanti al riferimento; cresce se ci sono elementi davanti */
function frontPad(m){ return Math.max(150, (m.maxY||0)+60); }

function assessOut(out, stageW, stageD, fp){
  var m=measureOrchestraOut(out), C={x:stageW/2, y:stageD-fp};
  var tooSmall = (C.y+m.minY<0 || C.y+m.maxY>stageD || C.x-m.maxX<0 || C.x+m.maxX>stageW);
  /* gli elementi di sfondo (pedane, tappeti) possono stare sotto altri: non contano come sovrapposizione */
  var boxes = out.map(function(o){
    var z=odim(o);
    return {x:C.x+o.x, y:C.y+o.y, r:Math.max(24, Math.max(z.w,z.d)*0.48), bg:(TYPES[o.type].z||2)<=1};
  });
  var overlaps=0;
  for(var bi=0; bi<boxes.length; bi++){
    for(var bj=bi+1; bj<boxes.length; bj++){
      if(boxes[bi].bg || boxes[bj].bg) continue;
      if(Math.hypot(boxes[bi].x-boxes[bj].x, boxes[bi].y-boxes[bj].y)<boxes[bi].r+boxes[bj].r) overlaps++;
    }
  }
  return {tooSmall:tooSmall, overlaps:overlaps, relevantOverlaps:overlaps, measure:m};
}

function orchestraScore(counts, stageW, stageD){
  var out=buildOrchestraOut(counts), m=measureOrchestraOut(out), fp=frontPad(m), C={x:stageW/2, y:stageD-fp};
  var overflow =
    Math.max(0, -(C.y+m.minY))+
    Math.max(0, C.y+m.maxY-stageD)+
    Math.max(0, -(C.x-m.maxX))+
    Math.max(0, C.x+m.maxX-stageW);
  var a=assessOut(out, stageW, stageD, fp);
  return overflow + a.relevantOverlaps*35;
}



function applyOrchestraPreset(presetId){
  var preset=presetById(presetId), counts=presetCounts(presetId);
  ORCH_DEF.forEach(function(s){
    var input=document.getElementById("orch_"+s.id);
    if(input) input.value=counts[s.id]||0;
  });
  document.getElementById("orchFit").checked=false;
  document.getElementById("orchHint").textContent =
    preset.hint+" Totale: "+orchTotal(counts)+" postazioni. Puoi modificare i numeri; se non entra, l'app ti avvisa prima di piazzarlo.";
}

/* Piazza una lista di postazioni (out, coord. relative al riferimento) sul palco.
   Riusato da organico orchestra e da tutte le formazioni tipo. */
function placeOut(out, fitStage, clearFirst, force){
  var m=measureOrchestraOut(out), fp=frontPad(m);
  if(fitStage){
    var nw=Math.max(800, Math.ceil((2*m.maxX+160)/50)*50);
    var nd=Math.max(600, Math.ceil((-m.minY+fp+60)/50)*50);
    var h0=stageBlocks()[0].h||0;
    state.stage.blocks=[{x:0,y:0,w:nw,d:nd,h:h0}];   /* adatta palco = palco rettangolare che contiene l'organico (il bbox è ricalcolato dai blocchi) */
    state.stage.w=nw; state.stage.d=nd;
  }
  var C={x:state.stage.w/2, y:state.stage.d-fp};
  var assessment=assessOut(out, state.stage.w, state.stage.d, fp);
  if(!force && (assessment.tooSmall || assessment.relevantOverlaps>0)){
    pendingOut={out:out, fitStage:fitStage, clearFirst:clearFirst};
    var msg=[];
    if(assessment.tooSmall) msg.push("Il palco è troppo piccolo: alcune postazioni escono dall'area utile.");
    if(assessment.relevantOverlaps>0) msg.push("La disposizione automatica crea "+assessment.overlaps+" sovrapposizion"+(assessment.overlaps===1?"e":"i")+" tra postazioni.");
    msg.push("Puoi continuare e poi sistemare a mano, oppure rivedere l'organico.");
    document.getElementById("orchWarnText").textContent=msg.join(" ");
    document.getElementById(pendingReviewModal||"orchModal").hidden=true;
    document.getElementById("orchWarnModal").hidden=false;
    return false;
  }
  if(clearFirst) state.items=[];
  var news=out.map(function(o){
    var t=TYPES[o.type], z=odim(o);
    var it={id:uid(), type:o.type, x:Math.round(C.x+o.x), y:Math.round(C.y+o.y),
            rot:Math.round((o.rot||0)/5)*5, w:z.w, d:z.d, label:o.label!=null?o.label:defaultLabel(o.type)};
    if(t.riser) it.h=(o.h!=null?o.h:(t.h||40));
    else if(isCover(it) && o.h!=null) it.h=+o.h;   /* coperture: h opzionale (luce sotto) */
    if(o.parts){ it.parts=compClone(o.parts); if(COMP[o.type] && COMP[o.type].size){ var cz=COMP[o.type].size(it); it.w=cz[0]; it.d=cz[1]; } }
    ["donna","hair","mano","leggio","sedia","doppia","sep","ampli","pedaliera","vsec","label2","podio","nomic","micMode","hw","ch","outCh"].forEach(function(k){ if(o[k]!=null) it[k]=o[k]; });   /* flag opzionali dal generatore (hw/ch/outCh = capacità stage box) */
    return it;
  });
  if(!clearFirst && state.items.length) avoidGroupOverlap(news);   /* non sovrapporsi a ciò che è già sul palco */
  news.forEach(function(it){ state.items.push(it); });
  clearSelection(); save();
  return true;
}
/* sposta il nuovo gruppo DIETRO gli elementi esistenti che gli stanno davanti; allarga il palco sul fondo se serve */
function avoidGroupOverlap(news){
  var gap=45;
  function box(it){ return {x1:it.x-it.w/2, x2:it.x+it.w/2, y1:it.y-it.d/2, y2:it.y+it.d/2}; }
  function gbox(arr){ var b=null; arr.forEach(function(it){ var k=box(it);
    if(!b) b={x1:k.x1,x2:k.x2,y1:k.y1,y2:k.y2};
    else{ b.x1=Math.min(b.x1,k.x1); b.x2=Math.max(b.x2,k.x2); b.y1=Math.min(b.y1,k.y1); b.y2=Math.max(b.y2,k.y2); } });
    return b; }
  var nb=gbox(news); if(!nb) return;
  var ex=state.items.filter(function(it){ var k=box(it); return k.x2>nb.x1-gap && k.x1<nb.x2+gap; });   /* esistenti che si sovrappongono in larghezza */
  if(!ex.length) return;
  var eb=gbox(ex);
  if(nb.y2 <= eb.y1-gap || nb.y1 >= eb.y2+gap) return;   /* già libero davanti/dietro */
  var dy=(eb.y1-gap)-nb.y2;   /* negativo: porta il gruppo dietro (verso il fondo) */
  var newTop=nb.y1+dy;
  if(newTop < 30){   /* non c'è spazio dietro: allarga il palco sul fondo e sposta tutto in avanti */
    var grow=Math.ceil((30-newTop)/25)*25;
    stageBlocks()[0].d=Math.round(stageBlocks()[0].d+grow); recalcStageBBox();
    state.items.forEach(function(it){ it.y=Math.round(it.y+grow); });
    dy+=grow;
  }
  dy=Math.round(dy);
  news.forEach(function(it){ it.y+=dy; });
}
function genOrchestra(counts, fitStage, clearFirst, force){
  pendingReviewModal="orchModal";
  return placeOut(buildOrchestraOut(counts), fitStage, clearFirst, force);
}

/* ============ FORMAZIONI TIPO (band, coro, combinazioni) ============ */
/* convenzione coord.: origine = centro fronte palco; -y = verso il fondo, +y = verso il pubblico;
   -x = lato DX palco, +x = lato SX palco (come la scena). */
/**
 * Il palco della band, sulla formazione che l'utente ha dichiarato.
 *
 * Prima era un elenco fisso: una voce, un corista, una chitarra, e chi aveva due chitarre o tre
 * coristi doveva aggiungerli a mano e — soprattutto — decidere DOVE metterli. Il posizionamento è
 * la cosa che il programma sa fare e l'utente no: i cori in fila con la spaziatura giusta, la
 * seconda chitarra col suo ampli e la sua spia, tutto dentro la profondità del palco.
 *
 * Senza opzioni fa esattamente quello che faceva prima: è il modello standard, e chi non vuole
 * rispondere a niente lo ottiene con un clic.
 */
function buildBandOut(o){
  /* ORGANICO: chi sale sul palco. I valori mancanti sono la formazione tipica, così il modello
     standard resta quello di sempre per chi non risponde a niente. */
  o = o || {};
  function n(k, d){ var v = (o[k]==null) ? d : (o[k]|0); return Math.max(0, Math.min(6, v)); }
  var voce=n("voce",1), cori=n("cori",1), chit=n("chitarra",1), basso=n("basso",1),
      batt=n("batteria",1), tast=n("tastiere",1), fiati=n("fiati",0);
  var inEar = (o.ascolto === "iem");
  var out=[];

  /* Il posto migliore è quello che il modello propone; se è già occupato si prova il successivo.
     Contano solo gli ingombri che una persona non può attraversare: le spie stanno davanti a chi
     suona e non impediscono al collega di stargli accanto. */
  var NON_OSTACOLI={wedge:1, iem:1};
  function occupato(x, y, w, d){
    w=w||90; d=d||90;
    return out.some(function(e){
      if(NON_OSTACOLI[e.type]) return false;
      var ew=e.w||90, ed=e.d||90;
      return Math.abs(e.x-x) < (ew+w)/2 && Math.abs((e.y||0)-y) < (ed+d)/2;
    });
  }
  function posa(tipo, prove, extra){
    var t=TYPES[tipo]||{}, w=t.w||90, d=t.d||90;
    var p = prove.find(function(pp){ return !occupato(pp[0], pp[1], w, d); });
    /* Se nessuna delle posizioni preferite è libera si CERCA, invece di posare comunque sopra
       qualcuno: col quarto corista il ripiego finiva addosso al bassista (40 cm fra due ingombri
       che ne vogliono 58). Si allarga a cerchi dal punto preferito, un passo alla volta. */
    if(!p){
      var base=prove[0];
      cerca: for(var raggio=100; raggio<=700; raggio+=100){
        for(var ang=0; ang<8; ang++){
          var a=ang*Math.PI/4;
          var cx=Math.round(base[0]+Math.cos(a)*raggio), cy=Math.round(base[1]+Math.sin(a)*raggio*0.6);
          if(!occupato(cx, cy, w, d)){ p=[cx,cy]; break cerca; }
        }
      }
    }
    if(!p) p=prove[prove.length-1];   /* palco davvero pieno: meglio un elemento da spostare che nessuno */
    var el = {type:tipo, x:p[0], y:p[1]};
    if(extra) for(var k in extra) if(extra.hasOwnProperty(k)) el[k]=extra[k];
    out.push(el);
    return el;
  }
  function ascolto(el, chi){
    if(!el) return;
    out.push(inEar ? {type:"iem", x:el.x+52, y:el.y-20, label:"IEM "+chi.toLowerCase()}
                   : {type:"wedge", x:el.x, y:el.y+92, rot:0, label:chi});
  }

  /* FONDO — la batteria, che è il volume più grosso e sta al centro */
  for(var b=0;b<batt;b++) posa("batteria", [[0,-300],[-300,-300],[300,-300]], {label:""});
  /* LATO E CENTRO — basso e tastiere a sinistra, chitarre a destra: la disposizione classica di una
     band, quella che un fonico si aspetta di vedere aprendo il PDF. */
  for(var s2=0;s2<basso;s2++){
    var el=posa("bassstand", [[-430,-110],[-560,-110],[-430,-210]], {ampli:true, label: basso===1?"Basso":"Basso "+(s2+1)});
    ascolto(el, basso===1?"Basso":"Basso "+(s2+1));
  }
  for(var k2=0;k2<tast;k2++){
    var el2=posa("stagepiano", [[-230,-190],[-330,-250],[-130,-250]], {label: tast===1?"Tastiere":"Tastiere "+(k2+1)});
    ascolto(el2, tast===1?"Tastiere":"Tastiere "+(k2+1));
  }
  for(var g=0;g<chit;g++){
    var nomeG = chit===1 ? "Chitarra" : "Chitarra "+(g+1);
    var el3=posa("gtstand", [[430 - g*180, -110],[560,-110],[430,-210],[300,-210]], {ampli:true, label:nomeG});
    ascolto(el3, nomeG);
  }
  /* FIATI — in seconda fila, dove non coprono chi sta davanti: alternati come una sezione vera */
  var STRUM_FIATI=["saxalto","tromba","saxtenore","trombone","saxbaritono","tromba"];
  for(var f=0;f<fiati;f++){
    var tf=STRUM_FIATI[f % STRUM_FIATI.length];
    var el4=posa(tf, [[220 + f*120, -250],[-220 - f*120, -250],[220 + f*120, -330]], {});
    ascolto(el4, (TYPES[tf]||{}).nome || "Fiati");
  }
  /* FRONTE — la voce al centro, i cori accanto: entrano per ultimi ma con la priorità del centro,
     quindi la voce si posa PRIMA dei cori, o i cori le finirebbero addosso. */
  for(var v=0;v<voce;v++){
    var el5=posa("cantante", [[0,-60],[-160,-60],[160,-60]], {label: voce===1?"Voce":"Voce "+(v+1)});
    ascolto(el5, voce===1?"Voce":"Voce "+(v+1));
  }
  for(var c=0;c<cori;c++){
    var nomeC = cori===1 ? "Cori" : "Cori "+(c+1);
    var el6=posa("corista", [[190 + c*100, -60],[-190 - c*100, -60],[190 + c*100, -160],[-190 - c*100,-160]], {label:nomeC});
    ascolto(el6, nomeC);
  }
  /* NIENTE allestimento tecnico: pedana, side fill, TX in-ear, stage box e prese dipendono dal
     locale e dal service, non dalla band. Il modello è una base di partenza (decisione 16/08):
     chi ne ha bisogno li aggiunge dal catalogo, chi no non deve cancellarli. */
  return out;
}
