/* Orchestra (LIVE PA): area/spot in base a cosa è presente, NON un mic per leggio */
function orchInputs(c){
  var n=function(id){ return c[id]||0; }, ins=[];
  if(n("v1")+n("v2")+n("vle")+n("vc")>0){ ins.push(ch("Archi spot L (V1/V2)","KM184")); ins.push(ch("Archi spot R (Vle/Vc)","KM184")); }
  if(n("cb")) ins.push(ch("Contrabbassi","DPA 4099"));
  if(n("fl")+n("ob")) ins.push(ch("Legni spot L","KM184"));
  if(n("cl")+n("fg")) ins.push(ch("Legni spot R","KM184"));
  if(n("cor")) ins.push(ch("Corni","MD421"));
  if(n("tr")+n("tbn")+n("tba")) ins.push(ch("Ottoni","MD421"));
  if(n("tim")) ins.push(ch("Timpani","KM184"));
  if(n("gc")+n("pia")+n("rul")+n("cmp")+n("tam")) ins.push(ch("Percussioni","KM184","coppia alta",true));
  if(n("arp")) ins.push(ch("Arpa","DPA 4099"));
  if(n("pf")){ ins.push(ch("Pianoforte L","KM184")); ins.push(ch("Pianoforte R","KM184")); }
  if(n("cel")) ins.push(ch("Celesta","KM184"));
  ins.push(ch("Talkback direttore","SM58"));
  return ins;
}
