/* ===== Pannello AUDIT / DIAGNOSTICA ===== */
var auditActive=false, auditOpen=true;
function renderAuditPanel(){
  var sec=document.getElementById("auditSec"); if(!sec) return;
  sec.style.display = auditActive ? "block" : "none";
  if(!auditActive) return;
  document.getElementById("auditBody").style.display = auditOpen ? "block" : "none";
  document.getElementById("auditCaret").textContent = auditOpen ? "▾" : "▸";
  if(!auditOpen) return;
  var A=auditEngine();
  var col = A.grade==="Pronto"?"#0d9488" : A.grade==="Da rivedere"?"#b45309" : (A.grade==="Vuoto"?"#9ca3af":"#dc2626");
  document.getElementById("auditScore").innerHTML =
    '<div style="display:flex;align-items:center;gap:12px">'
    +'<div style="width:52px;height:52px;border-radius:50%;border:3px solid '+col+';display:flex;align-items:center;justify-content:center;font-weight:800;font-size:16px;color:'+col+'">'+A.score+'</div>'
    +'<div><div style="font-weight:700;color:'+col+'">'+esc(A.grade)+'</div><div style="font-size:11.5px;color:var(--text-3)">'+A.errs+' error'+(A.errs===1?'e':'i')+' · '+A.warns+' avvis'+(A.warns===1?'o':'i')+((A.todefs||0)>0?(' · '+A.todefs+' da definire'):'')+'</div></div></div>';
  document.getElementById("auditMetrics").innerHTML = A.audioSrc+' ingressi · '+A.monitors+' mix monitor · '+(A.totW/1000).toFixed(1).replace(".",",")+' kW · cavo ~'+A.totCableM.toFixed(0)+' m'
    +(A.weightKg>0?' · ⚖ '+fmtKg(A.weightKg):'')+(A.rackU>0?' · ▭ '+A.rackU+' U':'');
  var host=document.getElementById("auditFindings");
  host.innerHTML="";
  var probs=A.findings.filter(function(x){ return x.lvl==="err"||x.lvl==="warn"||x.lvl==="todef"; });   /* todef = aspetto da definire (fase 4): visibile ma non penalizza lo score */
  if(!probs.length){ host.innerHTML='<div style="color:var(--accent);font-size:12px">✓ Nessuna criticità: il rider sembra pronto.</div>'; return; }
  var ORD={err:0,warn:1,todef:2};
  probs.sort(function(a,b){ return (ORD[a.lvl]||3)-(ORD[b.lvl]||3); });
  probs.forEach(function(x){
    var c=x.lvl==="err"?"var(--danger,#dc2626)":(x.lvl==="todef"?"#2563eb":"#b45309");
    var row=document.createElement("div"); row.className="audit-find";
    row.innerHTML='<div class="audit-find-txt"><span style="color:'+c+'">●</span> <b>'+esc(x.cat)+'</b> — '+esc(x.msg)+(x.fix?'<div class="audit-hint">↳ '+esc(x.fix)+'</div>':'')+'</div>';
    if(x.act && typeof x.act.run==="function"){
      var b=document.createElement("button"); b.type="button"; b.className="audit-fix"; b.textContent=x.act.label;
      b.addEventListener("click", function(){ x.act.run(); });   /* la fix persiste e ridisegna da sé */
      row.appendChild(b);
    }
    host.appendChild(row);
  });
}
