/* Maniglia di ridimensionamento della colonna destra (solo desktop). Trascina la cucitura canvas↔props:
   la larghezza vive in --rail, viene persistita e ri-clampata sulla finestra; doppio click = reset.
   NIENTE adattamento automatico della vista (Simone 29/07): allargare il pannello e vedersi saltare
   lo zoom del palco a ogni presa della maniglia è peggio di un indicatore «Adatta» impreciso —
   la vista è dell'utente, e «Adatta» resta lì a un clic per chi la vuole. Inerte su mobile. */
(function(){
  var handle=document.getElementById("railHandle"); if(!handle) return;
  var DEF=310, MIN=280, MAXHARD=560;
  function railMax(){ return Math.max(MIN, Math.min(MAXHARD, window.innerWidth-220-340)); }   /* il canvas resta ≥340px */
  function savedPref(){ try{ var s=parseInt(localStorage.getItem("sp_rail"),10); if(isFinite(s)&&s>0) return s; }catch(e){} return DEF; }
  function currentRail(){ var v=parseInt(getComputedStyle(document.documentElement).getPropertyValue("--rail"),10); return isFinite(v)&&v>0?v:DEF; }
  function applyRail(px){ px=Math.round(Math.max(MIN, Math.min(railMax(), px))); document.documentElement.style.setProperty("--rail", px+"px"); return px; }
  function setRail(px){ px=applyRail(px); try{ localStorage.setItem("sp_rail", px); }catch(e){} return px; }   /* preferenza dell'utente */
  applyRail(savedPref());   /* ripristina la larghezza salvata (clampata alla finestra), senza sovrascrivere la preferenza */
  var dragging=false, startX=0, startRail=0;
  handle.addEventListener("pointerdown", function(e){
    if(window.matchMedia("(max-width:880px)").matches) return;   /* solo desktop */
    dragging=true; startX=e.clientX; startRail=currentRail(); handle.classList.add("dragging");
    try{ handle.setPointerCapture(e.pointerId); }catch(_){}
    document.body.style.cursor="col-resize"; e.preventDefault();
  });
  handle.addEventListener("pointermove", function(e){ if(dragging) applyRail(startRail-(e.clientX-startX)); });   /* trascina a sinistra = più largo */
  function endDrag(e){
    if(!dragging) return; dragging=false; handle.classList.remove("dragging");
    try{ handle.releasePointerCapture(e.pointerId); }catch(_){}
    document.body.style.cursor=""; setRail(currentRail());   /* la vista resta dov'era: nessun adattamento a sorpresa */
  }
  handle.addEventListener("pointerup", endDrag);
  handle.addEventListener("pointercancel", endDrag);
  handle.addEventListener("dblclick", function(){ setRail(DEF); });   /* reset della LARGHEZZA, non della vista */
  window.addEventListener("resize", function(){ applyRail(savedPref()); });   /* re-clampa sulla finestra, la preferenza resta */
})();
/* ===== Inspector B "lista piatta" (scelta Simone 08/07, mockup inspector-vuoto.html) =====
   Con nulla selezionato: LAYER (esistente) + STATO (righe chiave-valore) + PROGETTO (hub verso
   mixer/report/liste/pannelli). I pannelli tecnici grandi restano ma NASCOSTI finché non li apri
   da qui: la colonna quotidiana è pulita. */
function renderInspectorB(){
  var st=document.getElementById("statoSec"), pg=document.getElementById("progSec");
  if(!st || !pg) return;
  var hasItems=(state.items||[]).length>0;
  /* — STATO — */
  if(!hasItems){ st.style.display="none"; }
  else {
    var R=cabResult();
    var conn=(R.links||[]).filter(function(l){ return !l.deleted; }).length;
    var boxesTxt=(R.boxes||[]).filter(function(b){ return !b.auto; }).map(function(b){ return b.letter+(b.hw?" · "+hwLabel(b.hw,STAGEBOX_DB):""); }).join(", ");
    var Re=(state.elec && state.elec.on) ? elecResult() : null;
    /* lista cavi per taglio (Simone 08/07: "quanti cavi da quanti metri" batte il totale) */
    function tallyRow(links){ var t={}; links.forEach(function(l){ var k=l.cut?String(l.cut):">50"; t[k]=(t[k]||0)+1; });
      var cuts=Object.keys(t).sort(function(a,b){ return (a===">50"?999:+a)-(b===">50"?999:+b); });
      return cuts.map(function(c){ return t[c]+"× "+(c===">50"?"oltre 50 m":c+" m"); }).join(" · "); }
    var xlr=tallyRow((R.links||[]).filter(function(l){ return !l.deleted; }).concat(R.returnLinks||[]));
    var elc=Re ? tallyRow(Re.loadLinks||[]) : "";
    var pw=powerTotalW();
    function ir(k,v,cls){ return '<div class="insp-row'+(cls?" "+cls:"")+'"><b>'+esc(k)+'</b><small>'+esc(String(v))+'</small></div>'; }
    /* conteggi infrastruttura (Simone 08/07: righe omogenee nello STATO + ciabatte/prese/quadri) */
    function nType(){ var set={}; for(var i=0;i<arguments.length;i++) set[arguments[i]]=1;
      return (state.items||[]).filter(function(it){ return set[it.type]; }).length; }
    var c=countAccessori();
    var nCiab=nType("ciabatta"), nPrese=nType("corrente"), nQuadri=nType("quadro","distro32","distro63","distro125");
    var s='<div class="insp-hd">Stato</div>';
    /* Ingressi = i canali della channel list (il rider), non i cavi già routati; avvisa se superano lo stage box.
       Fonte: la lista instrument-driven (patchList) — state.inputs è la lista manuale della consulenza,
       vuota per l'utente normale (bug ciclo 2: contatore fermo a 0 e avviso capacità mai scattato). */
    var _nCh=0;
    try{ _nCh = (window.__consultMode && (state.inputs||[]).length) ? state.inputs.length : patchList().rows.length; }catch(e){ _nCh=(state.inputs||[]).length; }
    var _cap=R.capTot||0, _over=(_cap>0 && _nCh>_cap);
    s+=ir("Ingressi", _nCh+" / "+(_cap||"—")+(_over?"  ⚠ stage box insufficiente":""), _over?"insp-over":"");
    if(_over){   /* avviso AZIONABILE (coerente col pattern audit): indica come risolvere e porta lì */
      var _boxEl=(state.items||[]).find(function(it){ return typeof cabIsBox==="function" && cabIsBox(it); });
      s+= _boxEl
        ? '<div class="insp-fix" data-fix-stagebox="'+esc(_boxEl.id)+'">Aumenta la capacità della stage box →</div>'
        : '<div class="insp-fix insp-fix-static">Aggiungi una stage box più capiente (catalogo › Audio › Stagebox e cablaggio)</div>';
    }
    if(boxesTxt) s+=ir("Stage box", boxesTxt);
    if(xlr) s+=ir("Cavi XLR", xlr);
    if(elc) s+=ir("Cavi elettrici", elc);
    if(pw>0) s+=ir("Potenza", (pw/1000).toFixed(1).replace(".",",")+" kW");
    /* Peso·rack resta nell'audit/cartiglio (dato di pre-produzione, non di disegno) */
    if(nCiab){ var pt={}; (state.items||[]).filter(function(it){ return it.type==="ciabatta"; }).forEach(function(it){ var p=it.prese||6; pt[p]=(pt[p]||0)+1; });
      var pparts=Object.keys(pt).sort(function(a,b){ return a-b; }).map(function(p){ return pt[p]+"× "+p+" prese"; });
      s+=ir("Multiprese", pparts.join(" · ")); }   /* come i cavi: quante multiprese per numero di prese */
    if(nPrese)  s+=ir("Prese 220 V", nPrese);
    if(nQuadri) s+=ir("Quadri / distro", nQuadri);
    /* Un computer in Dante porta con sé una richiesta che nessun altro dato del plot esprime: una
       porta di rete Gigabit CABLATA. Se resta implicita, si scopre in soundcheck (31/07). */
    (state.items||[]).filter(dvsOn).forEach(function(pc){
      s+=ir((pc.label||"Computer")+" · Dante", dvsNote(pc));
    });
    var _ramp=(state.items||[]).filter(function(it){ return it.type==="cableramp"; });
    if(_ramp.length){ var _rmod=_ramp.reduce(function(a,it){ return a+rampModules(it); },0), _rlen=_ramp.reduce(function(a,it){ return a+(it.w||0); },0);
      s+=ir("Passacavi", _rmod+" moduli · "+(_rlen/100).toFixed(1).replace(".",",")+" m"); }   /* il service sa quanti pezzi servono */
    var _cov=(state.items||[]).filter(isCover);
    if(_cov.length){ var _covA=_cov.reduce(function(a,it){ return a+(it.w/100)*(it.d/100); },0);
      s+=ir("Coperture", _cov.length+" · "+(Math.round(_covA*10)/10).toString().replace(".",",")+" m² a terra"); }   /* gazebo/tende/copertura: quante strutture + superficie */
    /* Aste microfoniche: quante ne servono davvero, dedotte dal modello di mic di ogni canale.
       I tom vanno a clip, gli overhead su giraffa: contarne una per microfono sarebbe sbagliato. */
    try{ var _st=standNeeds(), _stTot=standTotal(_st);
      var _ASTE={giraffa:1,gigante:1,bassa:1,dritta:1};   /* aste vere (clip/headset/terra vanno nella coda "senza asta") */
      if(_stTot || _st.clip.tot){
        var _sd=STAND_KINDS.filter(function(k){ return _ASTE[k[0]] && _st[k[0]].tot>0; })
          .map(function(k){ return _st[k[0]].tot+"× "+k[1].toLowerCase(); });
        var _alt=STAND_KINDS.filter(function(k){ return !_ASTE[k[0]] && _st[k[0]].tot>0; })
          .map(function(k){ return _st[k[0]].tot+"× "+k[1].toLowerCase(); });
        s+=ir("Aste microfoniche", (_stTot||0)+(_sd.length?"  ·  "+_sd.join(" · "):"")
          +(_alt.length?"      senza asta: "+_alt.join(" · "):""));   /* clip e headset non sono aste: contate a parte */
      }
    }catch(_e){}
    if(c.sedie)     s+=ir("Sedie", c.sedie);
    if(c.leggii)    s+=ir("Leggii", c.leggii);
    if(c.sgabelli)  s+=ir("Sgabelli", c.sgabelli);
    if(c.hearbacks) s+=ir("Hearback", c.hearbacks);
    /* distinta PERSONAL MONITOR model-driven (B1): modelli, porte hub, alimentatori locali */
    if(state.mond && state.mond.on){
      var Rm=mondResult(), pmCounts={}, pmHubs=[];
      state.items.forEach(function(x){ var d=pmOf(x); if(!d) return;
        if(d.role==="mixer") pmCounts[d.model]=(pmCounts[d.model]||0)+1;
        else pmHubs.push({d:d, n:(Rm.hubLoad&&Rm.hubLoad[x.id])||0}); });
      Object.keys(pmCounts).forEach(function(m){ s+=ir(esc(m), pmCounts[m]+"×"); });
      pmHubs.forEach(function(h){ s+=ir(esc(h.d.model), h.n+"/"+(h.d.ports||8)+" porte"); });
      if(Rm.psuCount) s+=ir("Alimentatori locali", Rm.psuCount+"×");
    }
    st.innerHTML=s; st.style.display="block";
  }
  /* PROGETTO rimosso dall'inspector (Simone 08/07 sera, screenshot): tutto resta raggiungibile —
     Input/Monitor/Carichi dal catalogo sinistro, mixer+report dentro il pannello cablaggio, e i
     pannelli si aprono/chiudono col CLICK SUL NOME DEL LAYER nel Layer manager. */
  pg.innerHTML="";
}
