/* ===== Datalist src per Input patch / Output list ===== */
function updateChanDatalists(){
  var inL=document.getElementById("inSrcList"), outL=document.getElementById("outSrcList");
  if(!inL||!outL) return;
  var inOpts=[], outOpts=[], seenIn={}, seenOut={};
  state.items.forEach(function(it){
    var t=TYPES[it.type]; if(!t) return;
    var name=it.label||t.nome; if(!name) return;
    if((IN_SRC[it.type]!=null||IN_MULTI[it.type]) && !seenIn[name]){ seenIn[name]=1; inOpts.push(name); }
    if(OUT_SET[it.type]!=null && !seenOut[name]){ seenOut[name]=1; outOpts.push(name); }
  });
  function fillList(el, opts){ el.innerHTML=""; opts.forEach(function(o){ var op=document.createElement("option"); op.value=o; el.appendChild(op); }); }
  fillList(inL, inOpts);
  fillList(outL, outOpts);
  /* il mic non ha piu' un datalist: ha il completamento su MIC_DB (data-micac) — una fonte sola */
  var standL=document.getElementById("standList");   /* M4: suggerimenti stand */
  if(standL) fillList(standL, STAND_SUGGEST);
}
function renderChannels(){
  var inR=document.getElementById("inRows"), outR=document.getElementById("outRows");
  if(!inR) return;
  if(typeof renderContacts==="function") renderContacts();   /* T4: rubrica contatti/ruoli (rimpiazza il sync del singolo campo M5) */
  (function(){ var r=state.rider||{};   /* T2: popola i campi rider dallo state + placeholder = default */
    function setv(id,key){ var el=document.getElementById(id); if(!el) return; var want=(r[key]!=null?String(r[key]):""); if(el.value!==want) el.value=want; }
    setv("rdSedie","sedie"); setv("rdSistema","sistema"); setv("rdLuci","luci"); setv("rdPersonale","personale"); setv("rdNote","note");
    var DD=(typeof riderDefaults==="function")?riderDefaults():RIDER_DEFAULTS;
    var ph={rdSistema:DD.sistema, rdLuci:DD.luci, rdPersonale:DD.personale};
    Object.keys(ph).forEach(function(id){ var el=document.getElementById(id); if(el) el.setAttribute("placeholder","Dal palco: "+ph[id].slice(0,54)+"…"); });   /* si riscrive a ogni render: il default segue il palco */
  })();
  updateChanDatalists();
  /* aggiorna badge conteggio negli header a scomparsa */
  var inC=document.getElementById("inCount"), outC=document.getElementById("outCount");
  if(inC) inC.textContent=state.inputs.length||"–";
  if(outC) outC.textContent=state.outputs.length||"–";
  inR.innerHTML=""; outR.innerHTML="";
  if(!state.inputs.length){ inR.innerHTML='<div class="clempty">Nessun canale. Usa "+ canale" o "Auto" dal palco.</div>'; }
  else state.inputs.forEach(function(r,i){ inR.appendChild(chanRow("in",r,i)); });
  if(!state.outputs.length){ outR.innerHTML='<div class="clempty">Nessun mix. Usa "+ mix" o "Auto" dai monitor.</div>'; }
  else state.outputs.forEach(function(r,i){ outR.appendChild(chanRow("out",r,i)); });
}
function rowFromMic(src, mic, stand, p48, notes){ return ch(src, mic, stand, p48, notes); }
/* aggancia le righe della channel list agli oggetti sul palco confrontando src↔etichetta
   (best-effort: usato dalle formazioni QA per dimostrare il link patch→oggetto) */
function linkChannelsToItems(){
  function norm(s){ return String(s||"").toLowerCase().replace(/\[[^\]]*\]/g,"").replace(/[()]/g," ").replace(/\s+/g," ").trim(); }
  var items=state.items.map(function(it){ return {it:it, n:norm(it.label||TYPES[it.type]&&TYPES[it.type].nome)}; }).filter(function(o){ return o.n; });
  function findItem(src){
    var n=norm(src); if(!n) return null;
    var hit=items.filter(function(o){ return o.n===n; })[0]; if(hit) return hit.it;        /* match esatto */
    hit=items.filter(function(o){ return n.indexOf(o.n)>-1 || o.n.indexOf(n)>-1; })[0];     /* match parziale */
    if(hit) return hit.it;
    var w=n.split(" ")[0];                                                                  /* match sulla prima parola (es. "Corni") */
    return (items.filter(function(o){ return w.length>2 && o.n.indexOf(w)>-1; })[0]||{}).it || null;
  }
  [state.inputs, state.outputs].forEach(function(arr){
    arr.forEach(function(r){ if(r.linked_item_id) return; var it=findItem(r.src); if(it) r.linked_item_id=it.id; });
  });
}
/* M3 — ordine "a banchi" della input list (standard live: batteria/kick prima, poi basso,
   chitarre, tastiere, fiati, archi, voci, playback). Numero più basso = più in alto in lista.
   La categoria (TYPES[t].cat) dà il gruppo grosso; dentro "Ritmica" si distingue per keyword. */
function clBank(type){
  var t=TYPES[type]||{}, cat=t.cat||"", n=String(type).toLowerCase();
  if(cat==="Batteria e percussioni"||cat==="Band e backline"){
    if(/batter|drum|kick|grancass|rullant|\btom|hihat|hi-hat|overhead|edrums/.test(n)) return 10;   /* batteria (kick primo) */
    if(/piatt|cajon|conga|bongo|timbal|percuss|tamtam|campan|glocken|vibrafono|marimba|xilofono|timpani|quinto|tumba|djembe|surdo|tamburello|temple|triangolo/.test(n)) return 15; /* altre percussioni */
    if(/bass/.test(n)) return 20;
    if(/gt|chitarr|comboamp|stack|leslie|ampli/.test(n)) return 30;
    if(/keys|piano|tastier|grancoda|mezzacoda|verticale|celesta|stagepiano|doppiatastiera|organ/.test(n)) return 40;
    if(/dj|laptop|playback/.test(n)) return 85;
    return 45;   /* altro backline */
  }
  if(cat==="Orchestra") return (t.sub==="Archi") ? 60 : 50;   /* fiati 50, archi 60 */
  if(cat==="Microfoni e DI"||cat==="Persone e voci") return 70;   /* voci */
  if(cat==="Cablaggio e segnale"||cat==="Regia e console"||cat==="Tecnica") return 80;   /* DI, playback, tecnica */
  return 90;
}
/* La conferma di sovrascrittura vive nei click handler (#inAuto/#outAuto) via confirmDialog: qui dentro
   era un confirm() NATIVO, e al secondo click bloccava del tutto la finestra (audit 27/07). */
function autoInputs(silent){   /* silent=true (dall'apertura Esporta): genera in memoria SENZA salvare — M-04 */
  var rows=[];
  function linkTo(row,it,compId){ row.linked_item_id=it.id; if(compId) row.linked_component_id=compId; return row; }
  /* M3: ordina gli strumenti per banco (stabile: parità → ordine di inserimento) prima di numerare i canali */
  var ordered = state.items.map(function(it,idx){ return {it:it, idx:idx}; })
    .sort(function(a,b){ return (clBank(a.it.type)-clBank(b.it.type)) || (a.idx-b.idx); })
    .map(function(o){ return o.it; });
  ordered.forEach(function(it){
    var t=TYPES[it.type]; if(!t) return;
    if(it.type!=="miczone" && itemInMicZone(it) && !effOwnMic(it)) return;   /* coperto da una zona (effOwnMic = ownMic esplicito o default close-obligato) */
    if(it.type==="miczone"){ rows.push(linkTo(rowFromMic(micZoneLabel(it), micZoneMic(it)),it)); return; }
    if(it.type==="coppiast"){
      rows.push(linkTo(rowFromMic(labelPrefix(it,"L"),"KM184"),it,"mic_L"));
      rows.push(linkTo(rowFromMic(labelPrefix(it,"R"),"KM184"),it,"mic_R"));
      return;
    }
    if(MIKING[it.type]){   /* microfonazione scelta (archi/cori/fiati): panoramico può dare 0 canali */
      MIKING[it.type].chans(it.miking||MIKING[it.type].def).forEach(function(k){
        rows.push(linkTo(rowFromMic(k[0]?labelPrefix(it,k[0]):(it.label||t.nome), k[1]),it));
      });
      return;
    }
    if(IN_MULTI[it.type]){
      inMultiList(it).forEach(function(k){
        rows.push(linkTo(rowFromMic(labelPrefix(it,k[0]), k[1], k[2], k[3], k[4]),it));
      });
      return;
    }
    if(it.type==="distereo"){
      rows.push(linkTo(rowFromMic(labelPrefix(it,"L"),"DI"),it));
      rows.push(linkTo(rowFromMic(labelPrefix(it,"R"),"DI"),it));
      return;
    }
    if(IN_SRC[it.type]!=null){ rows.push(linkTo(rowFromMic(it.label || t.nome, IN_SRC[it.type]),it)); }
  });
  state.inputs=rows; if(!silent) save(); renderChannels();
}
function autoOutputs(silent){   /* silent=true dall'apertura Esporta: niente save — M-04 (conferma nel click) */
  var rows=[];
  state.items.forEach(function(it){
    if(OUT_SET[it.type]!=null && !MON_DIG_NODE[it.type]){   /* i personal mixer non generano un canale di uscita analogico: viaggiano in digitale (layer P.M.) */
      var r=outch(it.label || TYPES[it.type].nome, OUT_SET[it.type], "stage");
      r.linked_item_id=it.id; rows.push(r);
    }
  });
  state.outputs=rows; if(!silent) save(); renderChannels();
}

/* ============ PLANIMETRIA / VENUE ============ */
var venueCalibMode=0, venueCalibPts=[];
/* default vuoto; non serializzare _dataUrl nel JSON */
function venueDefault(){ return {enabled:true,locked:false,name:"",x:0,y:0,w:5000,h:3500,rot:0,opacity:40,calibration:null}; }
/* Sicurezza: _dataUrl finisce grezzo in <image href> (SVG via innerHTML). Un progetto di terzi
   (link ?view=, apri/copia da cloud) potrebbe iniettare un valore arbitrario → attribute injection/XSS.
   Whitelist stretta: solo i raster prodotti da FileReader/canvas (png/jpeg/webp/gif base64); qualsiasi
   altra cosa viene scartata. Il charset base64 non contiene " < > quindi è safe in attributo. */
function safeVenueDataUrl(u){
  return (typeof u==="string" && /^data:image\/(png|jpe?g|webp|gif);base64,[A-Za-z0-9+/]+={0,2}$/.test(u)) ? u : "";
}
function normalizeVenue(v){
  if(!v||typeof v!=="object"||Array.isArray(v)) return null;
  var o=venueDefault();
  function num(x,f,min,max){ x=Number(x); return isFinite(x)?Math.max(min,Math.min(max,x)):f; }
  o.enabled=v.enabled!==false; o.locked=v.locked===true;
  o.name=(typeof v.name==="string"||typeof v.name==="number")?String(v.name).slice(0,160):"";
  o.x=num(v.x,0,-10000000,10000000); o.y=num(v.y,0,-10000000,10000000);
  o.w=num(v.w,5000,1,10000000); o.h=num(v.h,3500,1,10000000);
  o.rot=num(v.rot,0,-360000,360000)%360; o.opacity=num(v.opacity,40,0,100);
  if(v.calibration && typeof v.calibration==="object" && !Array.isArray(v.calibration)){
    var c={}, rc=Number(v.calibration.realCm), rw=Number(v.calibration.realW);
    if(isFinite(rc)&&rc>0&&rc<=10000000) c.realCm=rc;
    if(isFinite(rw)&&rw>0&&rw<=10000000) c.realW=rw;
    ["p1","p2"].forEach(function(k){ var p=v.calibration[k];
      if(p&&typeof p==="object"&&isFinite(Number(p.x))&&isFinite(Number(p.y)))
        c[k]={x:num(p.x,0,-10000000,10000000),y:num(p.y,0,-10000000,10000000)}; });
    if(Object.keys(c).length) o.calibration=c;
  }
  var du=safeVenueDataUrl(v._dataUrl); if(du) o._dataUrl=du;
  var iw=Number(v._imgW), ih=Number(v._imgH);
  if(isFinite(iw)&&iw>0&&iw<=100000) o._imgW=Math.round(iw);
  if(isFinite(ih)&&ih>0&&ih<=100000) o._imgH=Math.round(ih);
  /* «la mia pianta è quella della scena X»: nei file esportati le scene gemelle non ripetono il
     base64 (vedi docToJSONFull). Va conservato o l'immagine non si riaggancia alla riapertura. */
  if(!du && typeof v._sameAs==="string" && v._sameAs && v._sameAs.length<=80) o._sameAs=v._sameAs;
  return o;
}

/* il punto (mondo) cade sulla planimetria? — hit-test geometrico, indipendente da pointer-events/lock */
/* venueHitTest RIMOSSA (31/07): serviva solo a far cambiare effetto al doppio clic quando sotto
   c'era la planimetria. Tolto quel comportamento non la chiamava più nessuno, e una funzione senza
   chiamanti è debito che il prossimo legge come se contasse ancora. */
function venueMarkup(){
  var v=state.venue; if(!v) return '';
  var durl=safeVenueDataUrl(v._dataUrl); if(!durl) return '';   /* seconda barriera: rivalida al render */
  function n(x,f){ x=Number(x); return isFinite(x)?x:f; }
  var x=n(v.x,0), y=n(v.y,0), w=Math.max(1,n(v.w,1)), h=Math.max(1,n(v.h,1)), rot=n(v.rot,0);
  var op=(Math.max(0,Math.min(100,n(v.opacity,40)))/100).toFixed(2);
  var hw=w/2, hh=h/2;
  var pe=v.locked?'none':'auto';
  var s='<image href="'+durl+'" x="'+(-hw)+'" y="'+(-hh)+'" width="'+w+'" height="'+h+'"';
  s+=' opacity="'+op+'" pointer-events="'+pe+'"';
  s+=' transform="translate('+x+','+y+') rotate('+rot+')"';
  if(!v.locked) s+=' class="venue-img" data-venue="1"';
  s+='/>';
  /* punti calibrazione */
  if(venueCalibMode>0 && venueCalibPts.length>0){
    venueCalibPts.forEach(function(p){ s+='<circle class="venue-calib-dot" cx="'+p.x+'" cy="'+p.y+'" r="6"/>'; });
    if(venueCalibPts.length===2){
      s+='<line class="venue-calib-line" x1="'+venueCalibPts[0].x+'" y1="'+venueCalibPts[0].y+'" x2="'+venueCalibPts[1].x+'" y2="'+venueCalibPts[1].y+'"/>';
    }
  }
  return s;
}

function renderVenuePanel(){
  var vp=document.getElementById("venuePanel"); if(!vp) return;
  var v=state.venue;
  var hasImg=!!(v&&v._dataUrl);
  var cal=!!(v&&v.calibration);
  function stepState(id, st){ var el=document.getElementById(id); if(el){ el.classList.remove("done","active","pending"); el.classList.add(st); } }
  stepState("vstep1", hasImg?"done":"active");
  stepState("vstep2", !hasImg?"pending":(cal?"done":"active"));
  stepState("vstep3", hasImg?"active":"pending");
  var s1=document.getElementById("vstep1sub");
  if(s1) s1.textContent = hasImg ? (v.name||"immagine caricata") : "La pianta del luogo (PNG o JPG)";
  var bi=document.getElementById("venueBtnImport");
  if(bi){ bi.textContent = hasImg ? "Sostituisci immagine…" : "📥 Importa immagine"; bi.classList.toggle("primary", !hasImg); }
  var s2=document.getElementById("vstep2sub");
  if(s2){
    if(!hasImg) s2.textContent="Prima importa l'immagine";
    else if(cal){ var mpp=v.calibration.realCm && v.calibration.p1 ? null : null;
      s2.textContent="In scala ✓ — se serve puoi ricalibrare"; }
    else s2.textContent="Traccia sulla mappa una misura che conosci";
  }
  var bc=document.getElementById("venueBtnCalib");
  if(bc){ bc.textContent = cal ? "📐 Ricalibra" : "📐 Inizia la calibrazione"; bc.classList.toggle("primary", hasImg && !cal); }
  var alt=document.getElementById("vstep2alt");
  if(alt){ alt.hidden = !hasImg || cal;
    if(hasImg && !cal){ var rw=document.getElementById("venueRealW"); if(rw && !rw.value) rw.value=(v.w/100).toFixed(1); } }
  /* Il peso si mostra solo quando è un problema: una planimetria pesante riempie l'archivio del
     browser e, oltre una certa soglia, impedisce di creare i punti di recupero (03/08/2026). */
  var wr=document.getElementById("venueWeightRow");
  if(wr){
    var pesante=hasImg && venueNeedsCompression(v._dataUrl, v._imgW, v._imgH);
    wr.hidden=!pesante;
    if(pesante){
      /* Se è già compressa e dentro il lato massimo, ricomprimerla non guadagna nulla: si toglie il
         bottone invece di lasciarne uno che al clic non fa niente. */
      var gia=/^data:image\/(webp|jpeg)/i.test(String(v._dataUrl)) &&
        Math.max(Number(v._imgW)||0,Number(v._imgH)||0)<=VENUE_MAXSIDE;
      var wt=document.getElementById("venueWeightTxt");
      if(wt) wt.textContent="Occupa "+fmtPeso(venueDataUrlBytes(v._dataUrl))+" sul dispositivo"+
        (gia?": è già compressa al meglio, per alleggerirla serve un'immagine di partenza più piccola."
            :": tanto spazio per una pianta di sfondo.");
      var bl=document.getElementById("venueBtnLighten"); if(bl) bl.hidden=gia;
    }
  }
  document.getElementById("venueReload").hidden = !(v&&v.name&&!v._dataUrl);
  if(v&&v.name&&!v._dataUrl) document.getElementById("venueReloadName").textContent=v.name;
  document.getElementById("venueOpacity").value = v?v.opacity:40;
  document.getElementById("venueOpacityVal").textContent = (v?v.opacity:40)+"%";
  document.getElementById("venueRot").value = v?v.rot:0;
  document.getElementById("venueRotNum").value = v?v.rot:0;
  document.getElementById("venueRotVal").textContent = (v?v.rot:0)+"°";
  document.getElementById("venueBtnLock").textContent = (v&&v.locked)?"🔓 Sblocca":"🔒 Blocca";
  document.getElementById("venueBtnVis").textContent = (v&&v.enabled===false)?"👁 Mostra":"👁 Nascondi";
  document.getElementById("venueBtnVis").style.display = hasImg?"":"none";
  document.getElementById("venueBtnLock").style.display = hasImg?"":"none";
  document.getElementById("venueOpacityRow").style.display = hasImg?"":"none";
  document.getElementById("venueRotRow").style.display = hasImg?"":"none";
  document.getElementById("venueBtnCalib").style.display = hasImg?"":"none";
  document.getElementById("venueBtnDel").style.display = v?"":"none";
}
function toggleVenueEdit(){
  if(stageEdit && stagePanelView!=="planimetria"){ stagePanelView="planimetria"; selBlock=null; renderStagePanel(); render(); return; }   /* aperto sui blocchi: passa alla planimetria */
  if(!stageEdit){ stageEdit=true; stagePanelView="planimetria"; selBlock=null; exitHubModes("palco"); clearSelection(); }
  else { stageEdit=false; selBlock=null; venueAutoLock(); }
  renderStagePanel(); render(); }

