/* [strumento Zone rimosso 06/07/2026 — toggleZoneLayer/suggestZones/addZone/delZone/renderZonePanel
   e i suggerimenti automatici. Superati dai motori audio/elettrico.] */
/* helper del motore/PDF: canali per oggetto, corrente monofase indicativa */
function itemChannels(it){ return cabItemInputs(it).length; }   /* fonte unica: coerente con zona/miczone/distereo/MIKING (test motori) */

/* ===== Cornice di stampa (area esportata nel PDF) ===== */
var frameEdit=false;
var saveAsOpen=false;
var versEdit=false;
function frameStageRect(){ recalcStageBBox(); return {x:0,y:0,w:state.stage.w,h:state.stage.d}; }
/* area che racchiude palco + elementi + planimetria (per "Tutto + planimetria") */
function frameContentRect(){
  var b=contentBounds(), x0=b.x0,y0=b.y0,x1=b.x1,y1=b.y1, v=state.venue;
  if(v && v.enabled!==false && v._dataUrl){
    var hw=v.w/2, hh=v.h/2, a=(v.rot||0)*Math.PI/180, c=Math.cos(a), s=Math.sin(a);
    [[-hw,-hh],[hw,-hh],[hw,hh],[-hw,hh]].forEach(function(p){
      var px=v.x+p[0]*c-p[1]*s, py=v.y+p[0]*s+p[1]*c;
      x0=Math.min(x0,px); y0=Math.min(y0,py); x1=Math.max(x1,px); y1=Math.max(y1,py);
    });
  }
  var m=40;
  return {x:Math.round(x0-m), y:Math.round(y0-m), w:Math.round(x1-x0+2*m), h:Math.round(y1-y0+2*m)};
}
function ensurePrintFrame(){ if(!state.printFrame) state.printFrame=frameStageRect(); }
function toggleFrameEdit(){ frameEdit=!frameEdit; if(frameEdit){ exitHubModes("frame"); clearSelection(); ensurePrintFrame(); } renderFramePanel(); render(); }
function fmtMnum(cm){ return (cm/100).toFixed(2).replace(/\.?0+$/,""); }
function activateFrameEdit(){ if(!frameEdit){ frameEdit=true; saveAsOpen=false; clearSelection(); ensurePrintFrame(); renderFramePanel(); render(); } }
/* fine della scelta: si torna alla finestra Esporta, da dove si era partiti */
/* «Torna a Esporta» tornava a un'ALTRA cosa: il pannello laterale Esporta, cioè proprio il passaggio
   intermedio che il 31/07 era stato tolto dall'andata — sopravviveva sulla via del ritorno. E con Esc
   non si tornava affatto: niente finestra, niente pannello, in mezzo al canvas (06/08). */
function finishFrameEdit(){ frameEdit=false; saveAsOpen=false; renderFramePanel(); render();
  if(typeof window.openPdfExportModal==="function") window.openPdfExportModal(); }
/* riassunto dell'area nella finestra Esporta: dice sempre cosa verrà stampato */
function frameSummaryText(){
  var f=state.printFrame;
  if(!f) return "tutto il palco ("+fmtM(state.stage.w)+" × "+fmtM(state.stage.d)+") con le quote";
  var st=frameStageRect();
  /* area che coincide col palco: stampa lo stesso rettangolo ma SENZA il margine delle quote —
     va detto, altrimenti sembra identico a «tutto il palco» e non si capisce perché il PDF cambia */
  if(Math.abs(f.x-st.x)<2 && Math.abs(f.y-st.y)<2 && Math.abs(f.w-st.w)<2 && Math.abs(f.h-st.h)<2)
    return "il palco esatto ("+fmtM(f.w)+" × "+fmtM(f.h)+"), senza margine per le quote";
  return "area scelta "+fmtM(f.w)+" × "+fmtM(f.h)+(f.x||f.y ? " · da "+fmtM(f.x)+"; "+fmtM(f.y) : "");
}
function renderFramePanel(){
  var p=document.getElementById("framePanel"); if(!p) return;
  /* La finestra Esporta è SEMPRE un modale centrato: durante la scelta dell'area si chiude e i suoi
     controlli passano al pannello destro (come «Palco e pedane»). Prima restava aperta senza la
     classe che la centrava, e cadeva in basso a sinistra sopra il catalogo. */
  p.hidden=!(saveAsOpen && !frameEdit);
  document.body.classList.toggle("export-menu", saveAsOpen && !frameEdit);
  var ap=document.getElementById("areaEditPanel");
  if(ap) ap.hidden=!frameEdit;
  document.body.classList.toggle("area-edit", frameEdit);
  var sm=document.getElementById("frameSummaryTxt");
  if(sm) sm.textContent=frameSummaryText();
  if(!(saveAsOpen||frameEdit)) return;
  {
    /* i quattro campi vanno riempiti SEMPRE che il pannello sia visibile: aperti dal menu Esporta
       (saveAsOpen, senza editing) restavano vuoti e sembrava che l'area non esistesse */
    var f=state.printFrame||frameStageRect();
    document.getElementById("frameW").value=fmtMnum(f.w);
    document.getElementById("frameH").value=fmtMnum(f.h);
    document.getElementById("frameX").value=fmtMnum(f.x);
    document.getElementById("frameY").value=fmtMnum(f.y);
  }
}
/* ===== Versioni salvate ===== */
var VER_KEY='stageplot_versions';
function loadVersions(){ try{ return JSON.parse(localStorage.getItem(VER_KEY)||'[]'); }catch(e){ return []; } }
/* Riferimento al blob della planimetria, quando esiste ed è raggiungibile. La chiave è indirizzata
   dal CONTENUTO (venueStorageKey = hash della firma), quindi due documenti con la stessa immagine
   condividono lo stesso blob e una versione può puntarci senza duplicare megabyte. */
function venueRefForVersion(sig){
  if(!sig) return null;
  var staged=(sig===venuePersistedSig&&venuePersistedKey)?{sig:sig,key:venuePersistedKey}:stageVenueImg();
  if(!staged||!staged.key||staged.sig!==sig) return null;
  try{ if(!localStorage.getItem(staged.key)) return null; }catch(_venueReadErr){ return null; }
  return {sig:sig,key:staged.key};
}
function saveVersion(name,includeImages){
  var vs=loadVersions();
  var C=window.__cloud, cid=(C&&typeof C.currentId==="function")?(C.currentId()||null):(window.__bootCloudId||null);
  var row={name:name||'Versione', date:Date.now(), cloudId:cid};
  var sig=venueImageBundleSig(), ref=venueRefForVersion(sig);
  /* PRIMA il riferimento, POI la copia. Il recovery dev'essere autosufficiente solo dove non può
     esistere un blob locale (consulenza/viewer: stageVenueImg() non scrive). Bug del 03/08/2026:
     con una planimetria da 8,3 MB già in archivio il punto di recupero ne pretendeva una SECONDA
     copia, la quota la rifiutava e restava impossibile aprire qualsiasi progetto. */
  if(ref){ row.data=docToJSON(); row.venueSig=ref.sig; row.venueKey=ref.key; }
  else if(includeImages||foreignDoc()) row.data=docToJSONFull();
  else if(sig) return false;   /* planimetria non referenziabile: non salvare una versione monca */
  else row.data=docToJSON();
  vs.unshift(row);
  if(vs.length>30) vs=vs.slice(0,30);
  /* Se non entra, sacrifica le versioni più VECCHIE e ritenta: il punto di recupero appena creato
     vale più dello storico, e arrendersi qui blocca l'apertura dei progetti. Mai in silenzio. */
  var potate=0;
  for(;;){
    try{ localStorage.setItem(VER_KEY, JSON.stringify(vs)); break; }
    catch(e){
      if(vs.length<=1) return false;
      var tieni=Math.max(1, vs.length-Math.max(1, Math.ceil(vs.length/4)));
      potate+=vs.length-tieni; vs=vs.slice(0,tieni);
    }
  }
  if(potate && window.__toast) window.__toast("Spazio esaurito sul dispositivo: "+potate+
    (potate===1?" versione salvata è stata eliminata":" versioni salvate sono state eliminate")+
    " per creare il punto di recupero.",true);
  renderVersionPanel();
  return true;
}
function deleteVersion(idx){
  var vs=loadVersions(); vs.splice(idx,1);
  try{ localStorage.setItem(VER_KEY, JSON.stringify(vs)); }catch(e){}
  renderVersionPanel();
}
function restoreVersion(idx){
  var vs=loadVersions(); if(!vs[idx]) return;
  try{
    var parsed=JSON.parse(vs[idx].data);   /* errore leggibile prima di qualsiasi side effect */
    var prepared=prepareDoc(parsed);
    var versionVenue=null;
    if(vs[idx].venueSig){
      if(typeof vs[idx].venueKey!=="string" || vs[idx].venueKey.indexOf(LS_KEY_VENUE+".")!==0) throw new Error("Version venue ref");
      var venueRaw=localStorage.getItem(vs[idx].venueKey); if(!venueRaw) throw new Error("Version venue missing");
      versionVenue=normalizeVenueImageBundle(JSON.parse(venueRaw),prepared.active);
      if(!versionVenue || venueImageBundleSig(versionVenue)!==vs[idx].venueSig) throw new Error("Version venue mismatch");
    }
    var C=window.__cloud, current=(C&&C.currentId)?(C.currentId()||null):(window.__bootCloudId||null);
    /* Anche gli snapshot legacy piatti attraversano il confine documento. Un record storico senza project ID
       non deve ereditare l'aggancio cloud corrente e sovrascrivere un progetto diverso al prossimo autosave. */
    var sameCloud=!!(vs[idx].cloudId && current && vs[idx].cloudId===current);
    guardDocumentReplacement({reason:"ripristinare una versione",title:"Ripristinare «"+String(vs[idx].name||"Versione").slice(0,60)+"»?",
      confirmText:"Ripristina"},function(){
      activatePreparedProject(prepared,{keepCloud:sameCloud,persist:false,autosave:false});
      if(versionVenue) replaceVenueImageBundle(versionVenue);
      reattachVenueImg(state,activeVar); resetHistory(); save();
      render();
    });
  }catch(e){ if(window.__toast) window.__toast("Versione non valida o non più compatibile.",true); }
}
function renderVersionPanel(){
  var p=document.getElementById('versPanel'); if(!p) return;
  p.hidden=!versEdit; if(!versEdit) return;
  var vs=loadVersions();
  var d=document.getElementById('versList');
  if(!vs.length){ d.innerHTML='<div style="color:var(--text-2);font-size:12px;padding:6px 0">Nessuna versione salvata.</div>'; return; }
  d.innerHTML=vs.map(function(v,i){
    var dt=new Date(v.date), ds='';
    /* un record senza data valida (archivio di una versione vecchia, o toccato a mano) stampava
       «Invalid Date Invalid Date» accanto al nome: meglio niente che una scritta rotta */
    if(dt && isFinite(dt.getTime()))
      ds=dt.toLocaleDateString('it-IT',{day:'2-digit',month:'2-digit',year:'2-digit'})+' '+dt.toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'});
    return '<div class="ver-row"><span class="ver-name">'+esc(v.name)+'</span><span class="ver-date">'+ds+'</span>'+
      '<button class="btn" style="font-size:11px;padding:3px 7px" onclick="restoreVersion('+i+')">Ripristina</button>'+
      '<button class="btn danger" style="font-size:11px;padding:3px 7px" onclick="deleteVersion('+i+')">✕</button></div>';
  }).join('');
}
function toggleVersionEdit(){
  versEdit=!versEdit;
  if(versEdit){ exitHubModes('vers'); clearSelection(); }
  renderVersionPanel(); render();
}
/* ===== SVG Export ===== */
/* ===== Stampa ===== */
function frameMarkup(){
  if(!frameEdit || !state.printFrame) return '';
  var f=state.printFrame, H=14;
  var s='<g data-frame="1">';
  s+='<rect class="frame-rect" data-frame-body="1" x="'+f.x+'" y="'+f.y+'" width="'+f.w+'" height="'+f.h+'"/>';
  s+='<text class="frame-lbl" x="'+(f.x+f.w/2)+'" y="'+(f.y-12)+'" text-anchor="middle" font-size="22">AREA STAMPA · '+(f.w/100)+'×'+(f.h/100)+' m</text>';
  var pts=[["nw",f.x,f.y],["n",f.x+f.w/2,f.y],["ne",f.x+f.w,f.y],["e",f.x+f.w,f.y+f.h/2],["se",f.x+f.w,f.y+f.h],["s",f.x+f.w/2,f.y+f.h],["sw",f.x,f.y+f.h],["w",f.x,f.y+f.h/2]];
  pts.forEach(function(p){ s+='<rect class="frame-h" data-frame-edge="'+p[0]+'" x="'+(p[1]-H)+'" y="'+(p[2]-H)+'" width="'+(2*H)+'" height="'+(2*H)+'" rx="3"/>'; });
  s+='</g>';
  return s;
}
function resizeFrame(drag, sp){
  var f0=drag.f0, ed=drag.edge, dx=sp.x-drag.sp0.x, dy=sp.y-drag.sp0.y, MIN=50;
  var x=f0.x, y=f0.y, w=f0.w, h=f0.h;
  if(ed.indexOf("w")>=0){ var nx=f0.x+dx, nw=f0.w-dx; if(nw<MIN){ nx=f0.x+f0.w-MIN; nw=MIN; } x=Math.round(nx); w=Math.round(nw); }
  if(ed.indexOf("e")>=0){ w=Math.round(Math.max(MIN, f0.w+dx)); }
  if(ed.indexOf("n")>=0){ var ny=f0.y+dy, nh=f0.h-dy; if(nh<MIN){ ny=f0.y+f0.h-MIN; nh=MIN; } y=Math.round(ny); h=Math.round(nh); }
  if(ed.indexOf("s")>=0){ h=Math.round(Math.max(MIN, f0.h+dy)); }
  state.printFrame={x:x,y:y,w:w,h:h};
}
["frameW","frameH","frameX","frameY"].forEach(function(id){
  document.getElementById(id).addEventListener("change", function(){
    /* Leggere PRIMA di attivare: activateFrameEdit() ridisegna il pannello e riscrive i quattro campi
       dai valori correnti dell'area — chiamandolo per primo il numero appena digitato veniva
       sovrascritto e la modifica andava persa (bug 27/07: "il primo valore che scrivi non conta"). */
    var w=Math.max(0.5, +document.getElementById("frameW").value||0.5);
    var h=Math.max(0.5, +document.getElementById("frameH").value||0.5);
    var x=+document.getElementById("frameX").value||0, y=+document.getElementById("frameY").value||0;
    activateFrameEdit();
    state.printFrame={x:Math.round(x*100), y:Math.round(y*100), w:Math.round(w*100), h:Math.round(h*100)};
    save(); render(); renderFramePanel();   /* rimette nei campi i valori normalizzati (arrotondati, minimi) */
  });
});
document.getElementById("frameEditBtn").addEventListener("click", activateFrameEdit);   /* dalla finestra Esporta si passa al pannello destro */
document.getElementById("areaDone").addEventListener("click", finishFrameEdit);
document.getElementById("frameStage").addEventListener("click", function(){ activateFrameEdit(); state.printFrame=frameStageRect(); save(); render(); renderFramePanel(); });
document.getElementById("frameAll").addEventListener("click", function(){ activateFrameEdit(); state.printFrame=frameContentRect(); save(); render(); });
document.getElementById("frameClear").addEventListener("click", function(){ activateFrameEdit(); state.printFrame=null; save(); render(); });
document.getElementById("frameCenter").addEventListener("click", function(){
  activateFrameEdit(); ensurePrintFrame(); recalcStageBBox();
  state.printFrame.x = Math.round(state.stage.w/2 - state.printFrame.w/2);
  state.printFrame.y = Math.round(state.stage.d/2 - state.printFrame.h/2);
  save(); render();
});
