/* ============ Dialogo di conferma riusabile (azioni distruttive) ============ */
var CFM_ICON={
  warn:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M10.3 3.3 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.3a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4M12 17h.01"/></svg>',
  trash:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6M14 11v6"/></svg>'
};
function confirmDialog(opts){
  opts=opts||{};
  return new Promise(function(resolve){
    var m=document.getElementById("confirmModal");
    if(!m){ resolve(window.confirm(opts.message||opts.title||"")); return; }
    document.getElementById("cfmIco").innerHTML = CFM_ICON[opts.icon] || CFM_ICON.warn;
    document.getElementById("cfmTitle").textContent = opts.title || "Sei sicuro?";
    var msg=document.getElementById("cfmMsg");
    msg.textContent = opts.message || ""; msg.hidden = !opts.message;
    var okb=document.getElementById("cfmOk"), cancb=document.getElementById("cfmCancel");
    okb.textContent = opts.confirmText || "Conferma";
    cancb.textContent = opts.cancelText || "Annulla";
    m.hidden=false;
    var prev=document.activeElement;
    function done(val){
      m.hidden=true;
      okb.removeEventListener("click",onOk);
      cancb.removeEventListener("click",onCancel);
      m.removeEventListener("mousedown",onBack);
      document.removeEventListener("keydown",onKey,true);
      /* niente prev.focus() qui: era sincrono mentre lo sfondo è ancora `inert` (non focalizzabile)
         e spediva il focus su <body>. Il ripristino è dell'infrastruttura modali (M-22), che lo fa
         dopo aver tolto inert — un solo sistema, non due in competizione (PERF-A11Y-02). */
      resolve(val);
    }
    function onOk(){ done(true); }
    function onCancel(){ done(false); }
    function onBack(e){ if(e.target===m) done(false); }
    function onKey(e){
      if(e.key==="Escape"){ e.preventDefault(); e.stopPropagation(); done(false); }
      else if(e.key==="Enter"){ e.preventDefault(); e.stopPropagation(); done(true); }   /* Invio = conferma (richiesta Simone 08/07): semantica standard dei dialoghi */
    }
    okb.addEventListener("click",onOk);
    cancb.addEventListener("click",onCancel);
    m.addEventListener("mousedown",onBack);
    document.addEventListener("keydown",onKey,true);
    cancb.focus();   /* focus su Annulla (il click parte da lì) — ma Invio CONFERMA sempre via onKey */
  });
}
window.confirmDialog=confirmDialog;

/* ============ FILE: nuovo / json / png ============ */
document.getElementById("bNew").addEventListener("click", function(){
  if(window.__consultMode){
    if(window.__toast) window.__toast("Durante la consulenza non puoi sostituire il progetto. Usa Esporta recupero se ti serve una copia.",true);
    return;
  }
  /* Conferma solo se c'è davvero qualcosa da perdere (13/08): su un palco ancora vuoto l'avviso
     «verrà chiuso» parlava di un lavoro che non esisteva, e ora che «Nuovo…» è già una finestra di
     scelta sarebbero state due finestre di fila per non azzerare niente. */
  var chiedi = (typeof hasMeaningfulDocument==="function") ? hasMeaningfulDocument() : true;
  (chiedi ? confirmDialog({
    icon:"warn", title:"Nuovo stage plot?",
    message:"L'editor viene azzerato per ricominciare da un palco vuoto. I progetti che hai salvato (cloud o «I miei progetti») NON vengono eliminati e restano al loro posto. Se il lavoro aperto non è salvato, esportalo o salvalo prima: verrà chiuso.",
    confirmText:"Azzera e ricomincia"
  }) : Promise.resolve(true)).then(function(ok){
    if(!ok) return;
    guardDocumentReplacement({skipConfirm:true,allowBlockedDiscard:true,reason:"nuovo progetto"},function(){
      window.__docLoadBlocked=null;   /* scelta esplicita: abbandona l'eventuale documento locale incompatibile */
      /* Un solo confine documento: scarta anche varianti inattive, metadati root, contatti, routing e cache
         del progetto precedente, oltre a invalidare ogni save asincrono ancora in volo. */
      if(!beginNewDocument({titolo:"",luogo:"",stage:{w:1200,d:800,blocks:[{x:0,y:0,w:1200,d:800}]},items:[],inputs:[],outputs:[]},
          {skipRecovery:true,reason:"nuovo progetto"})) return;
      if(typeof renderVariantBar==="function") renderVariantBar();
      resetMetaLayersUI();   /* foglio nuovo: azzera visibilità/opacità/blocco dei layer Palco e Section Mic */
      stageEdit=false; selBlock=null; eventoEdit=false; renderStagePanel(); renderEventoPanel(); clearSelection(); save(); fit();
      setEventInputs(); renderChannels();
      resetCatalogView();   /* foglio nuovo = catalogo in stato di partenza */
      if(typeof maybeAskStageSize==="function") maybeAskStageSize(true);   /* progetto nuovo senza palco → chiedi le dimensioni */
    });
  });
});
/* Auto-ricompattamento RIMOSSO (07/07, scelta Simone): le categorie restano aperte finché non ne apri
   un'altra (accordion) o le chiudi a mano — niente più chiusura automatica dopo inattività. Gli stub
   no-op tengono innocui i vecchi call site. */
function catCompactSoon(){}
function catIdleCancel(){}
function collapseCats(){   /* chiude solo le categorie/sottocategorie aperte (non tocca ricerca/scroll) */
  document.querySelectorAll("#catalog .cat-head.open, #catalog .cat-body.open, #catalog .sub-head.open, #catalog .sub-body.open").forEach(function(el){ el.classList.remove("open"); });
}
/* C'è una ricerca in corso nel catalogo? (campo con del testo dentro) */
function catSearching(){ var q=document.getElementById("catSearch"); return !!(q && q.value); }
/* Fine della ricerca: il campo si svuota e la colonna torna com'era all'apertura (categorie chiuse,
   in cima). Si chiama da Esc e dal primo tocco sul canvas — dentro o fuori dal palco, indifferente.
   Se NON si sta cercando non fa nulla: chi ha aperto una categoria per lavorare non se la vede
   richiudere a ogni clic sul palco. */
function endCatSearch(){ if(!catSearching()) return false;
  var q=document.getElementById("catSearch"); if(q && q===document.activeElement && q.blur) q.blur();
  resetCatalogView(); return true; }
function resetCatalogView(){
  catIdleCancel();
  collapseCats();
  var q=document.getElementById("catSearch");
  if(q && q.value){ q.value=""; q.dispatchEvent(new Event("input",{bubbles:true})); }
  var c=document.getElementById("catalog"); if(c) c.scrollTop=0;
}
