function dl(href,name){ var a=document.createElement("a"); a.href=href; a.download=name; document.body.appendChild(a); a.click(); a.remove(); }
/* conferma download coerente per tutti gli export (CSV/PDF/PNG) — il file parte davvero ma senza
   feedback l'utente non lo sa (il browser mostra il download in un angolo, spesso ignorato). */
function toastDownloaded(name){ try{ if(window.__toast) window.__toast("Download completato: "+name); }catch(_e){} }
function pdfSave(doc, name){ doc.save(name); toastDownloaded(name); }

/* ===== Export CSV della channel list (discovery pro #1 + preset #4) — il service importa in
   Excel/console invece di ri-digitare il PDF a mano. Separatore scelto + BOM UTF-8 (accenti). ===== */
function csvCell(v, sep){ v=(v==null?"":String(v)); return (v.indexOf(sep)>-1 || /["\n\r]/.test(v)) ? '"'+v.replace(/"/g,'""')+'"' : v; }
/* nome canale per Allen & Heath: accenti rimossi, solo alfanumerici+spazio, max 8 caratteri (vincolo console) */
function ahName(s){ return String(s==null?"":s).normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/[^A-Za-z0-9 ]/g,"").trim().slice(0,8); }
function rowsToCsv(headers, rows, sep){
  sep=sep||";";
  var out=[]; if(headers) out.push(headers.map(function(c){ return csvCell(c,sep); }).join(sep));
  rows.forEach(function(r){ out.push(r.map(function(c){ return csvCell(c,sep); }).join(sep)); });
  return "﻿"+out.join("\r\n")+"\r\n";   /* BOM + CRLF: massima compatibilità Excel/console */
}
function downloadCsv(text, name){
  var blob=new Blob([text], {type:"text/csv;charset=utf-8"});
  var url=URL.createObjectURL(blob);
  dl(url, name);
  toastDownloaded(name);
  setTimeout(function(){ URL.revokeObjectURL(url); }, 4000);
}
/* ===== Behringer X32 / Midas M32: SNIPPET (.snp) con nomi, colori e 48V dei canali =====
   Perché uno snippet e non una scena: la scena (.scn) è l'istantanea di TUTTI i ~2000 parametri della
   console; lo snippet è il formato che la X32 ha apposta per applicare SOLO alcuni parametri senza
   toccare il resto — qui /ch/NN/config (nome ≤12 caratteri, icona, colore, sorgente) e /headamp/NNN
   (gain, phantom). Formato letto da file reali (scene pubbliche su GitHub) e dalla documentazione
   OSC non ufficiale di Patrick-Gilles Maillot: intestazione «#4.0# "nome" 1 1 1 1 1», poi una riga
   per comando OSC. Sorgente = ingresso locale NN (1–32); /headamp/000 è l'ingresso locale 1.
   Colori X32: OFF RD GN YE BL MG CY WH (+ «i» = invertito). I colori qui sono un DEFAULT sensato per
   famiglia (batteria rossa, basso blu, chitarre verdi, tastiere gialle, voci ciano…): il fonico li
   cambia in un tocco, ma 32 nomi non li ridigita. StageOn e Stageplot Pro lo fanno; da oggi anche
   noi. ⚠️ Da verificare su una console o su X32-Edit prima dello show: il formato è quello, ma qui
   nessuno ha una X32 sotto mano (23/08). */
var X32_MAX_CH=32, X32_NAME_MAX=12;
function x32Color(nome){
  var n=String(nome||"").toLowerCase();
  if(/kick|cassa|rullant|snare|tom|floor|hi.?hat|charl|over|oh |^oh|ride|crash|batter|drum|timpan|percuss|cong|bong|cajon/.test(n)) return "RD";
  if(/bass|contrab/.test(n)) return "BL";
  if(/chit|guit|gtr|ampli/.test(n)) return "GN";
  if(/tast|keys|piano|synth|organ|clav|rhodes|wurl|celest|arpa|harp|sequen|click|laptop|comput|track/.test(n)) return "YE";
  if(/voce|vox|voc|cori|coro|cantant|solist|speech|parl|mc\b/.test(n)) return "CY";
  if(/sax|tromb|tromba|trumpet|corno|horn|flaut|flute|oboe|clarin|fagott|fiati|brass/.test(n)) return "MG";
  if(/viol|cello|archi|string/.test(n)) return "WH";
  return "WH";
}
function x32Name(s, max){   /* ASCII, ≤12 per i canali, senza virgolette (il nome sta fra doppi apici nel file) */
  return String(s==null?"":s).normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/["\\]/g,"").replace(/[^\x20-\x7e]/g,"").replace(/\s+/g," ").trim().slice(0,max||X32_NAME_MAX);
}
/* rows = le righe della patch list; restituisce {snp, count, skipped}. Puro: niente DOM. */
function x32Snippet(rows, titolo){
  rows=rows||[];
  var lines=[], used={}, count=0, skipped=[];
  rows.forEach(function(r){
    var ch=(r.foh!=null && r.foh>0) ? r.foh : r.n;   /* il numero che il fonico ha sul banco (FOH se c'è) */
    if(!(ch>=1 && ch<=X32_MAX_CH)){ skipped.push(ch); return; }
    if(used[ch]) return; used[ch]=1;
    /* Il ripiego «CH n» va scelto DOPO la pulizia ASCII, non prima: un nome tutto fuori dall'ASCII
       (cinese, cirillico, sole emoji) è una stringa non vuota, quindi vinceva l'OR, ma x32Name la
       riduceva a niente e in console arrivava un canale senza nome — «"" 1 WH 1» (25/08). */
    var nome = r.reserved ? "SPARE" : (x32Name(r.short||r.name) || x32Name("CH "+ch));
    var col  = r.reserved ? "WHi" : x32Color(r.name);
    var nn=("0"+ch).slice(-2), ha=("00"+(ch-1)).slice(-3);
    lines.push("/ch/"+nn+"/config \""+nome+"\" 1 "+col+" "+ch);
    lines.push("/headamp/"+ha+" +0.0 "+(r.p48?"ON":"OFF"));
    count++;
  });
  var head='#4.0# "'+x32Name(titolo||"StagePlot", 16)+'" 1 1 1 1 1';   /* il nome dello snippet non ha il limite dei canali: una scena reale ne aveva 13 */
  return { snp: [head].concat(lines).join("\n")+"\n", count:count, skipped:skipped };
}
function exportX32Snippet(){
  var pl=(typeof patchList==="function")?patchList():{rows:[]};
  var r=x32Snippet(pl.rows, state.titolo);
  if(!r.count){ if(window.__toast) window.__toast("Nessun canale da esportare: aggiungi microfoni, DI o strumenti sul palco.", true); return false; }
  var name=fileName()+"-x32.snp";
  var blob=new Blob([r.snp], {type:"text/plain;charset=us-ascii"});
  var url=URL.createObjectURL(blob); dl(url, name); toastDownloaded(name);
  setTimeout(function(){ URL.revokeObjectURL(url); }, 4000);
  if(r.skipped.length && window.__toast) window.__toast(r.skipped.length+" canali oltre il 32 non entrano in una X32: lo snippet ha i primi 32.", true);
  try{ if(window.__sendEvent) window.__sendEvent({event:"export_csv",props:{rows:r.count, format:"x32snp"}}); }catch(e){}
  return true;
}
window.exportX32Snippet=exportX32Snippet;
/* Channel list (ingressi) in CSV, formato scelto. Fonte: la lista instrument-driven (stessa del PDF/pannello).
   opts.format: "excel-it" (sep ;) | "intl" (sep ,) | "ah" (Allen & Heath Director, best-effort). */
function channelListCsv(opts){
  opts=opts||{};
  var pl=(typeof patchList==="function")?patchList():{rows:[]};
  var count=pl.rows.length;
  if(opts.format==="ah"){
    /* Allen & Heath Director (dLive/Avantis): colonne Director documentate, separatore virgola, NO BOM.
       Nomi max 8 caratteri ALFANUMERICI senza accenti (vincolo A&H: äöüéß non ammessi, >8 char troncati);
       "-" = cella ignorata all'import; valori yes/no minuscoli. Fonte: doc A&H + tool community dlive-midi-tools.
       DA VERIFICARE sulla console prima dell'evento. */
    /* Il nome che conta è in CODA, non in testa: «Batteria 1 - Kick», «Batteria 1 - Rullante top»…
       troncando gli 8 caratteri dall'inizio uscivano otto canali chiamati tutti «Batteria», e il CSV
       serve proprio a NON ridigitare i nomi in console. Si prende la sigla (r.short, la stessa della
       colonna FOH del PDF) o l'ultimo segmento; gli omonimi residui prendono un progressivo (06/08). */
    var ahSeen={};
    var ah=pl.rows.map(function(r){
      if(r.reserved) return ["yes","SPARE","-","-","-","-","-",r.p48?"yes":"no"];
      var base=String(r.short||"").trim() || String(r.name||"").split(" - ").pop();
      var nm=ahName(base) || ahName(r.name) || "CH";
      if(ahSeen[nm]){ var k=++ahSeen[nm], sfx=String(k); nm=nm.slice(0,8-sfx.length)+sfx; }
      else ahSeen[nm]=1;
      var out=["yes", nm, "-", "-", "-", "-", "-", r.p48?"yes":"no"]; out._foh=r.foh; return out; });
    /* Nel formato A&H non esiste una colonna «canale»: il canale È la posizione della riga. Con più
       box i numeri FOH partono da 17 e il file caricava il Kick sul canale 1 mentre il PDF consegnato
       diceva 17 — due documenti dello stesso progetto che si contraddicono. Le posizioni non usate
       escono disabilitate, così la riga N è il canale N. */
    if(pl.hasFoh && ah.some(function(x){ return x._foh; })){
      var maxFoh=0; ah.forEach(function(x){ if(x._foh>maxFoh) maxFoh=x._foh; });
      var slots=[], coda=[];
      ah.forEach(function(x){ if(x._foh) slots[x._foh-1]=x; else coda.push(x); });
      var full=[]; for(var i=0;i<maxFoh;i++) full.push(slots[i]||["no","-","-","-","-","-","-","no"]);
      ah=full.concat(coda);
    }
    return { csv: rowsToCsv(["Enabled","Name","Color","Source","Socket","Gain","Pad","Phantom"], ah, ",").replace(/^﻿/,""), count:count };
  }
  var sep = opts.format==="intl" ? "," : ";";
  var rows=pl.rows.map(function(r){
    var patch=(r.patch && r.patch!=="—") ? r.patch : "";   /* "—" è il placeholder visivo del pannello, non un dato: nel CSV va vuoto */
    /* il numero è quello che il fonico ha sul banco: con più box/Device ID vale il canale FOH continuo,
       come nel pannello e nel PDF (prima il CSV usava l'indice di riga → numeri sfasati all'import) */
    /* coppia stereo con asta unica: il service deve leggere che il supporto è quello della riga sopra,
       non una cella vuota da interpretare come «asta da decidere» */
    return [(pl.hasFoh&&r.foh)?r.foh:r.n, r.reserved?"RISERVATO":r.name, r.mic||"", r.standShared?"stessa asta":(r.stand||""), r.p48?"48V":"", patch];
  });
  return { csv: rowsToCsv(["Canale","Sorgente","Mic/DI","Asta","Phantom","Patch"], rows, sep), count: count };
}
function exportChannelCsv(opts){
  var r=channelListCsv(opts);
  if(!r.count){ if(window.__toast) window.__toast("Nessun canale da esportare: aggiungi microfoni, DI o strumenti sul palco.", true); return false; }
  var suffix = (opts&&opts.format==="ah") ? "-channel-list-AH.csv" : "-channel-list.csv";
  downloadCsv(r.csv, fileName()+suffix);
  try{ if(window.__sendEvent) window.__sendEvent({event:"export_csv",props:{rows:r.count, format:(opts&&opts.format)||"excel-it"}}); }catch(e){}
  return true;
}
/* apre il piccolo dialogo di scelta formato (voce menu / bottone pannello) */
function openCsvExport(){
  if(!channelListCsv().count){ if(window.__toast) window.__toast("Nessun canale da esportare: aggiungi microfoni, DI o strumenti sul palco.", true); return; }
  var m=document.getElementById("csvPicker"); if(m) m.hidden=false; else exportChannelCsv();
}
window.exportChannelCsv=exportChannelCsv; window.openCsvExport=openCsvExport;
(function(){
  var m=document.getElementById("csvPicker"); if(!m) return;
  m.querySelectorAll(".csvfmt").forEach(function(b){ b.addEventListener("click", function(){
    var fmt=b.getAttribute("data-fmt");
    var ok = fmt==="x32snp" ? exportX32Snippet() : exportChannelCsv({format:fmt});
    if(ok) m.hidden=true; }); });
  var c=document.getElementById("csvClose"); if(c) c.addEventListener("click", function(){ m.hidden=true; });
  m.addEventListener("click", function(e){ if(e.target===m) m.hidden=true; });
  document.addEventListener("keydown", function(e){ if(!m.hidden && e.key==="Escape") m.hidden=true; });
})();

/* tabella input/output a lato della planimetria (coord. SVG dell'export) */
function channelTableSvg(x, top, w){
  var lh=34, s='';
  function short(x,n){ x=String(x||""); return x.length>n ? x.slice(0,n-3)+"..." : x; }
  function section(title, rows, sy){
    var t='<text x="'+x+'" y="'+sy+'" font-size="26" font-weight="700" fill="#111827">'+esc(title)+'</text>'+
          '<line x1="'+x+'" y1="'+(sy+11)+'" x2="'+(x+w)+'" y2="'+(sy+11)+'" stroke="#111827" stroke-width="2"/>';
    var ry=sy+11+lh;
    if(rows.length){
      t+='<text x="'+x+'" y="'+(ry-4)+'" font-size="13" fill="#6b7280">CH</text>'+
         '<text x="'+(x+44)+'" y="'+(ry-4)+'" font-size="13" fill="#6b7280">SORGENTE / MIX</text>'+
         '<text x="'+(x+270)+'" y="'+(ry-4)+'" font-size="13" fill="#6b7280">MIC / TIPO</text>'+
         '<text x="'+(x+420)+'" y="'+(ry-4)+'" font-size="13" fill="#6b7280">STAND / PATCH</text>'+
         '<text x="'+(x+585)+'" y="'+(ry-4)+'" font-size="13" fill="#6b7280">48V</text>'+
         '<text x="'+(x+640)+'" y="'+(ry-4)+'" font-size="13" fill="#6b7280">NOTE</text>';
      ry+=20;
    }
    rows.forEach(function(r,i){
      if(i%2===1) t+='<rect x="'+(x-6)+'" y="'+(ry-24)+'" width="'+(w+12)+'" height="'+lh+'" fill="#f4f5f7"/>';
      t+='<text x="'+x+'" y="'+ry+'" font-size="22" fill="#6b7280">'+(i+1)+'</text>'+
         '<text x="'+(x+44)+'" y="'+ry+'" font-size="20" fill="#111827">'+esc(short(r.src,25))+'</text>'+
         '<text x="'+(x+270)+'" y="'+ry+'" font-size="20" fill="#374151">'+esc(short(r.mic,14))+'</text>'+
         '<text x="'+(x+420)+'" y="'+ry+'" font-size="18" fill="#374151">'+esc(short(r.stand,16))+'</text>'+
         '<text x="'+(x+596)+'" y="'+ry+'" font-size="18" fill="#374151" text-anchor="middle">'+(r.p48?"yes":"")+'</text>'+
         '<text x="'+(x+640)+'" y="'+ry+'" font-size="18" fill="#6b7280">'+esc(short(r.notes,26))+'</text>';
      ry+=lh;
    });
    return {svg:t, endY:ry};
  }
  var sec1=section("INPUT PATCH", state.inputs, top+30); s+=sec1.svg;
  if(state.outputs.length){ var sec2=section("MONITOR / OUTPUT", state.outputs, sec1.endY+34); s+=sec2.svg; }
  return s;
}
function buildExportSvg(){
  var keep=sel, keepSet=selSet; sel=null; selSet={};
  recalcStageBBox();
  var m=130, W=state.stage.w, D=state.stage.d, head=70;
  var hasCL = state.inputs.length || state.outputs.length;
  var tableW = hasCL ? 940 : 0;
  var tableRows = state.inputs.length + state.outputs.length;
  var tableSections = (state.inputs.length?1:0) + (state.outputs.length?1:0);
  var tableH = hasCL ? 16 + tableSections*90 + tableRows*34 : 0;
  var keepEdit=stageEdit; stageEdit=false;          /* mai l'overlay di "modifica palco" nell'export */
  var inner = sceneMarkup({espandi:true}); stageEdit=keepEdit;   /* export: markup autonomo, vedi libIconScene */ sel=keep; selSet=keepSet;
  var css = document.querySelector("style").textContent.replace(/\/\*[\s\S]*?\*\//g,"");   /* via i commenti: un '<' in un commento romperebbe l'SVG */
  var titolo = esc(state.titolo||"Stage plot");
  var luogo = esc(state.luogo||"");
  var oggi = new Date().toLocaleDateString("it-IT");
  var vbW = W+2*m+tableW, vbH = Math.max(D+2*m+head, tableH);
  var svgStr = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="'+(-m)+' '+(-m-head)+' '+vbW+' '+vbH+'">'+
    '<style>'+css+'</style>'+DEFS+
    '<rect x="'+(-m)+'" y="'+(-m-head)+'" width="'+vbW+'" height="'+vbH+'" fill="#ffffff"/>'+
    '<text x="'+(-m+30)+'" y="'+(-m-head+44)+'" font-size="34" font-weight="700" fill="#111827">'+titolo+(luogo?'<tspan font-size="22" font-weight="400" fill="#6b7280">   ·   '+luogo+'</tspan>':'')+'</text>'+
    '<text x="'+(W+m-30)+'" y="'+(-m-head+44)+'" font-size="20" fill="#6b7280" text-anchor="end">'+oggi+' · simonecastellan.com · griglia 0,5 m · palco '+(W/100)+'×'+(D/100)+' m'+stageHeightNote()+'</text>'+
    inner+
    '<line x1="0" y1="'+(D+m-40)+'" x2="100" y2="'+(D+m-40)+'" stroke="#111827" stroke-width="6"/>'+
    '<text x="50" y="'+(D+m-52)+'" font-size="18" fill="#111827" text-anchor="middle">1 m</text>'+
    (hasCL ? '<line x1="'+(W+m+14)+'" y1="'+(-m-head+16)+'" x2="'+(W+m+14)+'" y2="'+(D+m)+'" stroke="#e5e7eb" stroke-width="2"/>'+
             channelTableSvg(W+m+44, -m-head+16, tableW-80) : '')+
    '</svg>';
  render();
  return {svgStr:svgStr, vbW:vbW, vbH:vbH};
}
function renderPng(scale){
  return new Promise(function(resolve, reject){
    var ex=buildExportSvg(), img=new Image(), k=scale||2;
    img.onload=function(){
      var c=document.createElement("canvas"); c.width=ex.vbW*k; c.height=ex.vbH*k;
      c.getContext("2d").drawImage(img,0,0,c.width,c.height);
      c.toBlob(function(b){ b ? resolve(b) : reject(new Error("toBlob nullo")); },"image/png");
    };
    img.onerror=function(){ reject(new Error("rendering SVG fallito")); };
    img.src="data:image/svg+xml;charset=utf-8,"+encodeURIComponent(ex.svgStr);
  });
}
/* (pulsante "Esporta PNG" rimosso; renderPng resta per il PDF) */

/* ============ EXPORT PDF IN SCALA (jsPDF, A4/A3 orizzontale) ============ */
/* mm di carta per cm reali a scala 1:N → cm*10/N. Foglio orizzontale in mm. */
var PAPER={ a4:{w:297,h:210}, a3:{w:420,h:297}, a2:{w:594,h:420} };
var SCALES=[50,100,200,250,500];   /* aggiunte 1:250 e 1:500 per aree grandi (planimetrie/piazze) */
/* area di stampa in cm reali: la cornice personalizzata se impostata, altrimenti l'ingombro del palco */
function printArea(){
  if(state.printFrame){ var f=state.printFrame; return {x:f.x, y:f.y, w:f.w, h:f.h, custom:true}; }
  /* auto: solo il palco — elementi fuori dal palco clippati dalla viewport SVG */
  recalcStageBBox();
  return {x:0, y:0, w:state.stage.w, h:state.stage.d, custom:false};
}
function pdfLayout(paperKey, orient, cartH){
  cartH = cartH || 22;
  var p=PAPER[paperKey], pw=p.w, ph=p.h;
  if(orient==="portrait"){ pw=p.h; ph=p.w; }
  var M=10, topLbl=7, botLbl=5;
  return { pw:pw, ph:ph, M:M, cartH:cartH, orient:orient||"landscape", paper:paperKey,
    drawX:M+10, drawY:M+topLbl,
    drawW:pw-2*M-20, drawH:ph-M-cartH-botLbl-(M+topLbl) };
}
/* Nome per esteso del foglio, per il cartiglio: senza il formato la scala non basta a stampare —
   1:100 su A3 e 1:100 su A4 sono due fogli diversi, e chi riceve il PDF non ha modo di sapere quale
   caricare in stampante (Simone, 11/08: «c'è la scala ma non so se stamparlo in A3 o A4»). */
function paperLabel(paperKey, orient){
  return String(paperKey||"a4").toUpperCase()+" "+(orient==="portrait" ? "verticale" : "orizzontale");
}
/* Altezza del cartiglio per foglio+orientamento: la stessa formula che usano anteprima e PDF, in un
   posto solo. Prima ogni chiamante la ricalcolava a modo suo e la scala automatica usava 22 fisso. */
function cartHFor(header, paperKey, orient){
  var L=pdfLayout(paperKey, orient, 22);
  return cartHForHeader(header, L.pw-2*L.M-90);
}
/* stima l'altezza del cartiglio in base alle righe dell'intestazione (8pt ≈ 1.8mm/char) */
function cartHForHeader(header, titleW){
  var base=22;
  try{ if(pdfTotals().length) base+=5; }catch(e){}   /* riga dei totali: va contata, o «Automatica» sceglie una scala che poi non entra */
  if(!header || !String(header).trim()) return base;
  var charsPerLine=Math.max(20, Math.floor(titleW/1.8));
  return base+Math.max(0, Math.ceil(String(header).trim().length/charsPerLine)-1)*4;
}
function scaleFits(N, paperKey, orient, cartH){
  var L=pdfLayout(paperKey, orient, cartH), A=printArea(), DM=A.custom?0:80;
  return (A.w+2*DM)*10/N<=L.drawW && (A.h+2*DM)*10/N<=L.drawH;
}
/* Geometria del disegno sul foglio a scala 1:N (mm). Se il contenuto sfora l'area utile, NON lo rimpicciolisce:
   tiene la scala esatta (10/N mm per cm) e RITAGLIA la parte centrale che ci sta (cropVb). */
function pdfStageBox(N, paperKey, orient, cartH){
  var L=pdfLayout(paperKey, orient, cartH), A=printArea(), DM=A.custom?0:80;
  var mmPerCm=10/N;
  var fullMmW=(A.w+2*DM)*mmPerCm, fullMmH=(A.h+2*DM)*mmPerCm;
  var visMmW=Math.min(fullMmW, L.drawW), visMmH=Math.min(fullMmH, L.drawH);
  var ix=L.drawX+(L.drawW-visMmW)/2, iy=L.drawY+(L.drawH-visMmH)/2;
  var cropCmW=visMmW/mmPerCm, cropCmH=visMmH/mmPerCm;
  var cx=A.x-DM+(A.w+2*DM)/2, cy=A.y-DM+(A.h+2*DM)/2;   /* centro della scena (area + margine quote) */
  var vb={x:cx-cropCmW/2, y:cy-cropCmH/2, w:cropCmW, h:cropCmH};
  var cropped = visMmW < fullMmW-0.05 || visMmH < fullMmH-0.05;
  return {L:L, A:A, ix:ix, iy:iy, mmW:visMmW, mmH:visMmH, vb:vb, cropped:cropped, mmPerCm:mmPerCm};
}
/* cartH: altezza REALE del cartiglio (cresce se il riferimento va a capo). Passarla è indispensabile:
   col default 22 "Automatica" sceglieva una scala che nel PDF non entrava più, e il disegno veniva
   ritagliato in silenzio — l'anteprima, che usa l'altezza vera, mostrava un'altra cosa (27/07). */
/* Quanto ingrandire le scritte del disegno perché sulla carta restino della dimensione che avevano
   a 1:100 (~1,4 mm): il disegno rimpicciolisce di N, il testo cresce di N/100. Sopra 1:250 il testo
   non cresce più — sarebbe più grande degli elementi che nomina, e a quelle scale (piazze, aree
   grandi) i nomi non si leggono comunque: si guarda l'ingombro.
   CORPO_RIF e' LA manopola della leggibilita' del PDF: 100 da' 1,4 mm sulla carta (quanto si vedeva a
   1:100, la resa storica), 80 da' 1,75 mm. Piu' in giu' si puo' andare — la passata anti-collisione
   regge fino a 2,45 mm — ma il prezzo e' che i nomi si allontanano dall'elemento per schivarsi: su una
   band stretta, a 2,45 mm uno scende di mezzo metro di palco e non si capisce piu' di chi sia. 80 e' il
   punto in cui si guadagna un quarto di corpo e gli spostamenti restano sotto i 20 cm. */
var CORPO_RIF=80;
function pdfTextK(N){
  var n=+N; if(!isFinite(n) || n<=0) return 1;
  return Math.min(n, 250)/CORPO_RIF;
}
function autoScale(paperKey, orient, cartH){
  for(var i=0;i<SCALES.length;i++){ if(scaleFits(SCALES[i],paperKey,orient,cartH)) return SCALES[i]; }
  return SCALES[SCALES.length-1];  /* non entra nemmeno a 1:500 → usa la scala più piccola e ritaglia ciò che ci sta */
}
function resolveScale(paperKey, scaleSel, orient, cartH){
  return scaleSel==="auto" ? autoScale(paperKey, orient, cartH) : parseInt(scaleSel,10);
}
/* ORIENTAMENTO AUTOMATICO (11/08, chiesto da Simone): un palco largo e poco profondo vuole il foglio
   orizzontale, uno stretto e profondo quello verticale — e sbagliarlo costa una scala intera (1:200
   invece di 1:100 significa il disegno a metà). Non si guarda la proporzione del palco ma il RISULTATO:
   si prova il foglio in tutti e due i versi e si tiene quello che stampa il disegno più grande.
   Nell'ordine: chi non ritaglia batte chi ritaglia · scala più grande (N minore) · a parità, chi
   riempie meglio la pagina. Resta una SCELTA dell'utente: i chip Orizz./Vert. vincono sempre. */
function pdfBestOrient(paperKey, scaleSel, header){
  var best=null;
  /* landscape per primo: è il verso di partenza, e a parità di risultato resta lui — uno stage plot
     si legge come lo si guarda dal pubblico, e a parità di scala il disegno stampato è IDENTICO nei
     due versi, quindi girare il foglio non darebbe niente in cambio. (Un primo tentativo pesava
     anche quanto si riempie la pagina: premiava il foglio più stretto e mandava in verticale un palco
     quadrato, che alla stessa scala non ci guadagnava nulla.) */
  ["landscape","portrait"].forEach(function(o){
    var ch=cartHFor(header, paperKey, o);
    var N=resolveScale(paperKey, scaleSel, o, ch);
    var box=pdfStageBox(N, paperKey, o, ch);
    /* quando NESSUNO dei due versi ce la fa, vince chi lascia vedere più palco */
    var visto=box.mmW*box.mmH;
    var c={o:o, N:N, cropped:!!box.cropped, visto:visto};
    if(!best){ best=c; return; }
    if(c.cropped!==best.cropped){ if(!c.cropped) best=c; return; }   /* chi entra intero batte chi ritaglia */
    if(c.N!==best.N){ if(c.N<best.N) best=c; return; }               /* scala più grande = N minore */
    if(best.cropped && c.visto>best.visto+0.5) best=c;               /* pari e tutti e due ritagliati: più palco visibile */
  });
  return best ? best.o : "landscape";
}
/* Orientamento effettivo: "auto" risolto sul progetto di adesso, altrimenti quello scelto a mano. */
function pdfOrientValue(paperKey, scaleSel, header){
  var s=document.getElementById("pdfOrient");
  var v=s ? s.value : "auto";
  return v==="auto" ? pdfBestOrient(paperKey, scaleSel, header) : v;
}
/* Scala personalizzata, valore effettivo (10–500). Number() e non parseInt: "1e3" con parseInt
   diventava 1 → 1:10 mentre si chiedeva 1:1000, e i decimali sparivano senza dirlo. Vuoto o non
   numerico → 75, il valore di partenza; 0 e i negativi vanno al minimo, non al default. */
function pdfScaleClamp(raw){
  var t=String(raw==null?"":raw).trim();
  var n=t==="" ? 75 : Number(t);
  if(!isFinite(n)) n=75;
  return Math.round(Math.max(10, Math.min(500, n)));
}
/* M-scala: valore di scala effettivo — se "Personalizzata", legge l'input 1:N (10–500).
   NON riscrive il campo: lo faceva, e siccome l'anteprima si aggiorna a ogni tasto (`input`), il
   valore veniva rimesso nei limiti PRIMA che si finisse di scrivere — digitando «150» il campo
   diventava «10» sulla prima cifra e il cursore saltava in fondo, così i numeri di mezzo erano
   irraggiungibili: sembrava che l'app rifiutasse le scale volute (11/08). Ora i limiti si applicano
   quando si esce dal campo (`change`/blur), che è quando l'utente ha finito. */
function pdfScaleValue(){ var s=document.getElementById("pdfScale"); if(!s) return "auto";
  if(s.value==="custom"){
    var c=document.getElementById("pdfScaleCustom");
    return String(pdfScaleClamp(c && c.value));
  }
  return s.value;
}
/* SVG dell'area di stampa: palco + griglia + elementi + quote dimensionali.
   Con area di stampa automatica (non personalizzata) espande il viewBox di 80 unità per lato
   per includere i label di quota (posizionati fuori dal rettangolo palco). */
function stageSceneSvg(cropVb, opts){
  opts=opts||{}; var focus=opts.focus||null;   /* null | clean | cabin | cabout | mond | cabaudio(legacy: i 3 audio fusi) | elec | sectionmic */
  recalcStageBBox();
  var A=printArea(), DM=A.custom?0:80;
  /* cropVb (opzionale): finestra ritagliata quando il disegno non entra nel foglio — si stampa solo la
     parte centrale che ci sta, sempre in scala. Senza cropVb = scena intera (area + margine quote). */
  var vb=cropVb || {x:A.x-DM, y:A.y-DM, w:A.w+2*DM, h:A.h+2*DM};
  var keep=sel, keepSet=selSet; sel=null; selSet={};
  /* Il disegno è per la STAMPA, non per lo schermo: i generatori che semplificano in base a quanto
     l'elemento è grande sul monitor (es. il pannello della stage box, sbLod) devono dare il massimo
     dettaglio. Va acceso PRIMA di costruire gli item — __cabStatic arriva più sotto, quando ormai
     sarebbe tardi. Ripristinato nel finally in fondo alla funzione. */
  var _keepPrint=window.__scenePrint; window.__scenePrint=true;
  /* Di quanto le scritte verranno ingrandite (scaleSvgFonts, più sotto). Serve QUI, mentre si
     disegna, perché lo sbraccio dell'etichetta — quanto sta staccata dall'elemento che nomina —
     si calcola sul corpo del testo: ingrandire il testo dopo, a coordinata già scritta, lo fa
     scendere addosso all'elemento. Il font invece resta scritto com'è: lo moltiplica la regex,
     e moltiplicarlo anche qui darebbe k². */
  var _keepK=window.__sceneTextK; window.__sceneTextK=(opts.textK>0?opts.textK:1);
  var _keepNudge=window.__lblNudge; window.__lblNudge=lblNudges(window.__sceneTextK);
  /* classifica ogni elemento per la vista a fuoco (fg) o sfumato (bg) — layerFgItem = STESSA
     classificazione del SOLO sul canvas: la vista "cabaudio" include ritorni e P.M. → fg anche
     monitor/mixerini; la vista "elec" include i CARICHI (wattOf>0), come chiesto da Simone */
  function isAudioTech(it){ return layerFgItem("cabin",it) || layerFgItem("cabout",it) || layerFgItem("mond",it); }
  var fgItems='', bgItems='', zoneItems='';
  sortedItems().forEach(function(it){
    if(it.type==="miczone"){ zoneItems+=itemMarkup(it); return; }
    var m=itemMarkup(it);
    if(!focus || focus==="clean"){ fgItems+=m; return; }
    if(focus==="cabaudio" && isAudioTech(it)) fgItems+=m;
    else if(focus==="cabin" && layerFgItem("cabin",it)) fgItems+=m;     /* 1 pagina per layer (17/07) */
    else if(focus==="cabout" && layerFgItem("cabout",it)) fgItems+=m;
    else if(focus==="mond" && layerFgItem("mond",it)) fgItems+=m;
    else if(focus==="elec" && layerFgItem("elec",it)) fgItems+=m;
    else bgItems+=m;
  });
  sel=keep; selSet=keepSet;
  var css=document.querySelector("style").textContent.replace(/\/\*[\s\S]*?\*\//g,"");   /* via i commenti: un '<' in un commento romperebbe l'SVG */
  var hasVenue = state.venue && state.venue.enabled!==false && state.venue._dataUrl;
  var venue = hasVenue
    ? '<clipPath id="paClip"><rect x="'+A.x+'" y="'+A.y+'" width="'+A.w+'" height="'+A.h+'"/></clipPath>'+
      '<g clip-path="url(#paClip)">'+venueMarkup()+'</g>'   /* planimetria di sfondo, ritagliata all'area di stampa */
    : '';
  /* Le quote per blocco restano, TRANNE quando chi esporta le disegna già di suo (opts.noBlockDims):
     su un palco di un pezzo solo «6 m» finiva scritto due volte — una qui, dentro il disegno e in
     scala, e una da jsPDF fuori dal riquadro a corpo fisso. Stessa misura, due grafie, e le due si
     accavallavano sopra FONDO PALCO. Su un palco composto invece queste quotano i singoli blocchi e
     dicono qualcosa che l'ingombro totale non dice: lì restano. */
  var dims = (A.custom || opts.noBlockDims) ? '' : stageDimsMarkup();
  var W=state.stage.w, D=state.stage.d;
  var zones='<text fill="#1f2937" font-size="16" letter-spacing="2" text-anchor="middle" x="'+(W/2)+'" y="-42">FONDO PALCO</text>'+
            '<text fill="#1f2937" font-size="16" letter-spacing="2" text-anchor="middle" x="'+(W/2)+'" y="'+(D+38)+'">PUBBLICO</text>';
  /* overlay cablaggio (statico, senza maniglie di editing), filtrato per focus: audio (cavi+rete+P.M.+legenda)
     ed elettrico separati, così ogni pagina-vista mostra SOLO il proprio layer a piena opacità */
  var _keepCab=selCab, _keepStatic=window.__cabStatic; selCab=null; window.__cabStatic=true;
  var audioCab='', elecCab='';
  try{
    /* 1 pagina per layer (17/07): il SOLO temporaneo riusa il meccanismo del canvas — layerShown segue
       la mappa layerSoloUI e i markup emettono SOLO il layer a fuoco, a piena opacità (op=1 in solo).
       Solo attorno agli overlay: gli item sono già classificati sopra (fg/bg). */
    var _keepSolo=layerSoloUI;
    try{
      if(focus==="cabin"){ layerSoloUI={cabin:true, net:true}; audioCab=cablingMarkup()+netMarkup()+cableLegendMarkup(); }
      else if(focus==="cabout"){ layerSoloUI={cabout:true}; audioCab=cablingMarkup()+cableLegendMarkup(); }
      else if(focus==="mond"){ layerSoloUI={mond:true}; audioCab=monDigMarkup(); }
      else if(focus==="elec"){ layerSoloUI={elec:true}; elecCab=elecMarkup(); }
      else if(focus===null || focus==="cabaudio"){ audioCab=cablingMarkup()+netMarkup()+monDigMarkup()+cableLegendMarkup(); if(focus===null) elecCab=elecMarkup(); }
    } finally { layerSoloUI=_keepSolo; }
  }catch(_e){ audioCab=''; elecCab=''; }
  selCab=_keepCab; window.__cabStatic=_keepStatic;
  /* composizione per vista. FADE = opacità del CONTESTO nelle pagine-vista: il layer competente resta
     al 100%, il resto del palco sfuma. 0.3 (Simone 17/07): a 0.2 il contesto spariva in fotocopia/stampa
     B/N; a 0.3 resta orientabile ma chiaramente secondario; oltre 0.35 competerebbe col layer a fuoco. */
  var FADE="0.3";
  var showZones = (focus===null || focus==="sectionmic");   /* le zone si vedono solo nella scena piena o nella loro pagina-vista */
  var bgGroup = bgItems ? '<g style="opacity:'+FADE+'">'+bgItems+'</g>' : '';
  /* zoneGroup nel ramo else è mostrato SOLO per focus===null (export PNG/legacy) → zone a resa naturale, nessuna opacità forzata */
  var zoneGroup = showZones && zoneItems ? '<g id="layMicZones">'+zoneItems+'</g>' : '';
  /* z-order: pavimento → zone(sfondo) → elementi sfumati → elementi a fuoco → overlay */
  var body;
  if(focus==="sectionmic"){
    /* qui le zone sono il soggetto (piena resa), tutto il palco sfuma */
    body = stageFloorMarkup()+dims+zones+'<g style="opacity:'+FADE+'">'+bgItems+fgItems+'</g>'+'<g id="layMicZones">'+zoneItems+'</g>';
  } else {
    body = stageFloorMarkup()+dims+zones+zoneGroup+bgGroup+fgItems+audioCab+elecCab;
  }
  window.__scenePrint=_keepPrint;   /* fine del disegno per la stampa: si torna alle regole dello schermo */
  window.__sceneTextK=_keepK; window.__lblNudge=_keepNudge;
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="'+vb.x+' '+vb.y+' '+vb.w+' '+vb.h+'">'+
    '<style>'+scaleSvgTextHalos(scaleSvgFonts(css, opts.textK), opts.textK)+'</style>'+DEFS+
    '<rect x="'+vb.x+'" y="'+vb.y+'" width="'+vb.w+'" height="'+vb.h+'" fill="#ffffff"/>'+
    venue+scaleSvgFonts(body, opts.textK)+'</svg>';
}
/* TESTO A DIMENSIONE FISSA SUL FOGLIO (11/08). Le scritte del disegno — nomi, quote, FONDO PALCO —
   sono espresse nelle unità dell'SVG, che sono CENTIMETRI REALI: un corpo 14 diventa 14 cm di palco,
   cioè 140/N mm sulla carta. A 1:50 sono 2,8 mm e si leggono; a 1:200 sono 0,7 mm e sono puntini, e
   un rider di un palco da festival esce illeggibile. Nei disegni tecnici vale l'opposto: la geometria
   scala, il testo no — si quota in millimetri-carta. Qui compenso moltiplicando ogni corpo per N/100,
   così il testo mantiene a OGNI scala la dimensione fisica che aveva a 1:100 (~1,4 mm), che è quella
   su cui sono tarati gli sbracci delle etichette (lblBandOf): ingrandirlo di più le fa collidere.
   Un punto solo, e per costruzione vale sia per il PDF sia per l'anteprima, che passano di qui. */
function scaleSvgFonts(s, k){
  if(!s || !(k>0) || Math.abs(k-1)<0.001) return s;
  var mul=function(n){ return (+n*k).toFixed(2); };
  return String(s)
    .replace(/font-size:\s*([\d.]+)px/g, function(m,n){ return "font-size:"+mul(n)+"px"; })
    .replace(/letter-spacing:\s*([\d.]+)px/g, function(m,n){ return "letter-spacing:"+mul(n)+"px"; })
    /* i corpi scritti come attributo di presentazione (FONDO PALCO, PUBBLICO, i nomi col corpo
       scelto a mano dall'utente): il CSS non li vede, vanno moltiplicati nel markup */
    .replace(/font-size="([\d.]+)"/g, function(m,n){ return 'font-size="'+mul(n)+'"'; })
    .replace(/letter-spacing="([\d.]+)"/g, function(m,n){ return 'letter-spacing="'+mul(n)+'"'; });
}
/* L'alone bianco che stacca le scritte dallo sfondo deve crescere col testo, o a scale piccole
   sparisce. Ma `stroke-width` nel CSS è quasi tutto TRATTO DEI DISEGNI: moltiplicarlo alla cieca
   ingrosserebbe cavi, bordi e griglia. Quindi si tocca solo dentro le regole che parlano di testo. */
function scaleSvgTextHalos(css, k){
  if(!css || !(k>0) || Math.abs(k-1)<0.001) return css;
  return String(css).replace(/\{[^{}]*\}/g, function(blocco){
    if(blocco.indexOf("font-size")<0) return blocco;
    return blocco.replace(/stroke-width:\s*([\d.]+)px/g, function(m,n){ return "stroke-width:"+(+n*k).toFixed(2)+"px"; });
  });
}
function svgToDataUrl(svgStr, pxW, pxH, type){
  /* iOS Safari rasterizza l'SVG SOLO se il root ha width/height espliciti (non basta il viewBox) */
  svgStr = svgStr.replace(/^<svg /, '<svg width="'+pxW+'" height="'+pxH+'" ');
  return new Promise(function(res,rej){
    /* Blob URL invece di data URI: Chrome rifiuta SVG >~200KB come data URI in img.src */
    var blob = new Blob([svgStr], {type:'image/svg+xml'});
    var url = URL.createObjectURL(blob);
    var img=new Image();
    img.onload=function(){
      URL.revokeObjectURL(url);
      try{
        var c=document.createElement("canvas"); c.width=pxW; c.height=pxH;
        var ctx=c.getContext("2d"); ctx.fillStyle="#fff"; ctx.fillRect(0,0,pxW,pxH);
        ctx.drawImage(img,0,0,pxW,pxH);
        res(type==="image/png" ? c.toDataURL("image/png") : c.toDataURL("image/jpeg", 0.95));
      }catch(e){ URL.revokeObjectURL(url); rej(e); }
    };
    img.onerror=function(){ URL.revokeObjectURL(url); rej(new Error("SVG→PNG fallito")); };
    img.src=url;
  });
}
/* jsPDF + svg2pdf sono incorporati nel file (blocchi LIB-*-BUNDLE) → export PDF sempre disponibile, anche offline */
/* Lazy-load delle librerie PDF (audit P1): jsPDF+svg2pdf (~449KB) non sono più inline — vengono
   caricate da /vendor/pdf.min.js al primo export, non a ogni avvio. La promise è cachata (un solo
   caricamento); su errore si azzera per consentire un nuovo tentativo. */
var __pdfLibsPromise=null;
function loadJsPDF(){
  if(window.jspdf && window.jspdf.jsPDF) return Promise.resolve();
  if(__pdfLibsPromise) return __pdfLibsPromise;
  __pdfLibsPromise=new Promise(function(res,rej){
    var s=document.createElement("script"); s.src="/vendor/pdf.min.js"; s.async=true;
    s.onload=function(){ (window.jspdf && window.jspdf.jsPDF) ? res() : rej(new Error("jsPDF non disponibile dopo il caricamento")); };
    s.onerror=function(){ __pdfLibsPromise=null; rej(new Error("Impossibile caricare le librerie PDF")); };
    document.head.appendChild(s);
  });
  return __pdfLibsPromise;
}
/* ===== Report tecnico cablaggio audio (Fase 7) — PDF testuale: riepilogo, collegamenti, criticità ===== */
function cabReportPdf(shared){
  var R=cabResult(true);
  if(!R.totIn){ if(!shared) alert("Nessuna sorgente audio sul palco: il report sarebbe vuoto."); return; }
  var run=function(doc){
    if(shared) doc.addPage("a4","portrait");
    var W=210, M=16, y=0;
    function line(txt, size, bold, color, dy){
      if(y>282){ doc.addPage(); y=16; }
      doc.setFontSize(size||10); doc.setFont("helvetica", bold?"bold":"normal");
      doc.setTextColor(color||"#1f2937");
      doc.text(String(txt), M, y); y+=(dy||5);
    }
    doc.setFillColor("#0d9488"); doc.rect(0,0,W,14,"F");
    doc.setTextColor("#ffffff"); doc.setFontSize(11); doc.setFont("helvetica","bold");
    doc.text("STAGE PLOT — Report cablaggio audio", M, 9);
    doc.setFontSize(9); doc.setFont("helvetica","normal");
    doc.text(new Date().toLocaleDateString("it-IT"), W-M, 9, {align:"right"});
    y=22;
    if(state.titolo || state.luogo) line((state.titolo||"")+(state.luogo?" — "+state.luogo:""), 12, true, null, 8);
    /* M-06 onestà tecnica: le lunghezze sono stime sul percorso ortogonale, da verificare in loco. */
    (function(){ var d="Le lunghezze sono STIME sul percorso ortogonale (Manhattan) più margine di reach, utili per l'ordine cavi. Il percorso reale sul palco — pieghe, ostacoli, dislivelli, passaggi — va verificato in loco.";
      doc.setFontSize(8); doc.setFont("helvetica","italic"); var dl=doc.splitTextToSize(d, W-2*M-6), dh=dl.length*3.5+4;
      doc.setFillColor("#f0fdfa"); doc.setDrawColor("#0d9488"); doc.roundedRect(M, y-3, W-2*M, dh, 1.5, 1.5, "FD");
      doc.setTextColor("#0f766e"); doc.text(dl, M+3, y+1); y+=dh+4; })();
    line("Riepilogo", 12, true, "#0d9488", 6);
    if(R.mixer && MIXER_DB[R.mixer]) line("Mixer FOH: "+hwLabel(R.mixer,MIXER_DB)+" ("+hwProtoNames(MIXER_DB[R.mixer].proto)+")", 10, false, null, 5);
    if(R.home) line("Punto principale di connessione: "+R.home.name, 10, false, null, 5);
    line("Input audio totali: "+R.totIn+" / "+R.capTot+" canali disponibili", 10, false, null, 5);
    R.boxes.forEach(function(b){
      var hw=b.hw&&STAGEBOX_DB[b.hw];
      line("Stage box "+b.letter+": "+(hw?hwLabel(b.hw,STAGEBOX_DB)+" — "+hwProtoNames(hw.proto):b.name)+"  ("+b.used+"/"+b.cap+" ch"+(b.auto?", proposta 8ch":"")+")", 9.5, false, null, 4.8);
    });
    var cuts=Object.keys(R.cables).sort(function(a,b){ return parseFloat(a)-parseFloat(b); });
    if(cuts.length) line("Cavi XLR: "+cuts.map(function(c){ return R.cables[c]+" × "+c; }).join(", "), 10, false, null, 5);
    if(R.diMono||R.diStereo) line("DI da prevedere: "+(R.diMono?R.diMono+" mono":"")+(R.diMono&&R.diStereo?" + ":"")+(R.diStereo?R.diStereo+" stereo":""), 10, false, null, 5);
    /* aste: nei rider veri il dato sta qui, come totale ("(3) telescoping boom mic stands") */
    try{ var _sn=standNeeds(), _snParts=STAND_KINDS.filter(function(k){ return _sn[k[0]].tot>0; }).map(function(k){ return _sn[k[0]].tot+" "+k[1].toLowerCase(); });
      if(_snParts.length) line("Supporti microfonici: "+_snParts.join(" · "), 10, false, null, 5);
    }catch(_e){}
    if(R.snakes && R.snakes.length) line("Digital snake (home-run al punto principale): "+R.snakes.map(function(k){ return k.box.letter+" "+k.lenM.toFixed(0)+" m"; }).join(", "), 10, false, null, 5);
    /* L5 — sezione rete/dati: tratte digitali con protocollo, mezzo e lunghezza sul percorso reale */
    var N=netEngine();
    if(N.runs.length){
      y+=4; line("Rete audio", 12, true, "#4f46e5", 6);
      N.runs.forEach(function(r){
        line("Box "+r.box.letter+" -> "+(R.home?R.home.name:"FOH")+":  "+AUDIO_PROTO[r.proto]+" · "+r.medium+" · "+r.lenM.toFixed(0)+" m  ("+r.box.used+" ch"+(r.spec.redundant?", ridondanza consigliata":"")+")", 9.5, false, null, 4.8);
      });
      N.issues.forEach(function(i){ line("• "+i.msg, 9, i.lvl==="err", i.lvl==="err"?"#dc2626":(i.lvl==="warn"?"#b45309":"#6b7280"), 4.6); });
    }
    y+=4;
    line("Dettaglio collegamenti", 12, true, "#0d9488", 6);
    R.links.forEach(function(l){ if(l.deleted) return;
      line((l.s.name||l.label)+"  ->  Box "+l.box.letter+" ch "+l.ch+"  ->  "+(l.cut?"XLR "+l.cut+" m":"oltre 50 m!")+"   ("+l.s.mic+(l.manual?", percorso manuale":"")+", "+l.lenM.toFixed(1)+" m)", 9, false, l.cut?null:"#dc2626", 4.6);
    });
    R.links.filter(function(l){ return l.deleted; }).forEach(function(l){ line(l.s.name+"  ->  cavo rimosso manualmente", 9, false, "#9ca3af", 4.6); });
    R.unassigned.forEach(function(u){ line(u.name+"  ->  SENZA DESTINAZIONE (canali esauriti)", 9, true, "#dc2626", 4.6); });
    y+=4;
    line("Criticità", 12, true, "#0d9488", 6);
    if(R.issues.length) R.issues.forEach(function(i){ line("• "+i.msg, 9, i.lvl==="err", i.lvl==="err"?"#dc2626":(i.lvl==="warn"?"#b45309":"#6b7280"), 4.6); });
    else line("Nessuna criticità rilevata.", 10, false, "#0d9488", 5);
    if(shared) return;
    pdfCredit(doc);
    if(window.__cabPdfTest){ window.__cabPdfTest={name:fileName()+"-cablaggio-audio.pdf", pages:doc.getNumberOfPages()}; return; }   /* hook di test: niente download */
    pdfSave(doc, fileName()+"-cablaggio-audio.pdf");
  };
  if(shared){ run(shared); return; }
  loadJsPDF().then(function(){ run(new window.jspdf.jsPDF({orientation:"portrait", unit:"mm", format:"a4", compress:true})); }).catch(function(err){ alert("Librerie PDF non disponibili: "+err.message); });
}
/* Input list PDF: tabella numerata #/sorgente/mic·DI/patch (stessa fonte del pannello) */
function patchListPdf(shared){
  var pl=patchList(); if(!pl.rows.length){ if(!shared) alert("Nessun ingresso audio sul palco."); return; }
  var R=pl.R;
  var run=function(doc){
    if(shared) doc.addPage("a4","portrait");
    var M=16, y=22, cols=[M, M+10, M+62, M+100, M+136, M+158];   /* #, SORGENTE, FOH, MIC/DI, ASTA, PATCH */
    doc.setFillColor("#0d9488"); doc.rect(0,0,210,14,"F");
    doc.setTextColor("#ffffff"); doc.setFont("helvetica","bold"); doc.setFontSize(11); doc.text("STAGE PLOT — Input list", M, 9);
    doc.setFont("helvetica","normal"); doc.setFontSize(9); doc.text(new Date().toLocaleDateString("it-IT"), 194, 9, {align:"right"});
    if(state.titolo||state.luogo){ doc.setTextColor("#111827"); doc.setFont("helvetica","bold"); doc.setFontSize(12); doc.text((state.titolo||"")+(state.luogo?" — "+state.luogo:""), M, y); y+=8; }
    doc.setFont("helvetica","normal"); doc.setFontSize(9.5); doc.setTextColor("#555555");
    if(R.mixer&&MIXER_DB[R.mixer]) { doc.text("Mixer: "+hwLabel(R.mixer,MIXER_DB), M, y); y+=5; }
    doc.text(R.boxes.length ? "Stage box: "+R.boxes.map(function(b){ return b.letter+" "+(b.hw&&STAGEBOX_DB[b.hw]?STAGEBOX_DB[b.hw].model:b.cap+"ch")+(b.auto?" (auto)":""); }).join("  ·  ") : "Nessuna stage box dichiarata: il patch lo assegna il service", M, y); y+=8;
    /* Il buco si vede nella SUA cella — il patch — e la riga resta nera. Prima un canale senza stage
       box dipingeva di rosso l'intera riga: su una band appena creata (stage box quasi mai dichiarata)
       TUTTA la input list usciva rossa, e chi la riceveva leggeva «errore» su dati giusti (23/08). */
    function trow(a,b,c,d,e,f,bold,color,lastColor){ if(y>286){ doc.addPage(); y=18; } doc.setFont("helvetica", bold?"bold":"normal"); doc.setFontSize(9); doc.setTextColor(color||"#111827");
      doc.text(String(a),cols[0],y); doc.text(String(b),cols[1],y); doc.text(String(c),cols[2],y); doc.text(String(d),cols[3],y); doc.text(String(e),cols[4],y);
      doc.setTextColor(lastColor||color||"#111827"); doc.text(String(f),cols[5],y); y+=5.4; }
    trow("#","SORGENTE","FOH","MIC / DI","ASTA","PATCH", true, "#0d9488");
    doc.setDrawColor("#0d9488"); doc.setLineWidth(0.4); doc.line(M, y-3.6, 194, y-3.6);
    pl.rows.forEach(function(r){ trow((pl.hasFoh&&r.foh)?r.foh:r.n, r.reserved?"RISERVATO":r.name, r.short||"", r.reserved?"":(r.mic+(r.p48?"  (48V)":"")), r.standShared?"stessa asta":(r.stand||""), r.patch, false, (r.spare||r.reserved)?"#9a948b":"#111827", (r.spare||r.reserved||r.box)?null:"#b45309"); });
    /* F2: riepilogo riservate/libere per box (spare = porte, non righe fantasma — D2) */
    try{ cabResult().boxes.forEach(function(b){
      if(!b.res.length) return;
      var u2=Object.keys(b.taken).length;
      trow("", (b.sbId?("ID"+b.sbId):b.letter)+(b.fohBase!=null?"  ·  FOH "+(b.fohBase+1)+"-"+(b.fohBase+b.cap):""), "", u2+" in uso · "+b.res.length+" riservate", "", "", false, "#9a948b");
    }); }catch(_e){}
    if(shared) return;
    pdfCredit(doc);
    if(window.__patchPdfTest){ window.__patchPdfTest={name:fileName()+"-input-list.pdf", pages:doc.getNumberOfPages(), rows:pl.rows.length}; return; }
    pdfSave(doc, fileName()+"-input-list.pdf");
  };
  if(shared){ run(shared); return; }
  loadJsPDF().then(function(){ run(new window.jspdf.jsPDF({orientation:"portrait", unit:"mm", format:"a4", compress:true})); }).catch(function(err){ alert("Librerie PDF non disponibili: "+err.message); });
}
/* T2 — Rider tecnico PDF: pagina di testo con i numeri DERIVATI (microfoni/monitor/pedane/console) + le
   sezioni editabili (sistema audio/luci/personale). Stessa forma delle altre pagine-lista (shared=doc). */
/* PRODUZIONE (fase 4): ultima pagina del rider — "Criticità e aspetti da definire" (brief §2/§11).
   Distingue: errori tecnici · informazioni mancanti · sistemi delegati · aspetti consapevolmente da
   definire. Non inventa nulla: solo audit findings + risposte del Controllo tecnico. */
function todefinePdf(shared){
  var A=auditEngine();
  var errs=A.findings.filter(function(x){return x.lvl==="err";});
  var warns=A.findings.filter(function(x){return x.lvl==="warn";});
  var todefs=A.findings.filter(function(x){return x.lvl==="todef";});
  var deleg=(typeof productionSummary==="function")?productionSummary(state).filter(function(r){return ["venue","service","produzione"].indexOf((state.production.systems[r.key]||{}).ans)>=0;}):[];
  var run=function(doc){
    if(shared) doc.addPage("a4","portrait");
    var M=16, W=210, y=22;
    doc.setFillColor("#475569"); doc.rect(0,0,W,14,"F");
    doc.setTextColor("#ffffff"); doc.setFont("helvetica","bold"); doc.setFontSize(11); doc.text("STAGE PLOT — Criticità e aspetti da definire", M, 9);
    doc.setFont("helvetica","normal"); doc.setFontSize(9); doc.text(new Date().toLocaleDateString("it-IT"), 194, 9, {align:"right"});
    function heading(t,col){ if(y>272){ doc.addPage(); y=18; } doc.setFont("helvetica","bold"); doc.setFontSize(10.5); doc.setTextColor(col||"#475569"); doc.text(t, M, y); y+=5.4; doc.setTextColor("#111827"); }
    function body(t){ doc.setFont("helvetica","normal"); doc.setFontSize(9.5); var lines=doc.splitTextToSize(String(t==null||t===""?"—":t), W-2*M);
      lines.forEach(function(ln){ if(y>286){ doc.addPage(); y=18; } doc.text(ln, M, y); y+=4.8; }); y+=2.2; }
    if(errs.length){ heading("ERRORI TECNICI","#dc2626"); errs.forEach(function(x){ body("• "+x.msg+(x.fix?(" → "+x.fix):"")); }); y+=2; }
    if(warns.length){ heading("INFORMAZIONI MANCANTI O INCOERENTI","#b45309"); warns.forEach(function(x){ body("• "+x.msg); }); y+=2; }
    if(deleg.length){ heading("SISTEMI DELEGATI","#0d9488"); deleg.forEach(function(r){ body("• "+r.label+": "+r.text+"."); }); y+=2; }
    if(todefs.length){ heading("ASPETTI CONSAPEVOLMENTE DA DEFINIRE","#2563eb"); todefs.forEach(function(x){ body("• "+x.msg); }); }
    if(!errs.length && !warns.length && !deleg.length && !todefs.length){ body("Nessuna criticità o aspetto aperto."); }
    if(shared) return;
    pdfCredit(doc);
    pdfSave(doc, fileName()+"-da-definire.pdf");
  };
  if(shared){ run(shared); return; }
  loadJsPDF().then(function(){ run(new window.jspdf.jsPDF({orientation:"portrait", unit:"mm", format:"a4", compress:true})); }).catch(function(err){ alert("Librerie PDF non disponibili: "+err.message); });
}
/* Decisione 5A: pagina "Responsabilità" del rider — reparto → azienda (pubblici), + referenti
   che l'utente ha pubblicato esplicitamente (opt-in). Persone non pubblicate restano nell'account. */
function responsabilitaPdf(shared){
  var rd=window.currentRespData?window.currentRespData():null;
  if(!rd || !rd.assigns){ if(!shared) alert("Nessuna responsabilità assegnata (assegnala in File → Produzione)."); return; }
  var deps=(typeof productionDepts==="function")?productionDepts():[];
  var byId={}; (rd.rubrica||[]).forEach(function(c){ byId[c.id]=c; });
  var rows=[];
  deps.forEach(function(d){
    var list=rd.assigns[d.key]||[];
    var az=list.filter(function(a){ return a.role==="__azienda__"; })[0];
    var pubs=list.filter(function(a){ return a.role!=="__azienda__" && a.published; });
    if(!az && !pubs.length) return;
    rows.push({ rep:d.name, az: az&&byId[az.contact_id]?byId[az.contact_id].name:"—",
      ref: pubs.map(function(a){ var c=byId[a.contact_id]||{}; return (c.name||"")+(a.role?" ("+a.role+")":"")+(c.contact?" · "+c.contact:""); }).join("   ·   ") });
  });
  if(!rows.length){ if(!shared) alert("Nessuna azienda assegnata ai reparti."); return; }
  var run=function(doc){
    if(shared) doc.addPage("a4","portrait");
    var M=16, y=22, cols=[M, M+50, M+118];
    doc.setFillColor("#0d9488"); doc.rect(0,0,210,14,"F");
    doc.setTextColor("#ffffff"); doc.setFont("helvetica","bold"); doc.setFontSize(11); doc.text("STAGE PLOT — Responsabilità", M, 9);
    doc.setFont("helvetica","normal"); doc.setFontSize(9); doc.text(new Date().toLocaleDateString("it-IT"), 194, 9, {align:"right"});
    if(state.titolo||state.luogo){ doc.setTextColor("#111827"); doc.setFont("helvetica","bold"); doc.setFontSize(12); doc.text((state.titolo||"")+(state.luogo?" — "+state.luogo:""), M, y); y+=8; }
    function trow(a,b,c,bold,color){ if(y>286){ doc.addPage(); y=18; } doc.setFont("helvetica", bold?"bold":"normal"); doc.setFontSize(9.5); doc.setTextColor(color||"#111827"); doc.text(String(a),cols[0],y); doc.text(String(b),cols[1],y); doc.text(String(c),cols[2],y); y+=5.8; }
    trow("REPARTO","AZIENDA / SERVICE","REFERENTE (se pubblicato)", true, "#0b7a70");
    doc.setDrawColor("#0d9488"); doc.setLineWidth(0.4); doc.line(M, y-3.8, 194, y-3.8);
    rows.forEach(function(r){ trow(r.rep, r.az, r.ref||"—", false, "#111827"); });
    y+=4;
    doc.setFont("helvetica","normal"); doc.setFontSize(8.5); doc.setTextColor("#9a948b");
    doc.text("I contatti personali non pubblicati restano privati e non compaiono su questo documento.", M, y);
    if(shared) return;
    pdfCredit(doc);
    pdfSave(doc, fileName()+"-responsabilita.pdf");
  };
  if(shared){ run(shared); return; }
  loadJsPDF().then(function(){ run(new window.jspdf.jsPDF({orientation:"portrait", unit:"mm", format:"a4", compress:true})); }).catch(function(err){ alert("Librerie PDF non disponibili: "+err.message); });
}
function riderPdf(shared){
  var d=riderData();
  var run=function(doc){
    if(shared) doc.addPage("a4","portrait");
    var M=16, W=210, y=22;
    doc.setFillColor("#4338ca"); doc.rect(0,0,W,14,"F");
    doc.setTextColor("#ffffff"); doc.setFont("helvetica","bold"); doc.setFontSize(11); doc.text("STAGE PLOT — Rider tecnico", M, 9);
    doc.setFont("helvetica","normal"); doc.setFontSize(9); doc.text(new Date().toLocaleDateString("it-IT"), 194, 9, {align:"right"});
    if(d.titolo){ doc.setTextColor("#111827"); doc.setFont("helvetica","bold"); doc.setFontSize(12); doc.text(d.titolo+(d.luogo?" — "+d.luogo:""), M, y); y+=7; }
    (function(){ var si=statusInfo(d.status); var sign=(d.status==="approvato" && (d.approvedBy||d.approvedAt)) ? "  ·  firmato"+(d.approvedBy?" da "+d.approvedBy:"")+(d.approvedAt?" il "+new Date(d.approvedAt).toLocaleDateString("it-IT"):"") : "";
      doc.setFont("helvetica","bold"); doc.setFontSize(9); doc.setTextColor(si.color); doc.text(si.label.toUpperCase()+sign, M, y); y+=7; doc.setTextColor("#111827"); })();
    function heading(t){ if(y>272){ doc.addPage(); y=18; } doc.setFont("helvetica","bold"); doc.setFontSize(10.5); doc.setTextColor("#4338ca"); doc.text(t, M, y); y+=5.4; doc.setTextColor("#111827"); }
    function body(t){ doc.setFont("helvetica","normal"); doc.setFontSize(9.5); var lines=doc.splitTextToSize(String(t==null||t===""?"—":t), W-2*M);
      lines.forEach(function(ln){ if(y>286){ doc.addPage(); y=18; } doc.text(ln, M, y); y+=4.8; }); y+=3.2; }
    heading("MICROFONI"); body(d.inCh+" canali di ingresso · "+d.outCh+" canali di uscita (monitor)"+(d.boxes.length?" · Stage box: "+d.boxes.join(", "):""));
    (function(){ var D=riderDotazione(); if(D.testo) body(D.testo); if(D.aste) body("Aste: "+D.aste); })();   /* la dotazione per modello, come nei rider veri */
    heading("MONITOR"); body(riderMonitorText(d.monitor));
    heading("STAGE E PEDANE"); body(riderPedaneText(d.pedane)+(d.sedie?" · "+d.sedie+" sedie da orchestra senza braccioli":"")+(d.pesoKg>0?" · peso allestimento stimato "+fmtKg(d.pesoKg):""));
    if(d.console){ heading("CONSOLE"); body(d.console); }
    if(d.elettrico){ heading("ALIMENTAZIONE"); body(riderAlimentazioneText(d.elettrico)); }   /* mancava nel PDF: c'era solo nell'anteprima HTML */
    heading("SISTEMA AUDIO"); body(d.sistema);
    heading("LUCI"); body(d.luci);
    (function(){ var pm=(typeof productionSummary==="function")?productionSummary(state).filter(function(r){return r.key!=="luci";}):[];
      if(pm.length){ heading("PRODUZIONE E MEDIA"); pm.forEach(function(r){ body(r.label+": "+r.text); }); } })();
    heading("PERSONALE RICHIESTO AL SERVICE"); body(d.personale);
    if(d.note){ heading("NOTE"); body(d.note); }
    if(d.contatti.length){ heading("CONTATTI E RUOLI"); d.contatti.forEach(function(c){
        var head=[c.role||"—", c.name].filter(Boolean).join(" · ");
        /* SOLO ruolo, nome e recapito: la NOTA del contatto è un appunto interno del tecnico
           («non risponde mai, chiama la moglie») e non deve finire nel PDF che si manda al locale. */
        body(head+(c.contact?" — "+c.contact:"")); }); }
    else if(d.contatto){ if(y>282){ doc.addPage(); y=18; } doc.setFont("helvetica","italic"); doc.setFontSize(9); doc.setTextColor("#374151"); doc.text("Riferimento tecnico: "+d.contatto, M, y); y+=5; }
    if(shared) return;
    pdfCredit(doc);
    pdfSave(doc, fileName()+"-rider.pdf");
  };
  if(shared){ run(shared); return; }
  loadJsPDF().then(function(){ run(new window.jspdf.jsPDF({orientation:"portrait", unit:"mm", format:"a4", compress:true})); }).catch(function(err){ alert("Librerie PDF non disponibili: "+err.message); });
}
