/* ===== Backline list auto (discovery pro #3): l'attrezzatura fisica che qualcuno deve portare al palco
   (ampli, piani, tastiere, chitarre, batteria…), con "chi la fornisce" per riga. Il service legge cosa
   deve procurare (righe Service), la band cosa porta lei. Auto-derivata dagli elementi sul palco. ===== */
var BACKLINE_EXTRA={ batteria:1, edrums:1, percussioni:1, timbales:1 };   /* strumenti-backline fuori dalla categoria "Band e backline" */
function isBackline(it){ var t=TYPES[it.type]; if(!t) return false; return t.cat==="Band e backline" || !!BACKLINE_EXTRA[it.type]; }
function backlineList(){
  var groups={}, order=[];
  (state.items||[]).forEach(function(it){
    if(!isBackline(it)) return;
    var t=TYPES[it.type];
    var name=(it.label && it.label.trim()) ? it.label.trim() : (t?t.nome:it.type);   /* label custom (es. modello) o nome tipo */
    var by=(it.by==="Band"||it.by==="Service")?it.by:"";
    var k=name+"|"+by;
    if(!groups[k]){ groups[k]={name:name, by:by, qty:0}; order.push(k); }
    groups[k].qty++;
  });
  var rows=order.map(function(k){ return groups[k]; });
  rows.sort(function(a,b){ return a.name.localeCompare(b.name,"it") || a.by.localeCompare(b.by); });
  var byService=rows.filter(function(r){ return r.by==="Service"; }).reduce(function(s,r){ return s+r.qty; },0);
  return { rows:rows, count:rows.length, totItems:rows.reduce(function(s,r){return s+r.qty;},0), byService:byService };
}
/* LISTA NOTE (30/07): le note scritte sui singoli elementi, raccolte in una pagina sola. Sul disegno
   c'è il puntino, qui c'è cosa dice. Ordine: quello del palco, che è l'ordine in cui uno le incontra. */
function noteList(){
  var rows=[];
  (state.items||[]).forEach(function(it){
    var n=noteOf(it); if(!n) return;
    var t=TYPES[it.type]||{};
    rows.push({ name:(it.label && it.label.trim()) ? it.label.trim() : (t.nome||it.type), tipo:t.nome||it.type, note:n });
  });
  return { rows:rows, count:rows.length };
}
